-- CLI-generated migration, ordered after the existing future-dated baseline.
-- Apply before deploying the corresponding Edge Function. No POS/COA changes.
begin;
alter table public.subscriptions
  add column midtrans_amount_idr integer,
  add column midtrans_duration_days integer,
  add column paid_at timestamptz,
  add column provider_checked_at timestamptz;
alter table public.subscriptions
  add constraint midtrans_amount_positive check (midtrans_amount_idr is null or midtrans_amount_idr > 0),
  add constraint midtrans_duration_positive check (midtrans_duration_days is null or midtrans_duration_days > 0);

-- No guessed payment snapshots for legacy pending orders: reconciliation rejects
-- them until the operator verifies their original amount/duration with Midtrans.
-- Existing paid orders retain their period; a repeat notification cannot extend it.
update public.subscriptions set paid_at = created_at
where payment_provider = 'midtrans' and status in ('active', 'past_due');
update public.subscriptions set status = 'expired', auto_renewing = false
where payment_provider = 'midtrans' and status = 'cancelled';

create or replace function public.apply_midtrans_payment(
  p_sub_id uuid, p_status text, p_transaction_id text,
  p_amount numeric, p_order_id text, p_checked_at timestamptz
) returns text language plpgsql security invoker set search_path = '' as $$
declare
  s public.subscriptions;
  owner_id uuid;
  start_at timestamptz;
  end_at timestamptz;
begin
  if p_status not in ('pending','active','cancelled','expired') or p_checked_at is null then
    raise exception 'invalid_payment_state';
  end if;
  select user_id into strict owner_id from public.subscriptions where sub_id = p_sub_id;
  perform pg_advisory_xact_lock(hashtextextended(owner_id::text, 17));
  select * into strict s from public.subscriptions where sub_id = p_sub_id for update;
  if s.payment_provider <> 'midtrans' or s.midtrans_order_id is distinct from p_order_id then
    raise exception 'payment_order_mismatch';
  end if;
  if s.provider_checked_at is not null and p_checked_at <= s.provider_checked_at then return s.status; end if;
  if s.midtrans_amount_idr is null or s.midtrans_duration_days is null then
    raise exception 'legacy_order_requires_verified_snapshot';
  end if;
  if p_amount is null or p_amount <> s.midtrans_amount_idr then raise exception 'payment_amount_mismatch'; end if;
  if p_transaction_id is null or length(p_transaction_id) = 0 then raise exception 'missing_transaction_id'; end if;
  if s.midtrans_transaction_id is not null and s.midtrans_transaction_id <> p_transaction_id then
    raise exception 'payment_transaction_mismatch';
  end if;
  if p_status = 'active' then
    if s.paid_at is null then
      -- Serialize all purchases for this user; extend only the same paid plan
      -- on this rail. Unpaid cancelled orders and Play plans never add time.
      select greatest(now(), coalesce(max(current_period_end), now())) into start_at
      from public.subscriptions
      where user_id = owner_id and sub_id <> p_sub_id
        and payment_provider = 'midtrans' and plan_id = s.plan_id
        and paid_at is not null and status in ('active','past_due');
      end_at := start_at + make_interval(days => s.midtrans_duration_days);
      update public.subscriptions set status = 'active', paid_at = now(),
        current_period_start = start_at, current_period_end = end_at,
        grace_period_end = end_at + interval '3 days', auto_renewing = false,
        cancelled_at = null, midtrans_transaction_id = p_transaction_id,
        provider_checked_at = p_checked_at where sub_id = p_sub_id;
      return 'active';
    end if;
    -- A previously paid/refunded/expired order never buys another period.
    return s.status;
  end if;
  -- Late pending notifications must not roll a successful payment backwards.
  if p_status = 'pending' and s.paid_at is not null then return s.status; end if;
  update public.subscriptions set status = case when p_status = 'cancelled' then 'expired' else p_status end,
    midtrans_transaction_id = p_transaction_id, provider_checked_at = p_checked_at,
    auto_renewing = false where sub_id = p_sub_id;
  return case when p_status = 'cancelled' then 'expired' else p_status end;
end $$;
revoke all on function public.apply_midtrans_payment(uuid,text,text,numeric,text,timestamptz) from public, anon, authenticated;
grant execute on function public.apply_midtrans_payment(uuid,text,text,numeric,text,timestamptz) to service_role;

create or replace function public.apply_play_subscription(
  p_user_id uuid, p_token text, p_plan_id text, p_state jsonb,
  p_checked_at timestamptz, p_linked_token text default null
) returns uuid language plpgsql security invoker set search_path = '' as $$
declare
  result_id uuid;
  owner_id uuid;
begin
  if p_checked_at is null then raise exception 'missing_provider_check_time'; end if;
  -- User lock serializes linked-token replacement; unique token handles
  -- competing users atomically through the conflict predicate below.
  perform pg_advisory_xact_lock(hashtextextended(p_user_id::text, 18));
  if p_linked_token is not null then
    select user_id into owner_id from public.subscriptions where play_purchase_token = p_linked_token;
    if owner_id is not null and owner_id <> p_user_id then raise exception 'linked_token_owner_mismatch'; end if;
  end if;
  insert into public.subscriptions as existing (
    user_id, plan_id, status, payment_provider, play_purchase_token, play_order_id,
    current_period_start, current_period_end, grace_period_end, auto_renewing, provider_checked_at
  ) values (
    p_user_id, p_plan_id, p_state->>'status', 'play_billing', p_token, p_state->>'playOrderId',
    (p_state->>'currentPeriodStart')::timestamptz, (p_state->>'currentPeriodEnd')::timestamptz,
    (p_state->>'currentPeriodEnd')::timestamptz, (p_state->>'autoRenewing')::boolean, p_checked_at
  ) on conflict (play_purchase_token) do update set
    plan_id = excluded.plan_id, status = excluded.status, play_order_id = excluded.play_order_id,
    current_period_start = excluded.current_period_start, current_period_end = excluded.current_period_end,
    grace_period_end = excluded.grace_period_end, auto_renewing = excluded.auto_renewing,
    provider_checked_at = excluded.provider_checked_at
  where existing.user_id = p_user_id
    and (existing.provider_checked_at is null or existing.provider_checked_at < p_checked_at)
  returning sub_id into result_id;
  if result_id is null then
    select sub_id into result_id from public.subscriptions where play_purchase_token = p_token and user_id = p_user_id;
    if result_id is null then raise exception 'purchase_token_already_bound'; end if;
    return result_id;
  end if;
  if p_linked_token is not null and p_state->>'status' in ('active','past_due','cancelled') then
    update public.subscriptions set status = 'expired', auto_renewing = false
    where play_purchase_token = p_linked_token and user_id = p_user_id and sub_id <> result_id;
  end if;
  return result_id;
end $$;
revoke all on function public.apply_play_subscription(uuid,text,text,jsonb,timestamptz,text) from public, anon, authenticated;
grant execute on function public.apply_play_subscription(uuid,text,text,jsonb,timestamptz,text) to service_role;

-- Replace the original reconciler: never manufacture Play grace or resurrect
-- cancelled, unpaid Midtrans orders. Access checks also enforce time directly.
create or replace function public.reconcile_subscription_expiry()
returns jsonb language plpgsql security invoker set search_path = '' as $$
declare v_past_due integer; v_expired integer;
begin
  update public.subscriptions set status = 'past_due'
  where payment_provider = 'midtrans' and paid_at is not null and status = 'active'
    and now() >= current_period_end and now() < grace_period_end;
  get diagnostics v_past_due = row_count;
  update public.subscriptions set status = 'expired', auto_renewing = false
  where status in ('pending','active','past_due','cancelled') and (
    (payment_provider = 'play_billing' and now() >= current_period_end) or
    (payment_provider = 'midtrans' and (status = 'cancelled' or now() >= coalesce(grace_period_end,current_period_end)))
  );
  get diagnostics v_expired = row_count;
  return jsonb_build_object('past_due',v_past_due,'expired',v_expired);
end $$;
revoke all on function public.reconcile_subscription_expiry() from public, anon, authenticated;
grant execute on function public.reconcile_subscription_expiry() to service_role;
-- Explicit privileges support projects without automatic public-schema grants.
grant select, insert, update on public.subscriptions to service_role;
grant select, insert on public.subscription_events to service_role;
grant select on public.plans to service_role;
commit;

-- Advisor hardening for the isolated subscription staging schema.
-- No POS/COA tables are touched.
begin;

alter function public.set_updated_at() set search_path = public;

create index if not exists idx_subscriptions_plan_id
  on public.subscriptions(plan_id);

commit;

