set search_path = ''
as $$
  select decrypted_secret
  from vault.decrypted_secrets
  where name = 'berkahtigaputeri_license_private_key'
  order by updated_at desc
  limit 1
$$;

revoke all on function public.get_license_private_key() from public;
revoke all on function public.get_license_private_key() from anon;
revoke all on function public.get_license_private_key() from authenticated;
grant execute on function public.get_license_private_key() to service_role;

commit;

revoke all privileges on table public.subscriptions from anon, authenticated;
revoke all privileges on table public.subscription_events from anon, authenticated;
revoke all privileges on table public.devices from anon, authenticated;

revoke all privileges on table public.plans from anon, authenticated;
