-- ---------------------------------------------------------------------------
-- Tenant boundary and membership.
-- Financial records survive Auth account deletion; actor/owner subject strings
-- retain audit provenance while nullable auth FKs can be cleared.
-- ---------------------------------------------------------------------------
create table public.accounting_tenants (
  tenant_id uuid primary key default gen_random_uuid(),
  name text not null check (length(btrim(name)) between 1 and 120),
  owner_user_id uuid references auth.users(id) on delete set null,
  owner_subject text not null,
  status text not null default 'active' check (status in ('active','suspended')),
  created_at timestamptz not null default now()
);

create table public.accounting_memberships (
  tenant_id uuid not null references public.accounting_tenants(tenant_id) on delete restrict,
  user_id uuid not null references auth.users(id) on delete cascade,
  role text not null check (role in ('owner','admin','accountant','cashier')),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  primary key (tenant_id, user_id)
);

create index accounting_memberships_user_idx
  on public.accounting_memberships(user_id, tenant_id)
  where is_active;

-- ---------------------------------------------------------------------------
-- Accounting periods. Absence of a row means open. A closed period rejects
-- new posting. Reopen is an explicit privileged action and is audited.
-- ---------------------------------------------------------------------------
create table public.accounting_periods (
  period_id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.accounting_tenants(tenant_id) on delete restrict,
  period_start date not null,
  period_end date not null,
  status text not null check (status in ('open','closed')),
  close_reason text,
  closed_at timestamptz,
  closed_by uuid references auth.users(id) on delete set null,
  closed_subject text,
  reopen_reason text,
  reopened_at timestamptz,
  reopened_by uuid references auth.users(id) on delete set null,
  reopened_subject text,
  created_at timestamptz not null default now(),
  constraint accounting_period_dates check (period_end >= period_start),
  constraint accounting_period_unique unique (tenant_id, period_start, period_end)
);

create index accounting_periods_tenant_dates_idx
  on public.accounting_periods(tenant_id, period_start, period_end, status);

-- ---------------------------------------------------------------------------
-- Posted journal and lines. Posted rows are append-only.
-- request_fingerprint is compared exactly for idempotent retry semantics.
-- write_txid prevents lines being appended after the journal creation tx.
-- ---------------------------------------------------------------------------
create table public.accounting_journals (
  journal_id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.accounting_tenants(tenant_id) on delete restrict,
  idempotency_key text not null,
  request_fingerprint jsonb not null,
  transaction_ref text not null,
  journal_date date not null,
  description text not null default '',
  source_type text not null check (
    source_type in ('pos_sale','sale_return','shift_close','manual','reversal')
  ),
  reversal_of uuid references public.accounting_journals(journal_id) on delete restrict,
  total_debit bigint not null check (total_debit > 0),
  total_credit bigint not null check (total_credit > 0),
  actor_user_id uuid references auth.users(id) on delete set null,
  actor_subject text not null,
  device_id text not null,
  app_version text not null,
  posted_at timestamptz not null default now(),
  write_txid bigint not null default txid_current(),
  constraint accounting_journal_balanced_summary check (total_debit = total_credit),
  constraint accounting_journal_reversal_shape check (
    (source_type = 'reversal' and reversal_of is not null)
    or (source_type <> 'reversal' and reversal_of is null)
  ),
  constraint accounting_journal_tenant_idempotency unique (tenant_id, idempotency_key),
  constraint accounting_journal_id_tenant_unique unique (journal_id, tenant_id)
);

create unique index accounting_one_reversal_per_journal_idx
  on public.accounting_journals(reversal_of)
  where reversal_of is not null;

create index accounting_journals_tenant_date_idx
  on public.accounting_journals(tenant_id, journal_date, posted_at);

create index accounting_journals_transaction_ref_idx
  on public.accounting_journals(tenant_id, transaction_ref);

create table public.accounting_journal_lines (
  line_id bigint generated always as identity primary key,
  journal_id uuid not null,
  tenant_id uuid not null,
  line_no integer not null check (line_no > 0),
  account_code text not null references public.accounting_coa(account_code),
  debit bigint not null default 0 check (debit >= 0),
  credit bigint not null default 0 check (credit >= 0),
  memo text not null default '',
  created_at timestamptz not null default now(),
  constraint accounting_line_one_side check (
    (debit > 0 and credit = 0) or (credit > 0 and debit = 0)
  ),
  constraint accounting_line_unique_no unique (journal_id, line_no),
  constraint accounting_line_journal_tenant_fk
    foreign key (journal_id, tenant_id)
    references public.accounting_journals(journal_id, tenant_id)
    on delete restrict
);

create index accounting_journal_lines_tenant_idx
  on public.accounting_journal_lines(tenant_id, journal_id);

-- ---------------------------------------------------------------------------
-- Immutable accounting event stream.
-- ---------------------------------------------------------------------------
create table public.accounting_events (
  event_id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.accounting_tenants(tenant_id) on delete restrict,
  event_type text not null,
  event_key text not null,
  journal_id uuid references public.accounting_journals(journal_id) on delete restrict,
  entity_type text not null,
  entity_id text not null,
  actor_user_id uuid references auth.users(id) on delete set null,
  actor_subject text not null,
  device_id text not null,
  app_version text not null,
  details jsonb not null default '{}'::jsonb,
  occurred_at timestamptz not null default now(),
  constraint accounting_event_key_unique unique (tenant_id, event_key)
);

create index accounting_events_tenant_time_idx
  on public.accounting_events(tenant_id, occurred_at desc);

-- ---------------------------------------------------------------------------
-- Integrity trigger functions.
-- ---------------------------------------------------------------------------
create or replace function accounting_private.reject_mutation()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  raise exception using errcode = '55000', message = 'immutable_accounting_record';
end;
$$;

create or replace function accounting_private.reject_locked_coa_insert()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  raise exception using errcode = '55000', message = 'locked_coa_contract';
end;
$$;

create or replace function accounting_private.guard_line_creation_tx()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_txid bigint;
begin
  select j.write_txid into v_txid
  from public.accounting_journals j
  where j.journal_id = new.journal_id
    and j.tenant_id = new.tenant_id;

  if v_txid is null then
    raise exception using errcode = '23503', message = 'journal_not_found';
  end if;
  if v_txid <> txid_current() then
    raise exception using errcode = '55000', message = 'immutable_posted_journal';
  end if;
  return new;
end;
$$;

create or replace function accounting_private.assert_journal_balanced()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_journal_id uuid;
  v_expected_debit bigint;
  v_expected_credit bigint;
  v_debit numeric;
  v_credit numeric;
  v_count bigint;
begin
  v_journal_id := coalesce(new.journal_id, old.journal_id);

  select j.total_debit, j.total_credit
    into v_expected_debit, v_expected_credit
  from public.accounting_journals j
  where j.journal_id = v_journal_id;

  if not found then
    return null;
  end if;

  select coalesce(sum(l.debit),0), coalesce(sum(l.credit),0), count(*)
    into v_debit, v_credit, v_count
  from public.accounting_journal_lines l
  where l.journal_id = v_journal_id;

  if v_count < 2
     or v_debit <= 0
     or v_debit <> v_credit
     or v_debit <> v_expected_debit
     or v_credit <> v_expected_credit then
    raise exception using errcode = '23514', message = 'journal_not_balanced';
  end if;

  return null;
end;
$$;

create trigger accounting_coa_no_insert
before insert on public.accounting_coa
for each row execute function accounting_private.reject_locked_coa_insert();

create trigger accounting_coa_no_mutation
before update or delete on public.accounting_coa
for each row execute function accounting_private.reject_mutation();

create trigger accounting_journals_no_mutation
before update or delete on public.accounting_journals
for each row execute function accounting_private.reject_mutation();

create trigger accounting_journal_lines_creation_tx
before insert on public.accounting_journal_lines
for each row execute function accounting_private.guard_line_creation_tx();

create trigger accounting_journal_lines_no_mutation
before update or delete on public.accounting_journal_lines
