-- ---------------------------------------------------------------------------
-- Shared authorization helpers. These are private and never trust client actor
-- parameters; auth.uid() is authoritative.
-- ---------------------------------------------------------------------------
create or replace function accounting_private.require_bound_device(
  p_actor uuid,
  p_device_id text,
  p_app_version text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_actor is null then
    raise exception using errcode = '28000', message = 'authentication_required';
  end if;
  if p_device_id is null or length(btrim(p_device_id)) = 0 then
    raise exception using errcode = '22023', message = 'device_id_required';
  end if;
  if p_app_version is null or length(btrim(p_app_version)) = 0 then
    raise exception using errcode = '22023', message = 'app_version_required';
  end if;
  if not exists (
    select 1 from public.devices d
    where d.device_id = p_device_id and d.user_id = p_actor
  ) then
    raise exception using errcode = '42501', message = 'device_not_bound_to_actor';
  end if;
end;
$$;

create or replace function accounting_private.require_member_role(
  p_tenant_id uuid,
  p_actor uuid,
  p_allowed_roles text[] default null
)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_role text;
begin
  select m.role into v_role
  from public.accounting_memberships m
  join public.accounting_tenants t on t.tenant_id = m.tenant_id
  where m.tenant_id = p_tenant_id
    and m.user_id = p_actor
    and m.is_active
    and t.status = 'active';

  if v_role is null then
    raise exception using errcode = '42501', message = 'tenant_access_denied';
  end if;
  if p_allowed_roles is not null and not (v_role = any(p_allowed_roles)) then
    raise exception using errcode = '42501', message = 'accounting_role_denied';
  end if;
  return v_role;
end;
$$;

-- ---------------------------------------------------------------------------
-- Tenant creation.
-- ---------------------------------------------------------------------------
create or replace function accounting_private.create_tenant(
  p_name text,
  p_device_id text,
  p_app_version text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := auth.uid();
  v_tenant uuid;
begin
  perform accounting_private.require_bound_device(v_actor, p_device_id, p_app_version);
  if p_name is null or length(btrim(p_name)) not between 1 and 120 then
    raise exception using errcode = '22023', message = 'invalid_tenant_name';
  end if;

  insert into public.accounting_tenants(name, owner_user_id, owner_subject)
  values (btrim(p_name), v_actor, v_actor::text)
  returning tenant_id into v_tenant;

  insert into public.accounting_memberships(tenant_id, user_id, role)
  values (v_tenant, v_actor, 'owner');

  insert into public.accounting_events(
    tenant_id, event_type, event_key, entity_type, entity_id,
    actor_user_id, actor_subject, device_id, app_version, details
  ) values (
    v_tenant, 'tenant_created', 'tenant:' || v_tenant::text || ':created',
    'tenant', v_tenant::text,
    v_actor, v_actor::text, p_device_id, p_app_version,
    jsonb_build_object('name', btrim(p_name))
  );

  return v_tenant;
end;
$$;

-- ---------------------------------------------------------------------------
-- Atomic posting with exact retry fingerprint.
-- ---------------------------------------------------------------------------
create or replace function accounting_private.post_journal(
  p_tenant_id uuid,
  p_idempotency_key text,
  p_transaction_ref text,
  p_journal_date date,
  p_description text,
  p_source_type text,
  p_lines jsonb,
  p_device_id text,
  p_app_version text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := auth.uid();
  v_existing_id uuid;
  v_existing_fingerprint jsonb;
  v_fingerprint jsonb;
  v_journal_id uuid;
  v_line jsonb;
  v_line_no integer := 0;
  v_account_code text;
  v_debit_text text;
  v_credit_text text;
  v_memo text;
  v_debit numeric;
  v_credit numeric;
  v_total_debit numeric := 0;
  v_total_credit numeric := 0;
begin
  perform accounting_private.require_bound_device(v_actor, p_device_id, p_app_version);
  perform accounting_private.require_member_role(p_tenant_id, v_actor, null);

  if p_idempotency_key is null or length(btrim(p_idempotency_key)) not between 1 and 200 then
    raise exception using errcode = '22023', message = 'invalid_idempotency_key';
  end if;
  if p_transaction_ref is null or length(btrim(p_transaction_ref)) not between 1 and 200 then
    raise exception using errcode = '22023', message = 'invalid_transaction_ref';
  end if;
  if p_journal_date is null then
    raise exception using errcode = '22023', message = 'journal_date_required';
  end if;
  if p_source_type not in ('pos_sale','sale_return','shift_close','manual') then
    raise exception using errcode = '22023', message = 'invalid_source_type';
  end if;
  if p_description is not null and length(p_description) > 500 then
    raise exception using errcode = '22023', message = 'description_too_long';
  end if;
  if jsonb_typeof(p_lines) <> 'array'
     or jsonb_array_length(p_lines) < 2
     or jsonb_array_length(p_lines) > 100 then
    raise exception using errcode = '22023', message = 'invalid_journal_lines';
  end if;

  v_fingerprint := jsonb_build_object(
    'transaction_ref', btrim(p_transaction_ref),
    'journal_date', p_journal_date::text,
    'description', coalesce(p_description,''),
    'source_type', p_source_type,
    'lines', p_lines,
    'device_id', p_device_id,
    'app_version', p_app_version
  );

  perform pg_advisory_xact_lock(
    hashtextextended(p_tenant_id::text || ':' || btrim(p_idempotency_key), 411)
  );

  select j.journal_id, j.request_fingerprint
    into v_existing_id, v_existing_fingerprint
  from public.accounting_journals j
  where j.tenant_id = p_tenant_id
    and j.idempotency_key = btrim(p_idempotency_key);

  if v_existing_id is not null then
    if v_existing_fingerprint = v_fingerprint then
      return v_existing_id;
    end if;
    raise exception using errcode = '23505', message = 'idempotency_conflict';
  end if;

  if exists (
    select 1 from public.accounting_periods p
    where p.tenant_id = p_tenant_id
      and p.status = 'closed'
      and p_journal_date between p.period_start and p.period_end
  ) then
    raise exception using errcode = '55000', message = 'accounting_period_closed';
  end if;

  for v_line in select value from jsonb_array_elements(p_lines)
  loop
    v_line_no := v_line_no + 1;
    v_account_code := v_line->>'account_code';
    v_debit_text := coalesce(v_line->>'debit','0');
    v_credit_text := coalesce(v_line->>'credit','0');
    v_memo := coalesce(v_line->>'memo','');

    if v_account_code is null or not exists (
      select 1 from public.accounting_coa c where c.account_code = v_account_code
    ) then
      raise exception using errcode = '23503', message = 'unknown_account_code';
    end if;
    if v_debit_text !~ '^(0|[1-9][0-9]*)$'
       or v_credit_text !~ '^(0|[1-9][0-9]*)$' then
      raise exception using errcode = '22023', message = 'amount_must_be_integer_rupiah';
    end if;

    v_debit := v_debit_text::numeric;
    v_credit := v_credit_text::numeric;

    if (v_debit > 0 and v_credit > 0) or (v_debit = 0 and v_credit = 0) then
      raise exception using errcode = '23514', message = 'line_requires_one_side';
    end if;
    if v_debit > 9223372036854775807::numeric
       or v_credit > 9223372036854775807::numeric then
      raise exception using errcode = '22003', message = 'amount_out_of_range';
    end if;
    if length(v_memo) > 500 then
      raise exception using errcode = '22023', message = 'line_memo_too_long';
    end if;

    v_total_debit := v_total_debit + v_debit;
    v_total_credit := v_total_credit + v_credit;
  end loop;

  if v_total_debit <= 0 or v_total_debit <> v_total_credit then
    raise exception using errcode = '23514', message = 'journal_not_balanced';
  end if;
  if v_total_debit > 9223372036854775807::numeric then
    raise exception using errcode = '22003', message = 'journal_total_out_of_range';
  end if;

  insert into public.accounting_journals(
    tenant_id, idempotency_key, request_fingerprint, transaction_ref,
    journal_date, description, source_type, total_debit, total_credit,
    actor_user_id, actor_subject, device_id, app_version
  ) values (
    p_tenant_id, btrim(p_idempotency_key), v_fingerprint, btrim(p_transaction_ref),
    p_journal_date, coalesce(p_description,''), p_source_type,
    v_total_debit::bigint, v_total_credit::bigint,
    v_actor, v_actor::text, p_device_id, p_app_version
  )
  returning journal_id into v_journal_id;

  v_line_no := 0;
  for v_line in select value from jsonb_array_elements(p_lines)
  loop
    v_line_no := v_line_no + 1;
    insert into public.accounting_journal_lines(
      journal_id, tenant_id, line_no, account_code, debit, credit, memo
    ) values (
      v_journal_id, p_tenant_id, v_line_no, v_line->>'account_code',
      coalesce(v_line->>'debit','0')::bigint,
      coalesce(v_line->>'credit','0')::bigint,
      coalesce(v_line->>'memo','')
    );
  end loop;

  insert into public.accounting_events(
    tenant_id, event_type, event_key, journal_id, entity_type, entity_id,
    actor_user_id, actor_subject, device_id, app_version, details
  ) values (
    p_tenant_id, 'journal_posted', 'journal:' || v_journal_id::text || ':posted',
    v_journal_id, 'journal', v_journal_id::text,
    v_actor, v_actor::text, p_device_id, p_app_version,
    jsonb_build_object(
      'idempotency_key', btrim(p_idempotency_key),
      'transaction_ref', btrim(p_transaction_ref),
      'source_type', p_source_type,
      'journal_date', p_journal_date::text,
      'total_debit', v_total_debit
    )
  );

  return v_journal_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Reversal is the only correction path for a posted journal.
-- ---------------------------------------------------------------------------
create or replace function accounting_private.reverse_journal(
  p_tenant_id uuid,
  p_original_journal_id uuid,
  p_idempotency_key text,
  p_journal_date date,
  p_reason text,
  p_device_id text,
  p_app_version text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := auth.uid();
  v_original public.accounting_journals%rowtype;
  v_existing_id uuid;
  v_existing_fingerprint jsonb;
  v_fingerprint jsonb;
  v_reversal_id uuid;
  v_line public.accounting_journal_lines%rowtype;
begin
  perform accounting_private.require_bound_device(v_actor, p_device_id, p_app_version);
  perform accounting_private.require_member_role(
    p_tenant_id, v_actor, array['owner','admin','accountant']
  );

  if p_idempotency_key is null or length(btrim(p_idempotency_key)) not between 1 and 200 then
    raise exception using errcode = '22023', message = 'invalid_idempotency_key';
  end if;
  if p_reason is null or length(btrim(p_reason)) not between 1 and 500 then
    raise exception using errcode = '22023', message = 'reversal_reason_required';
  end if;
  if p_journal_date is null then
    raise exception using errcode = '22023', message = 'journal_date_required';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_tenant_id::text || ':' || btrim(p_idempotency_key), 411)
  );

  select * into v_original
  from public.accounting_journals j
  where j.journal_id = p_original_journal_id
    and j.tenant_id = p_tenant_id;

  if not found then
    raise exception using errcode = 'P0002', message = 'original_journal_not_found';
  end if;
  if v_original.source_type = 'reversal' then
    raise exception using errcode = '55000', message = 'cannot_reverse_reversal';
  end if;

  v_fingerprint := jsonb_build_object(
    'original_journal_id', p_original_journal_id::text,
    'journal_date', p_journal_date::text,
    'reason', btrim(p_reason),
    'device_id', p_device_id,
    'app_version', p_app_version
  );

  select j.journal_id, j.request_fingerprint
    into v_existing_id, v_existing_fingerprint
  from public.accounting_journals j
  where j.tenant_id = p_tenant_id
    and j.idempotency_key = btrim(p_idempotency_key);

  if v_existing_id is not null then
    if v_existing_fingerprint = v_fingerprint
       and exists (
         select 1 from public.accounting_journals r
         where r.journal_id = v_existing_id
           and r.reversal_of = p_original_journal_id
       ) then
      return v_existing_id;
    end if;
    raise exception using errcode = '23505', message = 'idempotency_conflict';
  end if;

  if exists (
    select 1 from public.accounting_journals r
    where r.tenant_id = p_tenant_id
      and r.reversal_of = p_original_journal_id
  ) then
    raise exception using errcode = '23505', message = 'journal_already_reversed';
  end if;

  if exists (
    select 1 from public.accounting_periods p
    where p.tenant_id = p_tenant_id
      and p.status = 'closed'
      and p_journal_date between p.period_start and p.period_end
  ) then
    raise exception using errcode = '55000', message = 'accounting_period_closed';
  end if;

  insert into public.accounting_journals(
    tenant_id, idempotency_key, request_fingerprint, transaction_ref,
    journal_date, description, source_type, reversal_of,
    total_debit, total_credit, actor_user_id, actor_subject, device_id, app_version
  ) values (
    p_tenant_id, btrim(p_idempotency_key), v_fingerprint,
    'reversal:' || v_original.transaction_ref,
    p_journal_date, 'Reversal: ' || btrim(p_reason), 'reversal',
    p_original_journal_id, v_original.total_credit, v_original.total_debit,
    v_actor, v_actor::text, p_device_id, p_app_version
  )
  returning journal_id into v_reversal_id;

  for v_line in
    select * from public.accounting_journal_lines
    where journal_id = p_original_journal_id
    order by line_no
  loop
    insert into public.accounting_journal_lines(
      journal_id, tenant_id, line_no, account_code, debit, credit, memo
    ) values (
      v_reversal_id, p_tenant_id, v_line.line_no, v_line.account_code,
      v_line.credit, v_line.debit,
      case when length(v_line.memo) > 0 then 'Reversal: ' || v_line.memo else 'Reversal' end
    );
  end loop;

  insert into public.accounting_events(
    tenant_id, event_type, event_key, journal_id, entity_type, entity_id,
    actor_user_id, actor_subject, device_id, app_version, details
  ) values (
    p_tenant_id, 'journal_reversed',
    'journal:' || p_original_journal_id::text || ':reversed',
    v_reversal_id, 'journal', p_original_journal_id::text,
    v_actor, v_actor::text, p_device_id, p_app_version,
    jsonb_build_object(
      'original_journal_id', p_original_journal_id,
      'reversal_journal_id', v_reversal_id,
      'reason', btrim(p_reason)
    )
  );

  return v_reversal_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Period close / reopen.
-- ---------------------------------------------------------------------------
create or replace function accounting_private.close_period(
  p_tenant_id uuid,
  p_period_start date,
  p_period_end date,
  p_reason text,
  p_device_id text,
  p_app_version text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := auth.uid();
  v_period public.accounting_periods%rowtype;
begin
  perform accounting_private.require_bound_device(v_actor, p_device_id, p_app_version);
  perform accounting_private.require_member_role(
    p_tenant_id, v_actor, array['owner','admin']
  );

  if p_period_start is null or p_period_end is null or p_period_end < p_period_start then
    raise exception using errcode = '22023', message = 'invalid_period_dates';
  end if;
  if p_reason is null or length(btrim(p_reason)) not between 1 and 500 then
    raise exception using errcode = '22023', message = 'close_reason_required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text, 412));

  if exists (
    select 1 from public.accounting_periods p
    where p.tenant_id = p_tenant_id
      and not (p.period_end < p_period_start or p.period_start > p_period_end)
      and not (p.period_start = p_period_start and p.period_end = p_period_end)
  ) then
    raise exception using errcode = '23P01', message = 'accounting_period_overlap';
  end if;

  select * into v_period
  from public.accounting_periods p
  where p.tenant_id = p_tenant_id
    and p.period_start = p_period_start
    and p.period_end = p_period_end
  for update;

  if found and v_period.status = 'closed' then
    return v_period.period_id;
  end if;

  if not found then
    insert into public.accounting_periods(
      tenant_id, period_start, period_end, status,
      close_reason, closed_at, closed_by, closed_subject
    ) values (
      p_tenant_id, p_period_start, p_period_end, 'closed',
      btrim(p_reason), now(), v_actor, v_actor::text
    )
    returning * into v_period;
  else
    update public.accounting_periods
    set status = 'closed',
        close_reason = btrim(p_reason),
        closed_at = now(),
        closed_by = v_actor,
        closed_subject = v_actor::text
    where period_id = v_period.period_id
    returning * into v_period;
  end if;

  insert into public.accounting_events(
    tenant_id, event_type, event_key, entity_type, entity_id,
    actor_user_id, actor_subject, device_id, app_version, details
  ) values (
    p_tenant_id, 'period_closed',
    'period:' || v_period.period_id::text || ':closed:' || txid_current()::text,
    'accounting_period', v_period.period_id::text,
    v_actor, v_actor::text, p_device_id, p_app_version,
    jsonb_build_object(
      'period_start', p_period_start::text,
      'period_end', p_period_end::text,
      'reason', btrim(p_reason)
    )
  );

  return v_period.period_id;
end;
$$;

create or replace function accounting_private.reopen_period(
  p_tenant_id uuid,
  p_period_id uuid,
  p_reason text,
  p_device_id text,
  p_app_version text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := auth.uid();
  v_period public.accounting_periods%rowtype;
begin
  perform accounting_private.require_bound_device(v_actor, p_device_id, p_app_version);
  perform accounting_private.require_member_role(
    p_tenant_id, v_actor, array['owner','admin']
  );

  if p_reason is null or length(btrim(p_reason)) not between 1 and 500 then
    raise exception using errcode = '22023', message = 'reopen_reason_required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text, 412));

  select * into v_period
  from public.accounting_periods p
  where p.period_id = p_period_id
    and p.tenant_id = p_tenant_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'accounting_period_not_found';
  end if;
  if v_period.status = 'open' then
    return v_period.period_id;
  end if;

  update public.accounting_periods
  set status = 'open',
      reopen_reason = btrim(p_reason),
      reopened_at = now(),
      reopened_by = v_actor,
      reopened_subject = v_actor::text
  where period_id = p_period_id
  returning * into v_period;

  insert into public.accounting_events(
    tenant_id, event_type, event_key, entity_type, entity_id,
    actor_user_id, actor_subject, device_id, app_version, details
  ) values (
    p_tenant_id, 'period_reopened',
    'period:' || v_period.period_id::text || ':reopened:' || txid_current()::text,
    'accounting_period', v_period.period_id::text,
    v_actor, v_actor::text, p_device_id, p_app_version,
    jsonb_build_object('reason', btrim(p_reason))
  );

  return v_period.period_id;
end;
$$;

-- Public invoker wrappers keep SECURITY DEFINER logic out of the exposed schema.
create or replace function public.create_accounting_tenant(
  p_name text,
  p_device_id text,
  p_app_version text
