create table public.inventory_events (
  tenant_id uuid not null references public.accounting_tenants(tenant_id) on delete restrict,
  event_id text not null,
  server_sequence bigint generated always as identity,
  event_type text not null check (event_type in ('receipt','sale','adjustment','reversal')),
  product_id uuid not null,
  lot_id text not null,
  cost_layer_id text not null,
  quantity_delta bigint not null check (quantity_delta <> 0),
  unit_cost bigint not null check (unit_cost >= 0),
  business_ref text not null,
  request_fingerprint jsonb not null,
  actor_user_id uuid references auth.users(id) on delete set null,
  actor_subject text not null,
  device_id text not null,
  app_version text not null,
  occurred_at timestamptz not null,
  accepted_at timestamptz not null default now(),
  primary key (tenant_id, event_id),
  constraint inventory_events_tenant_product_fk foreign key (tenant_id, product_id)
    references public.product_master(tenant_id, product_id) on delete restrict,
  constraint inventory_events_tenant_sequence_unique unique (tenant_id, server_sequence)
);
create index inventory_events_tenant_sequence_idx on public.inventory_events(tenant_id, server_sequence);
create index inventory_events_product_idx on public.inventory_events(tenant_id, product_id, server_sequence);

