  (event_component='combined' and lot_id is not null and length(btrim(lot_id))>0 and cost_layer_id is not null and length(btrim(cost_layer_id))>0)
  or (event_component='physical' and lot_id is not null and length(btrim(lot_id))>0 and cost_layer_id is null)
