-- Phase 6: atomic app_config optimistic concurrency.

DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.app_config
    WHERE jsonb_typeof(value) <> 'object'
  ) THEN
    RAISE EXCEPTION 'app_config.value must be a JSON object before Phase 6 version normalization';
  END IF;
END
$$;

-- Legacy rows predate the version contract. Normalize them once so every row
-- can participate in compare-and-swap updates. Existing positive versions are preserved.
UPDATE public.app_config
SET value = (value - 'version') || jsonb_build_object(
  'version',
  CASE
    WHEN coalesce(value ->> 'version', '') ~ '^[1-9][0-9]*$'
      THEN (value ->> 'version')::integer
    ELSE 1
  END
)
WHERE NOT (coalesce(value ->> 'version', '') ~ '^[1-9][0-9]*$');

CREATE OR REPLACE FUNCTION public.update_app_config_atomic(
  key text,
  new_value jsonb,
  expected_version integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $$
<<atomic>>
DECLARE
  updated_value jsonb;
  updated_at_value timestamptz;
  current_version integer;
BEGIN
  IF atomic.key IS NULL OR btrim(atomic.key) = '' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'key is required';
  END IF;

  IF atomic.new_value IS NULL OR jsonb_typeof(atomic.new_value) <> 'object' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'new_value must be a JSON object';
  END IF;

  IF atomic.expected_version IS NULL OR atomic.expected_version < 1 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'expected_version must be >= 1';
  END IF;

  UPDATE public.app_config AS cfg
  SET value = (atomic.new_value - 'version')
        || jsonb_build_object('version', atomic.expected_version + 1),
      updated_at = now()
  WHERE cfg.key = atomic.key
    AND coalesce(cfg.value ->> 'version', '') ~ '^[1-9][0-9]*$'
    AND (cfg.value ->> 'version')::integer = atomic.expected_version
  RETURNING cfg.value, cfg.updated_at
  INTO updated_value, updated_at_value;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'key', atomic.key,
      'value', updated_value,
      'version', atomic.expected_version + 1,
      'updated_at', updated_at_value
    );
  END IF;

  SELECT (cfg.value ->> 'version')::integer
  INTO current_version
  FROM public.app_config AS cfg
  WHERE cfg.key = atomic.key;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0002',
      MESSAGE = format('CONFIG_NOT_FOUND key=%s', atomic.key);
  END IF;

  RAISE EXCEPTION USING
    ERRCODE = '40001',
    MESSAGE = format(
      'VERSION_CONFLICT key=%s expected=%s actual=%s',
      atomic.key,
      atomic.expected_version,
      current_version
    );
END;
$$;

