create or replace function accounting_private.resolve_pos_accounting_tenant(p_pos_tenant_id text,p_device_id text)
returns uuid language plpgsql security definer set search_path='' as $$
declare v_actor uuid:=auth.uid(); v_accounting uuid;
begin
  if v_actor is null then raise exception using errcode='28000',message='authentication_required'; end if;
  if p_pos_tenant_id is null or btrim(p_pos_tenant_id)='' then raise exception using errcode='22023',message='pos_tenant_required'; end if;
  if not exists(select 1 from public.devices d where d.device_id=p_device_id and d.user_id=v_actor and d.tenant_id=p_pos_tenant_id) then raise exception using errcode='42501',message='pos_device_tenant_mismatch'; end if;
  if not exists(select 1 from public.pos_memberships m where m.tenant_id=p_pos_tenant_id and m.user_id=v_actor and m.is_active) then raise exception using errcode='42501',message='pos_membership_required'; end if;
  select m.accounting_tenant_id into v_accounting from public.pos_accounting_tenant_map m where m.pos_tenant_id=p_pos_tenant_id and m.is_active;
  if v_accounting is null then raise exception using errcode='55000',message='accounting_tenant_mapping_missing'; end if;
  perform accounting_private.require_member_role(v_accounting,v_actor,null);
  return v_accounting;
end; $$;
revoke all on function accounting_private.resolve_pos_accounting_tenant(text,text) from public;

do $$ declare v_ddl text; begin
  select pg_get_functiondef(p.oid) into v_ddl from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='accounting_private' and p.proname='post_journal' and pg_get_function_identity_arguments(p.oid)='p_tenant_id uuid, p_idempotency_key text, p_transaction_ref text, p_journal_date date, p_description text, p_source_type text, p_lines jsonb, p_device_id text, p_app_version text';
  if v_ddl is null then raise exception 'accounting post_journal dependency missing'; end if;
  if position('qris_settlement' in v_ddl)=0 then
    if position('p_source_type not in (''pos_sale'',''sale_return'',''shift_close'',''manual'')' in v_ddl)=0 then raise exception 'post_journal source allowlist drift'; end if;
    execute replace(v_ddl,'p_source_type not in (''pos_sale'',''sale_return'',''shift_close'',''manual'')','p_source_type not in (''pos_sale'',''sale_return'',''shift_close'',''qris_settlement'',''manual'')');
  end if;
end $$;

create or replace function public.post_pos_accounting_journal(p_pos_tenant_id text,p_idempotency_key text,p_transaction_ref text,p_journal_date date,p_description text,p_source_type text,p_lines jsonb,p_device_id text,p_app_version text)
returns uuid language plpgsql security definer set search_path='' as $$
declare v_tenant uuid;
begin
  v_tenant:=accounting_private.resolve_pos_accounting_tenant(p_pos_tenant_id,p_device_id);
  return accounting_private.post_journal(v_tenant,p_idempotency_key,p_transaction_ref,p_journal_date,p_description,p_source_type,p_lines,p_device_id,p_app_version);
end $$;
