-- P1-CFG-01: exact 352 + five-layer fail-closed + layer-scoped write authority.
create schema if not exists private;

create or replace function private.assert_app_config_inventory()
returns void language plpgsql security definer set search_path = '' as $$
declare v_count int; v_digest text;
begin
  select count(*)::int, md5(string_agg(key, E'\n' order by key)) into v_count, v_digest from public.app_config;
  if v_count <> 352 or v_digest <> '1fd3d64219ecc7c333453c20da80e295' then
    raise exception 'app_config inventory mismatch: count %, digest %', v_count, v_digest using errcode = '23514';
  end if;
end; $$;
revoke all on function private.assert_app_config_inventory() from public, anon, authenticated;
grant execute on function private.assert_app_config_inventory() to service_role;

create or replace function private.guard_app_config_inventory()
returns trigger language plpgsql security definer set search_path = '' as $$
begin perform private.assert_app_config_inventory(); return null; end; $$;
revoke all on function private.guard_app_config_inventory() from public, anon, authenticated;
drop trigger if exists app_config_inventory_key_guard on public.app_config;
create trigger app_config_inventory_key_guard after insert or delete or update of key on public.app_config
for each statement execute function private.guard_app_config_inventory();
drop trigger if exists app_config_inventory_truncate_guard on public.app_config;
create trigger app_config_inventory_truncate_guard after truncate on public.app_config
for each statement execute function private.guard_app_config_inventory();

create or replace function private.can_write_app_config(p_key text)
returns boolean language plpgsql stable security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid(); v_role text := lower(coalesce(auth.jwt()->>'role',''));
  v_email text := lower(coalesce(auth.jwt()->>'email','')); v_tenant text; v_device text;
begin
  if v_role='service_role' or v_email='satria@berkahtigaputeri.com' then return true; end if;
  if v_uid is null then return false; end if;
  if p_key ~ '^tenant:[^:]+$' then
    v_tenant:=split_part(p_key,':',2);
    return exists(select 1 from public.pos_memberships m
      where m.tenant_id=v_tenant and m.user_id=v_uid and m.is_active and m.role='owner');
  elsif p_key ~ '^tenant:[^:]+:service:(pos|akuntansi)$' then
    v_tenant:=split_part(p_key,':',2);
    return exists(select 1 from public.pos_memberships m
      where m.tenant_id=v_tenant and m.user_id=v_uid and m.is_active and m.role in ('owner','manager'));
  elsif p_key ~ '^device:[^:]+$' then
    v_device:=split_part(p_key,':',2);
    return exists(select 1 from public.devices d where d.device_id=v_device and
      (d.user_id=v_uid or exists(select 1 from public.pos_memberships m where m.tenant_id=d.tenant_id
       and m.user_id=v_uid and m.is_active and m.role in ('owner','manager'))));
  end if;
  return false;
end; $$;
revoke all on function private.can_write_app_config(text) from public, anon;
grant execute on function private.can_write_app_config(text) to authenticated, service_role;

create or replace function public.update_app_config_atomic(p_key text,p_new_value jsonb,p_expected_version integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_current jsonb; v_version int; v_role text:=lower(coalesce(auth.jwt()->>'role',''));
begin
  perform private.assert_app_config_inventory();
  if not private.can_write_app_config(p_key) then raise exception 'not authorized to update app_config key %',p_key using errcode='42501'; end if;
  if p_new_value is null or jsonb_typeof(p_new_value)<>'object' then raise exception 'new value must be a JSON object' using errcode='22023'; end if;
  if p_expected_version is null or p_expected_version<1 then raise exception 'expected version must be >= 1' using errcode='22023'; end if;
  select value into v_current from public.app_config where key=p_key for update;
  if not found then raise exception 'key not found %',p_key using errcode='P0002'; end if;
  if coalesce(v_current->>'version','') !~ '^[1-9][0-9]*$' then raise exception 'invalid current version for key %',p_key using errcode='22023'; end if;
  v_version:=(v_current->>'version')::int;
  if v_version<>p_expected_version then raise sqlstate '40001' using message=format('version conflict: expected %s got %s',p_expected_version,v_version); end if;
  if p_key ~ '^tenant:[^:]+$' and v_role<>'service_role' and lower(coalesce(auth.jwt()->>'email',''))<>'satria@berkahtigaputeri.com'
     and coalesce(p_new_value->>'template_id',p_new_value->>'template','')<>coalesce(v_current->>'template_id',v_current->>'template','')
  then raise exception 'tenant role cannot change template assignment' using errcode='42501'; end if;
  if p_key ~ '^device:[^:]+$' and p_new_value?'device_id' and p_new_value->>'device_id'<>split_part(p_key,':',2)
  then raise exception 'device_id must match app_config key' using errcode='23514'; end if;
  p_new_value:=jsonb_set(p_new_value,'{version}',to_jsonb(v_version+1),true);
  update public.app_config set value=p_new_value,updated_at=now() where key=p_key and (value->>'version')::int=p_expected_version;
  if not found then raise sqlstate '40001' using message='concurrent update'; end if;
  return p_new_value;
end; $$;
revoke all on function public.update_app_config_atomic(text,jsonb,integer) from public, anon;
grant execute on function public.update_app_config_atomic(text,jsonb,integer) to authenticated, service_role;
revoke insert, update, delete, truncate on table public.app_config from authenticated;

create or replace function public.get_effective_config(p_tenant text,p_device text,p_service text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  g jsonb; t jsonb; x jsonb; s jsonb; d jsonb; tid text; svc text:=lower(trim(coalesce(p_service,'')));
  uid uuid:=auth.uid(); email text:=lower(coalesce(auth.jwt()->>'email','')); role_name text:=lower(coalesce(auth.jwt()->>'role',''));
begin
  perform private.assert_app_config_inventory();
  if nullif(trim(coalesce(p_tenant,'')),'') is null or nullif(trim(coalesce(p_device,'')),'') is null or svc not in ('pos','akuntansi')
    then raise exception 'invalid tenant/device/service' using errcode='22023'; end if;
  if role_name<>'service_role' and uid is null then raise exception 'authentication required' using errcode='42501'; end if;
