create or replace function private.strip_legacy_tax_config(p_value jsonb)
returns jsonb
language sql
immutable
set search_path=''
as $$
  select coalesce(jsonb_object_agg(e.key,e.value),'{}'::jsonb)
  from jsonb_each(coalesce(p_value,'{}'::jsonb)) e
  where lower(e.key) not in (
    'ppn','ppn rate %','ppn account','dpp',
    'pph21','pph 21','pph23','pph 23','pph final','tax rate','tax_rate'
  );
$$;
revoke all on function private.strip_legacy_tax_config(jsonb) from public,anon,authenticated,service_role;

update public.app_config
set value=jsonb_set(
      private.strip_legacy_tax_config(value),
      '{version}',
      to_jsonb(((value->>'version')::int)+1),
      true
    ),
    updated_at=now()
where exists(
  select 1 from jsonb_object_keys(value) k
  where lower(k) in (
    'ppn','ppn rate %','ppn account','dpp',
    'pph21','pph 21','pph23','pph 23','pph final','tax rate','tax_rate'
  )
);

do $$
declare v_count int; v_digest text; v_legacy int;
begin
  select count(*)::int,md5(string_agg(key,E'\n' order by key)) into v_count,v_digest
  from public.app_config;
  if v_count<>352 or v_digest<>'1fd3d64219ecc7c333453c20da80e295' then
    raise exception 'app_config contract changed: count %, digest %',v_count,v_digest using errcode='23514';
  end if;
  select count(*) into v_legacy
  from public.app_config a cross join lateral jsonb_object_keys(a.value) k
  where lower(k) in (
    'ppn','ppn rate %','ppn account','dpp',
    'pph21','pph 21','pph23','pph 23','pph final','tax rate','tax_rate'
  );
  if v_legacy<>0 then raise exception 'legacy tax key remains in app_config' using errcode='23514'; end if;
end $$;

create or replace function public.update_app_config_atomic(p_key text,p_new_value jsonb,p_expected_version integer)
returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  v_current jsonb;
  v_version int;
  v_device_tenant text;
  v_role text:=lower(coalesce(auth.jwt()->>'role',''));
begin
  perform private.assert_app_config_inventory();

  if v_role='service_role' and (p_key='global' or p_key ~ '^template:[^:]+$') then
    raise exception 'service_role cannot mutate protected config' using errcode='42501';
  end if;

  if (p_key='global' or p_key ~ '^template:[^:]+$') and not private.btp_is_super_admin() then
    raise exception 'GLOBAL/TEMPLATE mutation requires canonical super_admin berkahtigaputeri@gmail.com'
      using errcode='42501';
  end if;

  if not private.can_write_app_config(p_key) then
    raise exception 'not authorized to update app_config key %',p_key using errcode='42501';
  end if;
  if p_new_value is null or jsonb_typeof(p_new_value)<>'object' then
    raise exception 'new value must be a JSON object' using errcode='22023';
  end if;
  if exists(
    select 1 from jsonb_object_keys(p_new_value) k
    where lower(k) in (
      'ppn','ppn rate %','ppn account','dpp',
      'pph21','pph 21','pph23','pph 23','pph final','tax rate','tax_rate'
    )
  ) then
    raise exception 'regulatory tax values are read-only; use tax_rates' using errcode='42501';
  end if;
  if p_expected_version is null or p_expected_version<1 then
    raise exception 'expected version must be >= 1' using errcode='22023';
  end if;

  select value into v_current from public.app_config where key=p_key for update;
  if not found then raise exception 'key not found %',p_key using errcode='P0002'; end if;
  if coalesce(v_current->>'version','') !~ '^[1-9][0-9]*$' then
    raise exception 'invalid current version for key %',p_key using errcode='22023';
  end if;
  v_version:=(v_current->>'version')::int;
  if v_version<>p_expected_version then
    raise sqlstate '40001' using message=format('version conflict: expected %s got %s',p_expected_version,v_version);
  end if;

  if p_key ~ '^tenant:[^:]+$'
     and v_role<>'service_role'
     and not private.btp_is_super_admin()
     and coalesce(p_new_value->>'template_id',p_new_value->>'template','')
         <>coalesce(v_current->>'template_id',v_current->>'template','') then
    raise exception 'tenant role cannot change template assignment' using errcode='42501';
  end if;

  if p_key ~ '^device:[^:]+$' then
    if p_new_value?'device_id' and p_new_value->>'device_id'<>split_part(p_key,':',2) then
      raise exception 'device_id must match app_config key' using errcode='23514';
    end if;
    select tenant_id into strict v_device_tenant from public.devices where device_id=split_part(p_key,':',2);
    if p_new_value?'tenant_id' and p_new_value->>'tenant_id'<>v_device_tenant then
      raise exception 'device tenant cannot be reassigned' using errcode='23514';
    end if;
  end if;

  p_new_value:=jsonb_set(private.strip_legacy_tax_config(p_new_value),'{version}',to_jsonb(v_version+1),true);
  update public.app_config set value=p_new_value,updated_at=now()
  where key=p_key and (value->>'version')::int=p_expected_version;
  if not found then raise sqlstate '40001' using message='concurrent update'; end if;

  if p_key ~ '^tenant:[^:]+$' then
    update public.tenants set
      toko_name=case when p_new_value?'toko_name' then p_new_value->>'toko_name' else toko_name end,
      alamat=case when p_new_value?'address' then p_new_value->>'address' else alamat end,
      max_user=case when p_new_value?'max_user' then (p_new_value->>'max_user')::int else max_user end,
      expiry=case when p_new_value?'expiry' then nullif(p_new_value->>'expiry','')::date else expiry end,
      is_blocked=case when p_new_value?'blocked' then (p_new_value->>'blocked')::boolean else is_blocked end,
      features=case when p_new_value?'features' then p_new_value->'features' else features end,
      template_id=case when p_new_value?'template_id' then upper(p_new_value->>'template_id') else template_id end,
      updated_at=now()
    where tenant_id=split_part(p_key,':',2);
    if not found then raise exception 'tenant projection missing' using errcode='23514'; end if;
  elsif p_key ~ '^device:[^:]+$' then
    update public.devices set
      package_id=case when p_new_value?'package_id' then p_new_value->>'package_id' else package_id end,
      hardware_mode=case when p_new_value?'hardware_mode' then p_new_value->>'hardware_mode' else hardware_mode end,
      printer_type=case when p_new_value?'printer_type' then p_new_value->>'printer_type' else printer_type end,
      updated_at=now()
    where device_id=split_part(p_key,':',2);
    if not found then raise exception 'device projection missing' using errcode='23514'; end if;
  end if;
  return p_new_value;
exception when no_data_found then
  raise exception 'device projection missing' using errcode='23514';
end;
$$;

revoke all on function public.update_app_config_atomic(text,jsonb,integer) from public,anon;
grant execute on function public.update_app_config_atomic(text,jsonb,integer) to authenticated,service_role;

create or replace function public.get_effective_config(p_tenant text,p_device text,p_service text)
returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  g jsonb; t jsonb; x jsonb; s jsonb; d jsonb;
  tid text;
  svc text:=lower(trim(coalesce(p_service,'')));
  uid uuid:=auth.uid();
  role_name text:=lower(coalesce(auth.jwt()->>'role',''));
begin
  perform private.assert_app_config_inventory();
  if nullif(trim(coalesce(p_tenant,'')),'') is null
     or nullif(trim(coalesce(p_device,'')),'') is null
     or svc not in ('pos','akuntansi') then
    raise exception 'invalid tenant/device/service' using errcode='22023';
  end if;
  if role_name<>'service_role' and uid is null then
    raise exception 'authentication required' using errcode='42501';
  end if;
  if not exists(select 1 from public.devices z where z.device_id=p_device and z.tenant_id=p_tenant) then
    raise exception 'device does not belong to tenant' using errcode='42501';
  end if;
  if role_name<>'service_role'
     and not private.btp_is_super_admin()
     and not exists(select 1 from public.devices z where z.device_id=p_device and z.tenant_id=p_tenant and z.user_id=uid) then
    raise exception 'caller is not authorized for device' using errcode='42501';
  end if;

  select value into strict g from public.app_config where key='global';
  select value into strict t from public.app_config where key='tenant:'||p_tenant;
  tid:=upper(trim(coalesce(t->>'template_id',t->>'template','')));
  if tid='' then raise exception 'tenant template assignment missing' using errcode='23514'; end if;
  select value into strict x from public.app_config where key='template:'||tid;
  select value into strict s from public.app_config where key='tenant:'||p_tenant||':service:'||svc;
  select value into strict d from public.app_config where key='device:'||p_device;
  if nullif(trim(coalesce(s->>'inherited_from_template','')),'') is not null then
    s:=s-'mdr'-'mdr_pos'-'qris_mdr'-'mdr_%';
  end if;
  return private.strip_legacy_tax_config(g||x||t||s||d);
exception when no_data_found then
  raise exception 'missing canonical five-layer app_config row' using errcode='23514';
end;
$$;

revoke all on function public.get_effective_config(text,text,text) from public,anon;
grant execute on function public.get_effective_config(text,text,text) to authenticated,service_role;

create table public.inventory_average_projection (
  tenant_id uuid not null,
  product_id uuid not null,
  on_hand_qty bigint not null default 0 check (on_hand_qty >= 0),
  inventory_value bigint not null default 0 check (inventory_value >= 0),
  revision bigint not null default 1 check (revision > 0),
  last_event_id text,
  updated_at timestamptz not null default now(),
  primary key (tenant_id,product_id),
  constraint inventory_average_product_fk foreign key (tenant_id,product_id)
    references public.product_master(tenant_id,product_id),
  constraint inventory_average_zero_value_check check (on_hand_qty > 0 or inventory_value = 0)
);

create table public.inventory_average_events (
  tenant_id uuid not null,
  event_id text not null,
  product_id uuid not null,
  event_type text not null check (event_type in ('receipt','sale','return','adjustment')),
  quantity_delta bigint not null check (quantity_delta <> 0),
  value_delta bigint not null check (value_delta <> 0),
  business_ref text not null check (length(btrim(business_ref)) >= 1),
  original_business_ref text,
  actor_user_id uuid references auth.users(id),
  device_id text not null check (length(btrim(device_id)) >= 1),
  reason text not null check (length(btrim(reason)) >= 3),
  occurred_at timestamptz not null default now(),
  primary key (tenant_id,event_id),
  constraint inventory_average_event_product_fk foreign key (tenant_id,product_id)
    references public.product_master(tenant_id,product_id)
);

alter table public.inventory_average_projection enable row level security;
alter table public.inventory_average_events enable row level security;

create policy inventory_average_projection_member_read
on public.inventory_average_projection for select to authenticated
using (
  auth.uid() is not null and exists(
    select 1 from public.accounting_memberships m
    where m.tenant_id=inventory_average_projection.tenant_id
      and m.user_id=(select auth.uid()) and m.is_active
  )
);
create policy inventory_average_events_member_read
on public.inventory_average_events for select to authenticated
using (
  auth.uid() is not null and exists(
    select 1 from public.accounting_memberships m
    where m.tenant_id=inventory_average_events.tenant_id
      and m.user_id=(select auth.uid()) and m.is_active
  )
);

