create or replace function private.resolve_tax_rate_snapshot(
  p_tax_code text,p_object_code text,p_business_date date,p_category text default 'DEFAULT'
) returns jsonb
language plpgsql stable security definer set search_path=''
as $$
declare v_count int; v_row public.tax_rates%rowtype;
begin
  if p_business_date is null then raise exception 'business_date_required' using errcode='22023'; end if;
  select count(*),min(tax_rate_id)::text::uuid into v_count,v_row.tax_rate_id
  from public.tax_rates
  where tax_code=p_tax_code and object_code=p_object_code and category=p_category
    and effective_date<=p_business_date and (end_date is null or end_date>=p_business_date);
  if v_count<>1 then raise exception 'effective_tax_rule_ambiguity' using errcode='23514'; end if;
  select * into strict v_row from public.tax_rates where tax_rate_id=v_row.tax_rate_id;
  return jsonb_build_object(
    'tax_rate_id',v_row.tax_rate_id,'tax_code',v_row.tax_code,'object_code',v_row.object_code,
    'category',v_row.category,'statutory_rate',v_row.statutory_rate,'dpp_multiplier',v_row.dpp_multiplier,
    'effective_rate',v_row.effective_rate,'calculation_method',v_row.calculation_method,
    'effective_date',v_row.effective_date,'end_date',v_row.end_date,'legal_basis',v_row.legal_basis,
    'metadata',v_row.metadata
  );
end;
$$;

create or replace function private.resolve_pph21_ter(
  p_category text,p_monthly_gross bigint,p_business_date date
) returns jsonb
language plpgsql stable security definer set search_path=''
as $$
declare v_count int; v public.tax_rate_brackets%rowtype;
begin
  if p_category not in ('A','B','C') or p_monthly_gross is null or p_monthly_gross<0 or p_business_date is null then
    raise exception 'invalid_pph21_ter_input' using errcode='22023';
  end if;
  select count(*) into v_count from public.tax_rate_brackets b
  where b.tax_code='PPH21_TER' and b.category=p_category
    and b.lower_bound<=p_monthly_gross and (b.upper_bound is null or b.upper_bound>=p_monthly_gross)
    and b.effective_date<=p_business_date and (b.end_date is null or b.end_date>=p_business_date);
  if v_count<>1 then raise exception 'effective_pph21_ter_rule_ambiguity' using errcode='23514'; end if;
  select * into strict v from public.tax_rate_brackets b
  where b.tax_code='PPH21_TER' and b.category=p_category
    and b.lower_bound<=p_monthly_gross and (b.upper_bound is null or b.upper_bound>=p_monthly_gross)
    and b.effective_date<=p_business_date and (b.end_date is null or b.end_date>=p_business_date);
  return jsonb_build_object(
    'tax_code','PPH21_TER','category',v.category,'lower_bound',v.lower_bound,'upper_bound',v.upper_bound,
    'rate',v.rate,'effective_date',v.effective_date,'end_date',v.end_date,'legal_basis',v.legal_basis
  );
end;
$$;

create or replace function private.resolve_vat_transaction_code(p_facility_context text)
returns text
language plpgsql immutable set search_path=''
as $$
begin
  case upper(coalesce(btrim(p_facility_context),'NORMAL'))
    when 'NORMAL' then return '01';
    when 'NOT_COLLECTED' then return '07';
    when 'GOVERNMENT_BORNE' then return '07';
    when 'EXEMPT' then return '08';
    when 'ASSET_16D' then return '09';
    else raise exception 'invalid_vat_facility_context' using errcode='22023';
  end case;
end;
$$;

create or replace function private.assert_no_accounting_fields(p_value jsonb)
returns void
language plpgsql immutable set search_path=''
as $$
begin
  if p_value is null or jsonb_typeof(p_value)<>'object' then raise exception 'facts_must_be_object' using errcode='22023'; end if;
  if exists(
    with recursive walk(v) as (
      select p_value
      union all
      select x.value from walk w cross join lateral jsonb_each(case when jsonb_typeof(w.v)='object' then w.v else '{}'::jsonb end) x
      union all
      select x.value from walk w cross join lateral jsonb_array_elements(case when jsonb_typeof(w.v)='array' then w.v else '[]'::jsonb end) x
    ), keys as (
      select lower(e.key) k from walk w cross join lateral jsonb_each(case when jsonb_typeof(w.v)='object' then w.v else '{}'::jsonb end) e
    )
    select 1 from keys where k in ('account_code','debit','credit','journal_lines','lines_accounting','tax_rate','ppn_rate','pph_rate')
  ) then
    raise exception 'operator facts cannot contain account/debit/credit/rate overrides' using errcode='42501';
  end if;
end;
$$;

