create or replace function inventory_private.average_receive(
  p_tenant_id uuid,p_product_id uuid,p_qty bigint,p_unit_cost bigint,
  p_event_id text,p_business_ref text,p_actor uuid,p_device_id text,p_reason text
) returns bigint
language plpgsql security definer set search_path=''
as $$
declare v public.inventory_average_projection%rowtype; v_add numeric; v_existing public.inventory_average_events%rowtype;
begin
  if p_qty is null or p_qty<=0 or p_unit_cost is null or p_unit_cost<=0 then
    raise exception 'invalid_inventory_receipt' using errcode='22023';
  end if;
  if p_event_id is null or length(btrim(p_event_id))=0 or p_business_ref is null or length(btrim(p_business_ref))=0 then raise exception 'inventory_identity_required' using errcode='22023'; end if;
  if p_actor is null or p_device_id is null or length(btrim(p_device_id))=0 or p_reason is null or length(btrim(p_reason))<3 then raise exception 'inventory_audit_lineage_required' using errcode='22023'; end if;
  if not exists(select 1 from public.product_master p where p.tenant_id=p_tenant_id and p.product_id=p_product_id and p.is_active) then raise exception 'inventory_product_not_active' using errcode='23503'; end if;
  select * into v_existing from public.inventory_average_events where tenant_id=p_tenant_id and event_id=btrim(p_event_id);
  if found then
    if v_existing.product_id=p_product_id and v_existing.event_type='receipt' and v_existing.quantity_delta=p_qty and v_existing.business_ref=btrim(p_business_ref) then return v_existing.value_delta; end if;
    raise exception 'inventory_idempotency_conflict' using errcode='23505';
  end if;
  v_add:=p_qty::numeric*p_unit_cost::numeric;
  if v_add>9223372036854775807::numeric then raise exception 'inventory_value_out_of_range' using errcode='22003'; end if;
  insert into public.inventory_average_projection(tenant_id,product_id,on_hand_qty,inventory_value,revision,last_event_id) values(p_tenant_id,p_product_id,0,0,1,null) on conflict do nothing;
  select * into v from public.inventory_average_projection where tenant_id=p_tenant_id and product_id=p_product_id for update;
  if v.inventory_value::numeric+v_add>9223372036854775807::numeric then raise exception 'inventory_value_out_of_range' using errcode='22003'; end if;
  update public.inventory_average_projection set on_hand_qty=v.on_hand_qty+p_qty,inventory_value=v.inventory_value+v_add::bigint,revision=v.revision+1,last_event_id=btrim(p_event_id),updated_at=now() where tenant_id=p_tenant_id and product_id=p_product_id;
  insert into public.inventory_product_projection(tenant_id,product_id,on_hand_qty,revision,last_server_sequence) values(p_tenant_id,p_product_id,v.on_hand_qty+p_qty,1,0)
  on conflict (tenant_id,product_id) do update set on_hand_qty=excluded.on_hand_qty,revision=public.inventory_product_projection.revision+1,updated_at=now();
  insert into public.inventory_average_events(tenant_id,event_id,product_id,event_type,quantity_delta,value_delta,business_ref,actor_user_id,device_id,reason)
  values(p_tenant_id,btrim(p_event_id),p_product_id,'receipt',p_qty,v_add::bigint,btrim(p_business_ref),p_actor,btrim(p_device_id),btrim(p_reason));
  return v_add::bigint;
end;
$$;

create or replace function inventory_private.average_adjust_to_count(
  p_tenant_id uuid,p_product_id uuid,p_counted_qty bigint,p_zero_stock_unit_cost bigint,
  p_event_id text,p_business_ref text,p_actor uuid,p_device_id text,p_reason text
) returns jsonb
language plpgsql security definer set search_path=''
as $$
declare v public.inventory_average_projection%rowtype; v_delta bigint; v_value_delta bigint; v_num numeric; v_existing public.inventory_average_events%rowtype;
begin
  if p_counted_qty is null or p_counted_qty<0 then raise exception 'invalid_stock_count' using errcode='22023'; end if;
  if p_event_id is null or length(btrim(p_event_id))=0 or p_business_ref is null or length(btrim(p_business_ref))=0 then raise exception 'inventory_identity_required' using errcode='22023'; end if;
  if p_actor is null or p_device_id is null or length(btrim(p_device_id))=0 or p_reason is null or length(btrim(p_reason))<3 then raise exception 'inventory_audit_lineage_required' using errcode='22023'; end if;
  select * into v_existing from public.inventory_average_events where tenant_id=p_tenant_id and event_id=btrim(p_event_id);
  if found then
    if v_existing.product_id=p_product_id and v_existing.event_type='adjustment' and v_existing.business_ref=btrim(p_business_ref) then
      return jsonb_build_object('quantity_delta',v_existing.quantity_delta,'value_delta',v_existing.value_delta);
    end if;
    raise exception 'inventory_idempotency_conflict' using errcode='23505';
  end if;
  insert into public.inventory_average_projection(tenant_id,product_id,on_hand_qty,inventory_value,revision,last_event_id) values(p_tenant_id,p_product_id,0,0,1,null) on conflict do nothing;
  select * into v from public.inventory_average_projection where tenant_id=p_tenant_id and product_id=p_product_id for update;
  v_delta:=p_counted_qty-v.on_hand_qty;
  if v_delta=0 then raise exception 'stock_count_matches_system_no_adjustment' using errcode='22023'; end if;
  if v_delta<0 then
    if v.inventory_value<=0 or v.on_hand_qty<=0 then raise exception 'invalid_inventory_value_for_stock_shortage' using errcode='23514'; end if;
    if -v_delta=v.on_hand_qty then v_value_delta:=-v.inventory_value;
    else
      v_num:=round(v.inventory_value::numeric*(-v_delta)::numeric/v.on_hand_qty::numeric);
      if v_num<=0 or v_num>=v.inventory_value then raise exception 'invalid_moving_average_adjustment' using errcode='23514'; end if;
      v_value_delta:=-v_num::bigint;
    end if;
  else
    if v.on_hand_qty>0 then
      v_num:=round(v.inventory_value::numeric*v_delta::numeric/v.on_hand_qty::numeric);
      if v_num<=0 then raise exception 'invalid_moving_average_adjustment' using errcode='23514'; end if;
      v_value_delta:=v_num::bigint;
    else
      if p_zero_stock_unit_cost is null or p_zero_stock_unit_cost<=0 then raise exception 'unit_cost_required_for_positive_count_from_zero' using errcode='22023'; end if;
      v_num:=v_delta::numeric*p_zero_stock_unit_cost::numeric;
      if v_num>9223372036854775807::numeric then raise exception 'inventory_value_out_of_range' using errcode='22003'; end if;
      v_value_delta:=v_num::bigint;
    end if;
  end if;
  update public.inventory_average_projection set on_hand_qty=p_counted_qty,inventory_value=v.inventory_value+v_value_delta,revision=v.revision+1,last_event_id=btrim(p_event_id),updated_at=now() where tenant_id=p_tenant_id and product_id=p_product_id;
  insert into public.inventory_product_projection(tenant_id,product_id,on_hand_qty,revision,last_server_sequence) values(p_tenant_id,p_product_id,p_counted_qty,1,0)
  on conflict (tenant_id,product_id) do update set on_hand_qty=excluded.on_hand_qty,revision=public.inventory_product_projection.revision+1,updated_at=now();
  insert into public.inventory_average_events(tenant_id,event_id,product_id,event_type,quantity_delta,value_delta,business_ref,actor_user_id,device_id,reason)
  values(p_tenant_id,btrim(p_event_id),p_product_id,'adjustment',v_delta,v_value_delta,btrim(p_business_ref),p_actor,btrim(p_device_id),btrim(p_reason));
  return jsonb_build_object('quantity_delta',v_delta,'value_delta',v_value_delta);
end;
$$;

revoke all on function inventory_private.average_receive(uuid,uuid,bigint,bigint,text,text,uuid,text,text) from public,anon,authenticated,service_role;
revoke all on function inventory_private.average_adjust_to_count(uuid,uuid,bigint,bigint,text,text,uuid,text,text) from public,anon,authenticated,service_role;

create or replace function private.build_sale_lines(
  p_tenant_id uuid,p_transaction_ref text,p_business_date date,p_facts jsonb,
  p_payment_account text,p_actor uuid,p_device_id text,p_reason text
) returns jsonb
language plpgsql security definer set search_path=''
as $$
declare
  v_lines jsonb:=coalesce(p_facts->'lines','[]'::jsonb);
  v_line jsonb; v_i int:=0; v_line_key text; v_kind text; v_product uuid; v_qty bigint; v_amount bigint;
  v_is_pkp boolean:=coalesce((p_facts->>'is_pkp')::boolean,false);
  v_inclusive boolean:=coalesce((p_facts->>'prices_include_vat')::boolean,false);
  v_object text:=upper(coalesce(nullif(btrim(p_facts->>'tax_object_code'),''),'NON_LUXURY'));
  v_facility text:=upper(coalesce(nullif(btrim(p_facts->>'facility_context'),''),'NORMAL'));
  v_tax jsonb:='{}'::jsonb; v_rate numeric:=0; v_tax_code text;
  v_dpp bigint; v_vat bigint; v_gross bigint; v_cogs bigint:=0;
  v_stock_dpp bigint:=0; v_service_dpp bigint:=0; v_total_vat bigint:=0; v_total_gross bigint:=0; v_total_cogs bigint:=0;
  v_sale_evidence jsonb:='[]'::jsonb; v_journal jsonb:='[]'::jsonb;
begin
  perform private.assert_no_accounting_fields(p_facts);
  if p_payment_account not in ('1-1010','1-1020','1-1030','1-1050') then raise exception 'invalid_internal_payment_mapping' using errcode='23514'; end if;
  if p_transaction_ref is null or length(btrim(p_transaction_ref))=0 or p_business_date is null then raise exception 'sale_identity_required' using errcode='22023'; end if;
  if jsonb_typeof(v_lines)<>'array' or jsonb_array_length(v_lines)<1 or jsonb_array_length(v_lines)>50 then raise exception 'sale_lines_required' using errcode='22023'; end if;
  if v_facility='ASSET_16D' then raise exception 'asset_16d_not_supported_by_pos_sale_intent' using errcode='22023'; end if;
  v_tax_code:=private.resolve_vat_transaction_code(v_facility);
  if v_is_pkp then
    v_tax:=private.resolve_tax_rate_snapshot('PPN',v_object,p_business_date,'DEFAULT');
    v_rate:=(v_tax->>'effective_rate')::numeric;
  end if;

  for v_line in select value from jsonb_array_elements(v_lines) loop
    v_i:=v_i+1;
    v_line_key:=coalesce(nullif(btrim(v_line->>'line_key'),''),v_i::text);
    v_kind:=upper(coalesce(v_line->>'kind',''));
    if v_kind not in ('STOCK','SERVICE') then raise exception 'invalid_sale_line_kind' using errcode='22023'; end if;
    if coalesce(v_line->>'qty','') !~ '^[1-9][0-9]*$' or coalesce(v_line->>'amount','') !~ '^[1-9][0-9]*$' then raise exception 'sale_qty_amount_must_be_positive_integer_rupiah' using errcode='22023'; end if;
    v_qty:=(v_line->>'qty')::bigint; v_amount:=(v_line->>'amount')::bigint;
    if v_is_pkp and v_facility='NORMAL' then
      if v_inclusive then
        v_dpp:=round(v_amount::numeric/(1+v_rate))::bigint;
        v_vat:=v_amount-v_dpp;
        v_gross:=v_amount;
      else
        v_dpp:=v_amount;
        v_vat:=round(v_dpp::numeric*v_rate)::bigint;
        v_gross:=v_dpp+v_vat;
      end if;
    else
      v_dpp:=v_amount; v_vat:=0; v_gross:=v_amount;
    end if;
    if v_dpp<=0 or v_gross<=0 or v_vat<0 then raise exception 'invalid_sale_tax_calculation' using errcode='23514'; end if;

    if v_kind='STOCK' then
      begin v_product:=(v_line->>'product_id')::uuid; exception when others then raise exception 'valid_product_id_required_for_stock_line' using errcode='22023'; end;
      v_cogs:=inventory_private.average_consume(p_tenant_id,v_product,v_qty,'sale:'||btrim(p_transaction_ref)||':'||v_line_key,btrim(p_transaction_ref),p_actor,p_device_id,p_reason);
      if v_cogs<=0 then raise exception 'stocked_sale_cogs_must_be_positive' using errcode='23514'; end if;
      v_stock_dpp:=v_stock_dpp+v_dpp; v_total_cogs:=v_total_cogs+v_cogs;
    else
      if v_line ? 'product_id' and nullif(btrim(v_line->>'product_id'),'') is not null then raise exception 'service_line_cannot_reference_inventory_product' using errcode='22023'; end if;
      v_product:=null; v_cogs:=0; v_service_dpp:=v_service_dpp+v_dpp;
    end if;
    v_total_vat:=v_total_vat+v_vat; v_total_gross:=v_total_gross+v_gross;
    v_sale_evidence:=v_sale_evidence||jsonb_build_array(jsonb_build_object(
      'line_key',v_line_key,'line_kind',v_kind,'product_id',v_product,'quantity',v_qty,
      'revenue_account',case when v_kind='STOCK' then '4-4010' else '4-4050' end,
      'dpp',v_dpp,'vat_amount',v_vat,'gross_amount',v_gross,'original_cogs',v_cogs,
      'tax_snapshot',case when v_is_pkp then v_tax||jsonb_build_object('vat_transaction_code',v_tax_code,'facility_context',v_facility) else '{}'::jsonb end
    ));
  end loop;

  v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code',p_payment_account,'debit',v_total_gross,'credit',0,'memo','Pembayaran penjualan'));
  if v_stock_dpp>0 then v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','4-4010','debit',0,'credit',v_stock_dpp,'memo','Penjualan barang')); end if;
  if v_service_dpp>0 then v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','4-4050','debit',0,'credit',v_service_dpp,'memo','Pendapatan jasa')); end if;
  if v_total_vat>0 then v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','2-2010','debit',0,'credit',v_total_vat,'memo','PPN dari penjualan')); end if;
  if v_total_cogs>0 then
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','5-5010','debit',v_total_cogs,'credit',0,'memo','Harga modal rata-rata otomatis'));
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','1-1040','debit',0,'credit',v_total_cogs,'memo','Pengurangan persediaan'));
  end if;
  return jsonb_build_object(
    'journal_lines',v_journal,'sale_lines',v_sale_evidence,
    'tax_snapshot',case when v_is_pkp then v_tax||jsonb_build_object('vat_transaction_code',v_tax_code,'facility_context',v_facility) else '{}'::jsonb end,
    'is_pkp',v_is_pkp,'vat_transaction_code',case when v_is_pkp then v_tax_code else null end,
    'dpp',v_stock_dpp+v_service_dpp,'vat_amount',v_total_vat,'gross_amount',v_total_gross
  );
end;
$$;
