create or replace function private.create_tax_document_internal(
  p_tenant_id uuid,p_document_type text,p_transaction_ref text,p_business_date date,
  p_counterparty_id uuid,p_facility_context text,p_tax_snapshot jsonb,
  p_dpp bigint,p_tax_amount bigint,p_gross_amount bigint,p_journal_id uuid,
  p_invoice_status text,p_creditable_input_vat boolean,p_reference_document_id uuid,
  p_actor uuid,p_device_id text,p_reason text
) returns uuid
language plpgsql security definer set search_path=''
as $$
declare v_id uuid; v_code text; v_legal jsonb;
begin
  if p_actor is null or p_device_id is null or length(btrim(p_device_id))=0 or p_reason is null or length(btrim(p_reason))<3 then raise exception 'tax_document_audit_lineage_required' using errcode='22023'; end if;
  if p_dpp<0 or p_tax_amount<0 or p_gross_amount<0 or p_gross_amount<>p_dpp+p_tax_amount then raise exception 'invalid_tax_document_amounts' using errcode='23514'; end if;
  if jsonb_typeof(p_tax_snapshot)<>'object' or coalesce(p_tax_snapshot->>'legal_basis','')='' then raise exception 'tax_document_legal_rule_snapshot_required' using errcode='23514'; end if;
  v_code:=case when p_document_type in ('VAT_OUTPUT','VAT_INPUT','VAT_RETURN','VAT_REPLACEMENT','VAT_CANCELLATION') then private.resolve_vat_transaction_code(p_facility_context) else null end;
  v_legal:=jsonb_build_object(
    'legal_basis',p_tax_snapshot->>'legal_basis','tax_rate_id',p_tax_snapshot->>'tax_rate_id',
    'vat_transaction_code',v_code,'facility_context',upper(coalesce(p_facility_context,'NORMAL')),
    'snapshot_at',now()
  );
  insert into public.tax_documents(
    tenant_id,document_type,transaction_ref,reference_document_id,counterparty_id,business_date,
    vat_transaction_code,facility_context,dpp,tax_amount,gross_amount,tax_rate_snapshot,legal_rule_snapshot,
    invoice_status,creditable_input_vat,status,journal_id,actor_user_id,device_id,reason
  ) values(
    p_tenant_id,p_document_type,btrim(p_transaction_ref),p_reference_document_id,p_counterparty_id,p_business_date,
    v_code,upper(coalesce(p_facility_context,'NORMAL')),p_dpp,p_tax_amount,p_gross_amount,p_tax_snapshot,v_legal,
    p_invoice_status,p_creditable_input_vat,'VALIDATED',p_journal_id,p_actor,btrim(p_device_id),btrim(p_reason)
  ) returning tax_document_id into v_id;
  insert into public.tax_document_events(tax_document_id,tenant_id,event_type,details,actor_user_id,device_id,reason)
  values(v_id,p_tenant_id,'VALIDATED',jsonb_build_object('document_type',p_document_type,'transaction_ref',btrim(p_transaction_ref)),p_actor,btrim(p_device_id),btrim(p_reason));
  return v_id;
end;
$$;

create or replace function public.register_input_tax_invoice(
  p_tenant_id uuid,p_transaction_ref text,p_business_date date,p_counterparty_id uuid,
  p_facility_context text,p_tax_object_code text,p_dpp bigint,p_tax_amount bigint,p_gross_amount bigint,
  p_device_id text,p_app_version text,p_reason text
) returns uuid
language plpgsql security definer set search_path=''
as $$
declare v_actor uuid:=auth.uid(); v_tax jsonb; v_rate numeric; v_expected bigint; v_id uuid; v_code text;
begin
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  perform accounting_private.require_member_role(p_tenant_id,v_actor,array['owner','admin','accountant']);
  if p_reason is null or length(btrim(p_reason))<3 then raise exception 'audit_reason_required' using errcode='22023'; end if;
  if p_counterparty_id is null or not exists(select 1 from public.tax_parties tp where tp.tenant_id=p_tenant_id and tp.party_id=p_counterparty_id and tp.party_kind='VENDOR' and p_business_date between tp.valid_from and coalesce(tp.valid_to,date '9999-12-31')) then raise exception 'valid_vendor_tax_party_required' using errcode='23514'; end if;
  v_tax:=private.resolve_tax_rate_snapshot('PPN',upper(coalesce(nullif(btrim(p_tax_object_code),''),'NON_LUXURY')),p_business_date,'DEFAULT');
  v_code:=private.resolve_vat_transaction_code(p_facility_context);
  v_rate:=(v_tax->>'effective_rate')::numeric;
  v_expected:=case when v_code in ('07','08') then 0 else round(p_dpp::numeric*v_rate)::bigint end;
  if p_dpp<=0 or p_tax_amount<>v_expected or p_gross_amount<>p_dpp+p_tax_amount then raise exception 'input_tax_invoice_amount_mismatch' using errcode='23514'; end if;
  insert into public.tax_documents(
    tenant_id,document_type,transaction_ref,counterparty_id,business_date,vat_transaction_code,facility_context,
    dpp,tax_amount,gross_amount,tax_rate_snapshot,legal_rule_snapshot,invoice_status,creditable_input_vat,status,
    actor_user_id,device_id,reason
  ) values(
    p_tenant_id,'VAT_INPUT',btrim(p_transaction_ref),p_counterparty_id,p_business_date,v_code,upper(coalesce(p_facility_context,'NORMAL')),
    p_dpp,p_tax_amount,p_gross_amount,v_tax,
    jsonb_build_object('legal_basis',v_tax->>'legal_basis','vat_transaction_code',v_code,'facility_context',upper(coalesce(p_facility_context,'NORMAL')),'snapshot_at',now()),
    'PENDING',false,'DRAFT',v_actor,btrim(p_device_id),btrim(p_reason)
  ) returning tax_document_id into v_id;
  insert into public.tax_document_events(tax_document_id,tenant_id,event_type,details,actor_user_id,device_id,reason)
  values(v_id,p_tenant_id,'REGISTERED',jsonb_build_object('invoice_status','PENDING'),v_actor,btrim(p_device_id),btrim(p_reason));
  insert into private.audit_logs(tenant_id,actor_id,device_id,source,reason,action)
  values(p_tenant_id::text,v_actor,btrim(p_device_id),'tax_input_invoice',btrim(p_reason),'success');
  return v_id;
end;
$$;

create or replace function public.set_input_tax_invoice_validation(
  p_tax_document_id uuid,p_invoice_status text,p_creditable boolean,p_external_reference text,p_reason text
) returns void
language plpgsql security definer set search_path=''
as $$
declare v_doc public.tax_documents%rowtype; v_actor uuid:=auth.uid(); v_role text:=lower(coalesce(auth.jwt()->>'role',''));
begin
  if v_role<>'service_role' and not private.btp_is_super_admin() then raise exception 'tax invoice validation authority denied' using errcode='42501'; end if;
  if p_invoice_status not in ('VALID','INVALID') or p_reason is null or length(btrim(p_reason))<3 then raise exception 'invalid_tax_invoice_validation' using errcode='22023'; end if;
  select * into strict v_doc from public.tax_documents where tax_document_id=p_tax_document_id and document_type='VAT_INPUT' for update;
  if v_doc.status<>'DRAFT' or v_doc.invoice_status<>'PENDING' then raise exception 'tax_invoice_already_validated' using errcode='55000'; end if;
  if p_invoice_status='INVALID' and p_creditable then raise exception 'invalid_invoice_cannot_be_creditable' using errcode='23514'; end if;
  update public.tax_documents set invoice_status=p_invoice_status,creditable_input_vat=(p_invoice_status='VALID' and p_creditable),status='VALIDATED',coretax_reference=nullif(btrim(coalesce(p_external_reference,'')),''),updated_at=now() where tax_document_id=p_tax_document_id;
  insert into public.tax_document_events(tax_document_id,tenant_id,event_type,details,actor_user_id,device_id,reason)
  values(p_tax_document_id,v_doc.tenant_id,'INPUT_INVOICE_VALIDATED',jsonb_build_object('invoice_status',p_invoice_status,'creditable',p_creditable,'external_reference',p_external_reference),coalesce(v_actor,v_doc.actor_user_id),v_doc.device_id,btrim(p_reason));
end;
$$;

