    upper(btrim(p_certificate_status)),p_turnover_eligibility,nullif(upper(btrim(coalesce(p_tax_object,''))),''),p_metadata,v_actor,btrim(p_device_id),btrim(p_reason)
  ) returning party_id into v_id;
