create or replace function private.build_supplier_payment_lines(
  p_tenant_id uuid,p_business_date date,p_facts jsonb
) returns jsonb
language plpgsql stable security definer set search_path=''
as $$
declare
  v_gross bigint; v_base bigint; v_tax bigint:=0; v_net bigint; v_method text;
  v_party_id uuid; v_party public.tax_parties%rowtype; v_object text; v_tax_code text; v_rate_object text;
  v_tax_rule jsonb:='{}'::jsonb; v_rate numeric:=0; v_liability_account text:='2-2020'; v_payable_account text;
  v_payment_account text; v_journal jsonb:='[]'::jsonb; v_final_valid boolean:=false;
begin
  perform private.assert_no_accounting_fields(p_facts);
  if coalesce(p_facts->>'gross_liability','') !~ '^[1-9][0-9]*$' then raise exception 'gross_liability_required' using errcode='22023'; end if;
  v_gross:=(p_facts->>'gross_liability')::bigint;
  v_method:=upper(coalesce(p_facts->>'payment_method',''));
  if v_method='CASH' then v_payment_account:='1-1010'; elsif v_method='BANK' then v_payment_account:='1-1030'; else raise exception 'payment_method_must_be_cash_or_bank' using errcode='22023'; end if;
  begin v_party_id:=(p_facts->>'vendor_party_id')::uuid; exception when others then raise exception 'vendor_tax_party_required' using errcode='22023'; end;
  select * into strict v_party from public.tax_parties
  where tenant_id=p_tenant_id and party_id=v_party_id and party_kind='VENDOR'
    and valid_from<=p_business_date and (valid_to is null or valid_to>=p_business_date);

  v_object:=upper(coalesce(nullif(btrim(p_facts->>'tax_object'),''),'NONE'));
  if v_object='NONE' then
    v_net:=v_gross;
  else
    if coalesce(p_facts->>'pph_base','') !~ '^[1-9][0-9]*$' then raise exception 'pph_base_required_and_separate_from_vat_dpp' using errcode='22023'; end if;
    v_base:=(p_facts->>'pph_base')::bigint;
    if v_base>v_gross then raise exception 'pph_base_exceeds_liability' using errcode='23514'; end if;

    if v_object='LAND_BUILDING_RENT' then
      v_tax_code:='PPH_FINAL_4_2'; v_rate_object:='LAND_BUILDING_RENT'; v_payable_account:='2-2060';
    elsif v_object in ('SERVICE','ASSET_RENT_NON_LAND_BUILDING') then
      if upper(v_party.tax_regime)='PPH_FINAL_UMKM' then
        v_final_valid:=coalesce(v_party.turnover_eligibility,false)
          and v_party.certificate_status='VALID'
          and length(btrim(v_party.legal_basis))>=3;
        if not v_final_valid then raise exception 'vendor_final_tax_evidence_invalid' using errcode='23514'; end if;
        v_tax_code:='PPH_FINAL_UMKM'; v_rate_object:='TURNOVER'; v_payable_account:='2-2060';
      else
        v_tax_code:='PPH23'; v_rate_object:=v_object; v_payable_account:='2-2050';
      end if;
    elsif v_object in ('DIVIDEND','INTEREST','ROYALTY') then
      v_tax_code:='PPH23'; v_rate_object:=v_object; v_payable_account:='2-2050';
    else
      raise exception 'unsupported_vendor_tax_object' using errcode='22023';
    end if;
    v_tax_rule:=private.resolve_tax_rate_snapshot(v_tax_code,v_rate_object,p_business_date,'DEFAULT');
    v_rate:=(v_tax_rule->>'effective_rate')::numeric;
    v_tax:=round(v_base::numeric*v_rate)::bigint;
    if v_tax<=0 or v_tax>=v_gross then raise exception 'invalid_withholding_amount' using errcode='23514'; end if;
    v_net:=v_gross-v_tax;
  end if;

  v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code',v_liability_account,'debit',v_gross,'credit',0,'memo','Pelunasan utang supplier'));
  v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code',v_payment_account,'debit',0,'credit',v_net,'memo','Pembayaran vendor'));
  if v_tax>0 then v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code',v_payable_account,'debit',0,'credit',v_tax,'memo','Pajak dipotong saat bayar')); end if;
  return jsonb_build_object(
    'journal_lines',v_journal,'vendor_party_id',v_party_id,'gross_liability',v_gross,'cash_paid',v_net,
    'withholding_amount',v_tax,'withholding_base',coalesce(v_base,0),'tax_code',v_tax_code,'tax_object',v_rate_object,
    'tax_snapshot',v_tax_rule,'withholding_account',v_payable_account
  );
end;
$$;
revoke all on function private.build_supplier_payment_lines(uuid,date,jsonb) from public,anon,authenticated,service_role;

create or replace function private.build_sale_return_lines(
  p_tenant_id uuid,p_return_ref text,p_business_date date,p_facts jsonb,
  p_actor uuid,p_device_id text,p_reason text
) returns jsonb
language plpgsql security definer set search_path=''
as $$
declare
  v_original_ref text:=btrim(coalesce(p_facts->>'original_transaction_ref',''));
  v_orig public.accounting_transaction_evidence%rowtype; v_orig_line public.sale_line_evidence%rowtype;
  v_lines jsonb:=coalesce(p_facts->'lines','[]'::jsonb); v_req jsonb; v_line_key text; v_qty bigint;
  v_prev_qty bigint; v_prev_dpp bigint; v_prev_vat bigint; v_prev_cogs bigint; v_remaining bigint;
  v_dpp bigint; v_vat bigint; v_cogs bigint; v_total_dpp bigint:=0; v_total_vat bigint:=0; v_total_cogs bigint:=0;
  v_payment text; v_journal jsonb:='[]'::jsonb; v_return_evidence jsonb:='[]'::jsonb; v_first_tax jsonb:='{}'::jsonb;
begin
  perform private.assert_no_accounting_fields(p_facts);
  if v_original_ref='' or p_return_ref is null or length(btrim(p_return_ref))=0 then raise exception 'return_identity_required' using errcode='22023'; end if;
  select * into strict v_orig from public.accounting_transaction_evidence where tenant_id=p_tenant_id and transaction_ref=v_original_ref;
  if v_orig.transaction_type not in ('JUAL_TUNAI','JUAL_QRIS','JUAL_TRANSFER','JUAL_KREDIT') then raise exception 'original_transaction_is_not_sale' using errcode='23514'; end if;
  v_payment:=case v_orig.transaction_type when 'JUAL_TUNAI' then '1-1010' when 'JUAL_QRIS' then '1-1020' when 'JUAL_TRANSFER' then '1-1030' when 'JUAL_KREDIT' then '1-1050' end;
  if jsonb_typeof(v_lines)<>'array' or jsonb_array_length(v_lines)<1 or jsonb_array_length(v_lines)>50 then raise exception 'return_lines_required' using errcode='22023'; end if;

  for v_req in select value from jsonb_array_elements(v_lines) loop
    v_line_key:=btrim(coalesce(v_req->>'line_key',''));
    if v_line_key='' or coalesce(v_req->>'qty','') !~ '^[1-9][0-9]*$' then raise exception 'valid_return_line_key_and_qty_required' using errcode='22023'; end if;
    v_qty:=(v_req->>'qty')::bigint;
    select * into strict v_orig_line from public.sale_line_evidence where tenant_id=p_tenant_id and transaction_ref=v_original_ref and line_key=v_line_key;
    select coalesce(sum(quantity),0),coalesce(sum(dpp_reversed),0),coalesce(sum(vat_reversed),0),coalesce(sum(cogs_restored),0)
      into v_prev_qty,v_prev_dpp,v_prev_vat,v_prev_cogs
    from public.sale_return_line_evidence where tenant_id=p_tenant_id and original_transaction_ref=v_original_ref and line_key=v_line_key;
    v_remaining:=v_orig_line.quantity-v_prev_qty;
    if v_qty>v_remaining then raise exception 'return_quantity_exceeds_original_remaining' using errcode='23514'; end if;
    if v_qty=v_remaining then
      v_dpp:=v_orig_line.dpp-v_prev_dpp; v_vat:=v_orig_line.vat_amount-v_prev_vat; v_cogs:=v_orig_line.original_cogs-v_prev_cogs;
    else
      v_dpp:=round(v_orig_line.dpp::numeric*v_qty::numeric/v_orig_line.quantity::numeric)::bigint;
      v_vat:=round(v_orig_line.vat_amount::numeric*v_qty::numeric/v_orig_line.quantity::numeric)::bigint;
      v_cogs:=round(v_orig_line.original_cogs::numeric*v_qty::numeric/v_orig_line.quantity::numeric)::bigint;
    end if;
    if v_dpp<0 or v_vat<0 or v_cogs<0 then raise exception 'invalid_return_allocation' using errcode='23514'; end if;
    if v_orig_line.line_kind='STOCK' then
      if v_cogs<=0 then raise exception 'stock_return_original_cogs_required' using errcode='23514'; end if;
      perform inventory_private.average_restore_original(p_tenant_id,v_orig_line.product_id,v_qty,v_cogs,'return:'||btrim(p_return_ref)||':'||v_line_key,btrim(p_return_ref),v_original_ref,p_actor,p_device_id,p_reason);
    elsif v_cogs<>0 then raise exception 'service_return_cogs_must_be_zero' using errcode='23514'; end if;
    v_total_dpp:=v_total_dpp+v_dpp; v_total_vat:=v_total_vat+v_vat; v_total_cogs:=v_total_cogs+v_cogs;
    if v_first_tax='{}'::jsonb and v_orig_line.tax_snapshot<>'{}'::jsonb then v_first_tax:=v_orig_line.tax_snapshot; end if;
    v_return_evidence:=v_return_evidence||jsonb_build_array(jsonb_build_object('original_transaction_ref',v_original_ref,'line_key',v_line_key,'quantity',v_qty,'dpp_reversed',v_dpp,'vat_reversed',v_vat,'cogs_restored',v_cogs));
  end loop;
  if v_total_dpp<=0 then raise exception 'return_dpp_must_be_positive' using errcode='23514'; end if;
  v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','4-4030','debit',v_total_dpp,'credit',0,'memo','Retur penjualan'));
  if v_total_vat>0 then v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','2-2010','debit',v_total_vat,'credit',0,'memo','Pembalikan PPN penjualan')); end if;
  v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code',v_payment,'debit',0,'credit',v_total_dpp+v_total_vat,'memo','Pengembalian pembayaran/piutang'));
  if v_total_cogs>0 then
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','1-1040','debit',v_total_cogs,'credit',0,'memo','Barang retur kembali ke stok'));
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','5-5010','debit',0,'credit',v_total_cogs,'memo','Pembalikan harga modal asli'));
  end if;
  return jsonb_build_object('journal_lines',v_journal,'return_lines',v_return_evidence,'original_transaction_ref',v_original_ref,'dpp',v_total_dpp,'vat_amount',v_total_vat,'gross_amount',v_total_dpp+v_total_vat,'cogs_restored',v_total_cogs,'tax_snapshot',v_first_tax);
end;
$$;

create or replace function private.build_stock_opname_lines(
  p_tenant_id uuid,p_transaction_ref text,p_facts jsonb,p_actor uuid,p_device_id text,p_reason text
) returns jsonb
language plpgsql security definer set search_path=''
as $$
declare
  v_lines jsonb:=coalesce(p_facts->'lines','[]'::jsonb); v_line jsonb; v_i int:=0; v_product uuid; v_counted bigint; v_zero_cost bigint; v_adj jsonb;
  v_qty_delta bigint; v_value_delta bigint; v_short bigint:=0; v_over bigint:=0; v_journal jsonb:='[]'::jsonb; v_evidence_count bigint;
begin
  perform private.assert_no_accounting_fields(p_facts);
  if coalesce(p_facts->>'evidence_count','') !~ '^[1-9][0-9]*$' or coalesce((p_facts->>'approved')::boolean,false) is not true then raise exception 'stock_opname_approval_and_evidence_required' using errcode='22023'; end if;
  v_evidence_count:=(p_facts->>'evidence_count')::bigint;
  if jsonb_typeof(v_lines)<>'array' or jsonb_array_length(v_lines)<1 or jsonb_array_length(v_lines)>100 then raise exception 'stock_opname_lines_required' using errcode='22023'; end if;
  for v_line in select value from jsonb_array_elements(v_lines) loop
    v_i:=v_i+1;
    begin v_product:=(v_line->>'product_id')::uuid; exception when others then raise exception 'valid_product_id_required' using errcode='22023'; end;
    if coalesce(v_line->>'counted_qty','') !~ '^(0|[1-9][0-9]*)$' then raise exception 'counted_qty_must_be_nonnegative_integer' using errcode='22023'; end if;
    v_counted:=(v_line->>'counted_qty')::bigint;
    if coalesce(v_line->>'zero_stock_unit_cost','') ~ '^[1-9][0-9]*$' then v_zero_cost:=(v_line->>'zero_stock_unit_cost')::bigint; else v_zero_cost:=null; end if;
    v_adj:=inventory_private.average_adjust_to_count(p_tenant_id,v_product,v_counted,v_zero_cost,'opname:'||btrim(p_transaction_ref)||':'||v_i::text,btrim(p_transaction_ref),p_actor,p_device_id,p_reason);
    v_qty_delta:=(v_adj->>'quantity_delta')::bigint; v_value_delta:=(v_adj->>'value_delta')::bigint;
    if v_value_delta<0 then v_short:=v_short+(-v_value_delta); else v_over:=v_over+v_value_delta; end if;
  end loop;
  if v_short>0 then
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','6-6080','debit',v_short,'credit',0,'memo','Selisih stok kurang'));
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','1-1040','debit',0,'credit',v_short,'memo','Pengurangan persediaan opname'));
  end if;
  if v_over>0 then
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','1-1040','debit',v_over,'credit',0,'memo','Penambahan persediaan opname'));
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','4-4060','debit',0,'credit',v_over,'memo','Selisih stok lebih'));
  end if;
  if jsonb_array_length(v_journal)<2 then raise exception 'stock_opname_has_no_adjustment' using errcode='22023'; end if;
  return jsonb_build_object('journal_lines',v_journal,'shortage_value',v_short,'overage_value',v_over,'evidence_count',v_evidence_count);
end;
$$;

revoke all on function private.build_sale_return_lines(uuid,text,date,jsonb,uuid,text,text) from public,anon,authenticated,service_role;
revoke all on function private.build_stock_opname_lines(uuid,text,jsonb,uuid,text,text) from public,anon,authenticated,service_role;

create or replace function private.guard_tax_document_update()
returns trigger language plpgsql security definer set search_path=''
as $$
declare v_economic_changed boolean; v_journal_link_invalid boolean;
begin
  if tg_op='DELETE' then raise exception 'tax document history is immutable' using errcode='55000'; end if;
  v_economic_changed := (
    old.tenant_id,old.document_type,old.document_number,old.transaction_ref,old.reference_document_id,
    old.counterparty_id,old.business_date,old.vat_transaction_code,old.facility_context,
    old.dpp,old.tax_amount,old.gross_amount,old.tax_rate_snapshot,old.legal_rule_snapshot,
    old.invoice_status,old.creditable_input_vat,old.actor_user_id,old.device_id,old.reason,old.created_at
  ) is distinct from (
    new.tenant_id,new.document_type,new.document_number,new.transaction_ref,new.reference_document_id,
    new.counterparty_id,new.business_date,new.vat_transaction_code,new.facility_context,
    new.dpp,new.tax_amount,new.gross_amount,new.tax_rate_snapshot,new.legal_rule_snapshot,
    new.invoice_status,new.creditable_input_vat,new.actor_user_id,new.device_id,new.reason,new.created_at
  );
  v_journal_link_invalid := old.journal_id is not null and new.journal_id is distinct from old.journal_id;
  if v_journal_link_invalid then raise exception 'tax document journal linkage is immutable once set' using errcode='55000'; end if;
  if old.status<>'DRAFT' and v_economic_changed then raise exception 'validated/submitted tax document economics are immutable' using errcode='55000'; end if;
  if old.status in ('SUBMITTED','ACCEPTED','REPORTED','CANCELLED','REPLACED') and (v_economic_changed or new.journal_id is distinct from old.journal_id) then raise exception 'submitted/reported tax document is locked' using errcode='55000'; end if;
  if new.status=old.status then null;
  elsif old.status='DRAFT' and new.status in ('VALIDATED','CANCELLED') then null;
  elsif old.status='VALIDATED' and new.status in ('SUBMITTED','CANCELLED') then null;
  elsif old.status='SUBMITTED' and new.status in ('ACCEPTED','REJECTED') then null;
  elsif old.status='ACCEPTED' and new.status in ('REPORTED','CANCELLED','REPLACED') then null;
  elsif old.status='REJECTED' and new.status='CANCELLED' then null;
  else raise exception 'invalid tax document status transition % -> %',old.status,new.status using errcode='23514';
  end if;
  new.updated_at:=now(); return new;
end;
$$;

create or replace function private.create_tax_document_internal(
  p_tenant_id uuid,p_document_type text,p_transaction_ref text,p_business_date date,
  p_counterparty_id uuid,p_facility_context text,p_tax_snapshot jsonb,
  p_dpp bigint,p_tax_amount bigint,p_gross_amount bigint,p_journal_id uuid,
  p_invoice_status text,p_creditable_input_vat boolean,p_reference_document_id uuid,
  p_actor uuid,p_device_id text,p_reason text
) returns uuid
language plpgsql security definer set search_path=''
as $$
declare v_id uuid; v_code text; v_legal jsonb;
begin
  if p_actor is null or p_device_id is null or length(btrim(p_device_id))=0 or p_reason is null or length(btrim(p_reason))<3 then raise exception 'tax_document_audit_lineage_required' using errcode='22023'; end if;
  if p_dpp<0 or p_tax_amount<0 or p_gross_amount<0 then raise exception 'invalid_tax_document_amounts' using errcode='23514'; end if;
  if p_document_type in ('VAT_OUTPUT','VAT_INPUT','VAT_RETURN','VAT_REPLACEMENT','VAT_CANCELLATION') and p_gross_amount<>p_dpp+p_tax_amount then raise exception 'vat_document_gross_must_equal_dpp_plus_tax' using errcode='23514'; end if;
  if jsonb_typeof(p_tax_snapshot)<>'object' or coalesce(p_tax_snapshot->>'legal_basis','')='' then raise exception 'tax_document_legal_rule_snapshot_required' using errcode='23514'; end if;
  v_code:=case when p_document_type in ('VAT_OUTPUT','VAT_INPUT','VAT_RETURN','VAT_REPLACEMENT','VAT_CANCELLATION') then private.resolve_vat_transaction_code(p_facility_context) else null end;
  v_legal:=jsonb_build_object('legal_basis',p_tax_snapshot->>'legal_basis','tax_rate_id',p_tax_snapshot->>'tax_rate_id','vat_transaction_code',v_code,'facility_context',upper(coalesce(p_facility_context,'NORMAL')),'snapshot_at',now());
  insert into public.tax_documents(tenant_id,document_type,transaction_ref,reference_document_id,counterparty_id,business_date,vat_transaction_code,facility_context,dpp,tax_amount,gross_amount,tax_rate_snapshot,legal_rule_snapshot,invoice_status,creditable_input_vat,status,journal_id,actor_user_id,device_id,reason)
  values(p_tenant_id,p_document_type,btrim(p_transaction_ref),p_reference_document_id,p_counterparty_id,p_business_date,v_code,upper(coalesce(p_facility_context,'NORMAL')),p_dpp,p_tax_amount,p_gross_amount,p_tax_snapshot,v_legal,p_invoice_status,p_creditable_input_vat,'VALIDATED',p_journal_id,p_actor,btrim(p_device_id),btrim(p_reason))
  returning tax_document_id into v_id;
  insert into public.tax_document_events(tax_document_id,tenant_id,event_type,details,actor_user_id,device_id,reason)
  values(v_id,p_tenant_id,'VALIDATED',jsonb_build_object('document_type',p_document_type,'transaction_ref',btrim(p_transaction_ref)),p_actor,btrim(p_device_id),btrim(p_reason));
  return v_id;
end;
$$;
revoke all on function private.guard_tax_document_update() from public,anon,authenticated,service_role;
revoke all on function private.create_tax_document_internal(uuid,text,text,date,uuid,text,jsonb,bigint,bigint,bigint,uuid,text,boolean,uuid,uuid,text,text) from public,anon,authenticated,service_role;

create or replace function public.create_auto_journal(
  p_tenant_id uuid,
  p_transaction_type text,
  p_transaction_ref text,
  p_business_date date,
  p_facts jsonb,
  p_device_id text,
  p_app_version text,
  p_reason text
) returns uuid
language plpgsql
security definer
set search_path=''
as $$
declare
  v_actor uuid:=auth.uid(); v_member_role text; v_type text:=upper(btrim(coalesce(p_transaction_type,'')));
  v_fingerprint jsonb; v_existing public.accounting_transaction_evidence%rowtype; v_build jsonb; v_lines jsonb;
  v_source text; v_payment text; v_journal uuid; v_item jsonb; v_counterparty uuid; v_tax_doc uuid; v_original_tax public.tax_documents%rowtype;
  v_input_doc uuid; v_withholding bigint; v_tax_code text; v_required_bad int;
begin
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  v_member_role:=accounting_private.require_member_role(p_tenant_id,v_actor,array['owner','admin','accountant','cashier']);
  if p_reason is null or length(btrim(p_reason))<3 then raise exception 'audit_reason_required' using errcode='22023'; end if;
  if p_business_date is null or p_transaction_ref is null or length(btrim(p_transaction_ref))=0 then raise exception 'transaction_identity_required' using errcode='22023'; end if;
  if v_type not in ('JUAL_TUNAI','JUAL_QRIS','JUAL_TRANSFER','JUAL_KREDIT','BELI_KREDIT','BAYAR_VENDOR','RETUR_PENJUALAN','STOCK_OPNAME') then raise exception 'unsupported_transaction_template' using errcode='22023'; end if;
  if v_type in ('RETUR_PENJUALAN','STOCK_OPNAME') and v_member_role='cashier' then raise exception 'sensitive_transaction_requires_accounting_supervisor' using errcode='42501'; end if;
  perform private.assert_no_accounting_fields(p_facts);

  select count(*) into v_required_bad from (values
    ('1-1010','Aset Lancar','debit'),('1-1020','Aset Lancar','debit'),('1-1030','Aset Lancar','debit'),('1-1040','Aset Lancar','debit'),('1-1050','Aset Lancar','debit'),
    ('1-1090','Aset Lancar','debit'),('2-2010','Kewajiban','credit'),('2-2020','Kewajiban','credit'),('2-2050','Kewajiban','credit'),('2-2060','Kewajiban','credit'),
    ('4-4010','Pendapatan','credit'),('4-4030','Pendapatan','debit'),('4-4050','Pendapatan','credit'),('4-4060','Pendapatan','credit'),
    ('5-5010','HPP','debit'),('6-6080','Beban','debit')
  ) x(code,typ,bal)
  where not exists(select 1 from public.accounting_coa c where c.account_code=x.code and c.account_type=x.typ and c.normal_balance=x.bal);
  if v_required_bad<>0 then raise exception 'canonical COA mapping missing or semantically invalid' using errcode='23514'; end if;

  v_fingerprint:=jsonb_build_object('transaction_type',v_type,'transaction_ref',btrim(p_transaction_ref),'business_date',p_business_date::text,'facts',p_facts,'actor_user_id',v_actor::text,'device_id',btrim(p_device_id),'app_version',btrim(p_app_version),'reason',btrim(p_reason));
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||btrim(p_transaction_ref),7331));
  select * into v_existing from public.accounting_transaction_evidence where tenant_id=p_tenant_id and transaction_ref=btrim(p_transaction_ref);
  if found then
    if v_existing.request_fingerprint=v_fingerprint then return v_existing.journal_id; end if;
    raise exception 'transaction_idempotency_conflict' using errcode='23505';
  end if;

  case v_type
    when 'JUAL_TUNAI' then v_payment:='1-1010'; v_source:='pos_sale'; v_build:=private.build_sale_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_payment,v_actor,p_device_id,p_reason);
    when 'JUAL_QRIS' then v_payment:='1-1020'; v_source:='pos_sale'; v_build:=private.build_sale_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_payment,v_actor,p_device_id,p_reason);
    when 'JUAL_TRANSFER' then v_payment:='1-1030'; v_source:='pos_sale'; v_build:=private.build_sale_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_payment,v_actor,p_device_id,p_reason);
    when 'JUAL_KREDIT' then
      if nullif(btrim(coalesce(p_facts->>'customer_id','')),'') is null then raise exception 'customer_required_for_credit_sale' using errcode='22023'; end if;
      v_payment:='1-1050'; v_source:='pos_sale'; v_build:=private.build_sale_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_payment,v_actor,p_device_id,p_reason);
    when 'BELI_KREDIT' then
      if nullif(btrim(coalesce(p_facts->>'supplier_id','')),'') is null then raise exception 'supplier_required_for_credit_purchase' using errcode='22023'; end if;
      v_source:='purchase_receipt'; v_build:=private.build_purchase_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_actor,p_device_id,p_reason);
    when 'BAYAR_VENDOR' then v_source:='supplier_payment'; v_build:=private.build_supplier_payment_lines(p_tenant_id,p_business_date,p_facts);
    when 'RETUR_PENJUALAN' then v_source:='sale_return'; v_build:=private.build_sale_return_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_actor,p_device_id,p_reason);
    when 'STOCK_OPNAME' then v_source:='manual'; v_build:=private.build_stock_opname_lines(p_tenant_id,p_transaction_ref,p_facts,v_actor,p_device_id,p_reason);
  end case;
  v_lines:=v_build->'journal_lines';
  if jsonb_typeof(v_lines)<>'array' or jsonb_array_length(v_lines)<2 then raise exception 'auto_journal_builder_failed' using errcode='23514'; end if;

  v_journal:=accounting_private.post_journal(p_tenant_id,'auto:'||btrim(p_transaction_ref),btrim(p_transaction_ref),p_business_date,v_type,v_source,v_lines,p_device_id,p_app_version);
  insert into public.accounting_transaction_evidence(tenant_id,transaction_ref,transaction_type,business_date,request_fingerprint,facts_snapshot,tax_snapshot,journal_id,actor_user_id,device_id,app_version,reason)
  values(p_tenant_id,btrim(p_transaction_ref),v_type,p_business_date,v_fingerprint,p_facts,coalesce(v_build->'tax_snapshot','{}'::jsonb),v_journal,v_actor,btrim(p_device_id),btrim(p_app_version),btrim(p_reason));

  if v_type in ('JUAL_TUNAI','JUAL_QRIS','JUAL_TRANSFER','JUAL_KREDIT') then
    for v_item in select value from jsonb_array_elements(v_build->'sale_lines') loop
      insert into public.sale_line_evidence(tenant_id,transaction_ref,line_key,product_id,line_kind,quantity,revenue_account,dpp,vat_amount,gross_amount,original_cogs,tax_snapshot)
      values(p_tenant_id,btrim(p_transaction_ref),v_item->>'line_key',nullif(v_item->>'product_id','')::uuid,v_item->>'line_kind',(v_item->>'quantity')::bigint,v_item->>'revenue_account',(v_item->>'dpp')::bigint,(v_item->>'vat_amount')::bigint,(v_item->>'gross_amount')::bigint,(v_item->>'original_cogs')::bigint,coalesce(v_item->'tax_snapshot','{}'::jsonb));
    end loop;
    if coalesce((v_build->>'is_pkp')::boolean,false) then
      if p_facts ? 'customer_tax_party_id' and nullif(btrim(p_facts->>'customer_tax_party_id'),'') is not null then
        begin v_counterparty:=(p_facts->>'customer_tax_party_id')::uuid; exception when others then raise exception 'invalid_customer_tax_party_id' using errcode='22023'; end;
        if not exists(select 1 from public.tax_parties tp where tp.tenant_id=p_tenant_id and tp.party_id=v_counterparty and tp.party_kind='CUSTOMER' and tp.valid_from<=p_business_date and (tp.valid_to is null or tp.valid_to>=p_business_date)) then raise exception 'customer_tax_party_evidence_invalid' using errcode='23514'; end if;
      end if;
      v_tax_doc:=private.create_tax_document_internal(p_tenant_id,'VAT_OUTPUT',p_transaction_ref,p_business_date,v_counterparty,coalesce(v_build->'tax_snapshot'->>'facility_context','NORMAL'),v_build->'tax_snapshot',(v_build->>'dpp')::bigint,(v_build->>'vat_amount')::bigint,(v_build->>'gross_amount')::bigint,v_journal,'VALID',false,null,v_actor,p_device_id,p_reason);
    end if;
  elsif v_type='BELI_KREDIT' then
    if nullif(v_build->>'input_tax_document_id','') is not null then
      v_input_doc:=(v_build->>'input_tax_document_id')::uuid;
      update public.tax_documents set journal_id=v_journal,updated_at=now() where tax_document_id=v_input_doc and tenant_id=p_tenant_id and journal_id is null;
      if not found then raise exception 'input_tax_document_journal_link_failed' using errcode='23514'; end if;
      insert into public.tax_document_events(tax_document_id,tenant_id,event_type,details,actor_user_id,device_id,reason)
      values(v_input_doc,p_tenant_id,'JOURNAL_LINKED',jsonb_build_object('journal_id',v_journal),v_actor,btrim(p_device_id),btrim(p_reason));
    end if;
  elsif v_type='BAYAR_VENDOR' then
    v_withholding:=coalesce((v_build->>'withholding_amount')::bigint,0);
    if v_withholding>0 then
      v_tax_code:=v_build->>'tax_code';
      v_tax_doc:=private.create_tax_document_internal(
        p_tenant_id,case when v_tax_code='PPH23' then 'PPH23_UNIFICATION' else 'PPH_FINAL' end,
        p_transaction_ref,p_business_date,(v_build->>'vendor_party_id')::uuid,null,v_build->'tax_snapshot',
        (v_build->>'withholding_base')::bigint,v_withholding,(v_build->>'withholding_base')::bigint,v_journal,
        'VALID',false,null,v_actor,p_device_id,p_reason
      );
    end if;
  elsif v_type='RETUR_PENJUALAN' then
    for v_item in select value from jsonb_array_elements(v_build->'return_lines') loop
      insert into public.sale_return_line_evidence(tenant_id,return_transaction_ref,original_transaction_ref,line_key,quantity,dpp_reversed,vat_reversed,cogs_restored)
      values(p_tenant_id,btrim(p_transaction_ref),v_item->>'original_transaction_ref',v_item->>'line_key',(v_item->>'quantity')::bigint,(v_item->>'dpp_reversed')::bigint,(v_item->>'vat_reversed')::bigint,(v_item->>'cogs_restored')::bigint);
    end loop;
    select * into v_original_tax from public.tax_documents where tenant_id=p_tenant_id and document_type='VAT_OUTPUT' and transaction_ref=v_build->>'original_transaction_ref';
    if found then
      v_tax_doc:=private.create_tax_document_internal(p_tenant_id,'VAT_RETURN',p_transaction_ref,p_business_date,v_original_tax.counterparty_id,v_original_tax.facility_context,v_original_tax.tax_rate_snapshot,(v_build->>'dpp')::bigint,(v_build->>'vat_amount')::bigint,(v_build->>'gross_amount')::bigint,v_journal,'VALID',false,v_original_tax.tax_document_id,v_actor,p_device_id,p_reason);
    elsif (v_build->>'vat_amount')::bigint>0 then raise exception 'taxable_return_requires_original_tax_document' using errcode='23514'; end if;
  end if;

  insert into private.audit_logs(tenant_id,actor_id,device_id,source,reason,action)
  values(p_tenant_id::text,v_actor,btrim(p_device_id),'auto_journal:'||lower(v_type),btrim(p_reason),'success');
  return v_journal;
end;
$$;

