create or replace function public.assert_config_contract()
returns jsonb
language plpgsql
stable security definer set search_path=''
as $$
declare v_count int; v_digest text;
begin
  perform private.assert_app_config_inventory();
  select count(*)::int,md5(string_agg(key,E'\n' order by key)) into v_count,v_digest from public.app_config;
  if v_count<>352 or v_digest<>'1fd3d64219ecc7c333453c20da80e295' then
    raise exception 'app_config_contract_mismatch' using errcode='23514';
  end if;
  return jsonb_build_object('count',v_count,'keyset_md5',v_digest,'expected_count',352,'expected_keyset_md5','1fd3d64219ecc7c333453c20da80e295');
end;
$$;

create or replace function public.get_runtime_tax_snapshot(p_business_date date)
returns jsonb
language plpgsql
stable security definer set search_path=''
as $$
declare v_rules jsonb; v_ter jsonb; v_missing int;
begin
  if p_business_date is null then raise exception 'business_date_required' using errcode='22023'; end if;
  with active as (
    select tax_code,object_code,category,statutory_rate,dpp_multiplier,effective_rate,calculation_method,effective_date,end_date,legal_basis,metadata,
           count(*) over(partition by tax_code,object_code,category) as active_count
    from public.tax_rates
    where effective_date<=p_business_date and (end_date is null or end_date>=p_business_date)
  )
  select count(*) into v_missing from active where active_count<>1;
  if v_missing<>0 then raise exception 'effective_tax_rule_ambiguity' using errcode='23514'; end if;

  select coalesce(jsonb_object_agg(tax_code||':'||object_code||':'||category,
    jsonb_build_object('tax_code',tax_code,'object_code',object_code,'category',category,
      'statutory_rate',statutory_rate,'dpp_multiplier',dpp_multiplier,'effective_rate',effective_rate,
      'calculation_method',calculation_method,'effective_date',effective_date,'end_date',end_date,
      'legal_basis',legal_basis,'metadata',metadata)
    order by tax_code,object_code,category),'{}'::jsonb)
  into v_rules
  from public.tax_rates
  where effective_date<=p_business_date and (end_date is null or end_date>=p_business_date);

  select coalesce(jsonb_object_agg(category,jsonb_build_object('category',category,'effective_date',effective_date,'end_date',end_date,'legal_basis',legal_basis)),'{}'::jsonb)
  into v_ter
  from (
    select category,min(effective_date) effective_date,max(end_date) end_date,min(legal_basis) legal_basis
    from public.tax_rate_brackets
    where tax_code='PPH21_TER' and effective_date<=p_business_date and (end_date is null or end_date>=p_business_date)
    group by category
  ) q;

  if not (v_rules ? 'PPN:NON_LUXURY:DEFAULT') or not (v_rules ? 'PPN:LUXURY_CONSUMER:DEFAULT')
     or not (v_ter ? 'A') or not (v_ter ? 'B') or not (v_ter ? 'C') then
    raise exception 'required_runtime_tax_rule_missing' using errcode='23514';
  end if;
  return jsonb_build_object('business_date',p_business_date,'tax_rates',v_rules,'pph21_ter_categories',v_ter,'authority','public.tax_rates + public.tax_rate_brackets');
end;
$$;

revoke all on function public.assert_config_contract() from public,anon,authenticated;
grant execute on function public.assert_config_contract() to service_role;
revoke all on function public.get_runtime_tax_snapshot(date) from public,anon,authenticated;
grant execute on function public.get_runtime_tax_snapshot(date) to service_role;

create table public.coretax_template_registry (
  template_id uuid primary key default gen_random_uuid(),
  template_code text not null check (template_code in ('FAKTUR_KELUARAN','BPPU','BPMP')),
  template_version text not null,
  official_source_url text not null check (official_source_url like 'https://pajak.go.id/%' or official_source_url like 'https://www.pajak.go.id/%'),
  official_last_update date not null,
  xml_template text,
  generator_spec jsonb not null default '{}'::jsonb check (jsonb_typeof(generator_spec)='object'),
  template_sha256 text,
  is_verified boolean not null default false,
  is_active boolean not null default false,
  verified_by uuid references auth.users(id),
  verified_at timestamptz,
  created_at timestamptz not null default now(),
  check (not is_active or (is_verified and xml_template is not null and length(xml_template)>0 and template_sha256 ~ '^[0-9a-f]{64}$' and verified_by is not null and verified_at is not null))
);
create unique index coretax_template_version_uq on public.coretax_template_registry(template_code,template_version);
create unique index coretax_one_active_per_code_uq on public.coretax_template_registry(template_code) where is_active;

alter table public.coretax_template_registry enable row level security;
create policy coretax_template_read_authenticated on public.coretax_template_registry for select to authenticated using (true);
create policy coretax_template_insert_super_admin on public.coretax_template_registry for insert to authenticated with check (private.btp_is_super_admin());
create policy coretax_template_update_super_admin on public.coretax_template_registry for update to authenticated using (private.btp_is_super_admin()) with check (private.btp_is_super_admin());
revoke all on public.coretax_template_registry from anon,authenticated,service_role;
grant select on public.coretax_template_registry to authenticated,service_role;
grant insert,update on public.coretax_template_registry to authenticated;

create or replace function private.guard_coretax_template()
returns trigger language plpgsql security definer set search_path=''
as $$
begin
  if current_user<>'postgres' and not private.btp_is_super_admin() then raise exception 'coretax template mutation denied' using errcode='42501'; end if;
  if tg_op='DELETE' then raise exception 'coretax template history is immutable' using errcode='55000'; end if;
  if tg_op='UPDATE' then
    if old.is_verified and (old.template_code,old.template_version,old.official_source_url,old.official_last_update,old.xml_template,old.generator_spec,old.template_sha256,old.verified_by,old.verified_at)
      is distinct from (new.template_code,new.template_version,new.official_source_url,new.official_last_update,new.xml_template,new.generator_spec,new.template_sha256,new.verified_by,new.verified_at) then
      raise exception 'verified coretax template content is immutable' using errcode='55000';
    end if;
    if old.is_active and new.is_active then return new; end if;
    if old.is_active and not new.is_active then return new; end if;
    if not old.is_active and new.is_active and not new.is_verified then raise exception 'unverified coretax template cannot be activated' using errcode='23514'; end if;
  end if;
  return new;
end;
$$;
create trigger coretax_template_guard before insert or update or delete on public.coretax_template_registry for each row execute function private.guard_coretax_template();
revoke all on function private.guard_coretax_template() from public,anon,authenticated,service_role;

