create or replace function public.install_coretax_template(
  p_template_code text,p_template_version text,p_official_source_url text,p_official_last_update date,
  p_xml_template text,p_generator_spec jsonb,p_expected_sha256 text
) returns uuid
language plpgsql security definer set search_path=''
as $$
declare v_actor uuid:=auth.uid(); v_sha text; v_id uuid;
begin
  if not private.btp_is_super_admin() then raise exception 'canonical super_admin required' using errcode='42501'; end if;
  if p_template_code not in ('FAKTUR_KELUARAN','BPPU','BPMP') or p_template_version is null or length(btrim(p_template_version))<3 then raise exception 'invalid_coretax_template_identity' using errcode='22023'; end if;
  if p_official_source_url not like 'https://pajak.go.id/%' and p_official_source_url not like 'https://www.pajak.go.id/%' then raise exception 'official_djp_source_required' using errcode='23514'; end if;
  if p_xml_template is null or length(p_xml_template)<20 or p_generator_spec is null or jsonb_typeof(p_generator_spec)<>'object' then raise exception 'verified_xml_template_and_generator_spec_required' using errcode='22023'; end if;
  v_sha:=encode(extensions.digest(convert_to(p_xml_template,'UTF8'),'sha256'),'hex');
  if lower(coalesce(p_expected_sha256,''))<>v_sha then raise exception 'coretax_template_sha256_mismatch' using errcode='23514'; end if;

  update public.coretax_template_registry set is_active=false where template_code=p_template_code and is_active;
  update public.coretax_template_registry
  set official_source_url=p_official_source_url,official_last_update=p_official_last_update,
      xml_template=p_xml_template,generator_spec=p_generator_spec,template_sha256=v_sha,
      is_verified=true,is_active=true,verified_by=v_actor,verified_at=now()
  where template_code=p_template_code and template_version=p_template_version and not is_verified
  returning template_id into v_id;
  if v_id is null then
    insert into public.coretax_template_registry(template_code,template_version,official_source_url,official_last_update,xml_template,generator_spec,template_sha256,is_verified,is_active,verified_by,verified_at)
    values(p_template_code,p_template_version,p_official_source_url,p_official_last_update,p_xml_template,p_generator_spec,v_sha,true,true,v_actor,now()) returning template_id into v_id;
  end if;
  return v_id;
end;
$$;

create or replace function public.prepare_coretax_export_package(
  p_tax_document_id uuid,p_template_code text,p_device_id text,p_app_version text,p_reason text
) returns jsonb
language plpgsql security definer set search_path=''
as $$
declare
  v_actor uuid:=auth.uid(); v_doc public.tax_documents%rowtype; v_template public.coretax_template_registry%rowtype;
  v_self_count int; v_self public.tax_parties%rowtype; v_counter public.tax_parties%rowtype; v_expected_template text;
begin
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  perform accounting_private.require_member_role((select tenant_id from public.tax_documents where tax_document_id=p_tax_document_id),v_actor,array['owner','admin','accountant']);
  if p_reason is null or length(btrim(p_reason))<3 then raise exception 'audit_reason_required' using errcode='22023'; end if;
  select * into strict v_doc from public.tax_documents where tax_document_id=p_tax_document_id;
  perform private.assert_accounting_hard_gate(v_doc.tenant_id);
  if v_doc.status<>'VALIDATED' then raise exception 'tax_document_must_be_validated_before_export' using errcode='55000'; end if;
  if jsonb_typeof(v_doc.legal_rule_snapshot)<>'object' or nullif(btrim(v_doc.legal_rule_snapshot->>'legal_basis'),'') is null then raise exception 'tax_document_legal_snapshot_missing' using errcode='23514'; end if;
  v_expected_template:=case v_doc.document_type when 'VAT_OUTPUT' then 'FAKTUR_KELUARAN' when 'VAT_REPLACEMENT' then 'FAKTUR_KELUARAN' when 'PPH23_UNIFICATION' then 'BPPU' when 'PPH21_26' then 'BPMP' else null end;
  if v_expected_template is null or p_template_code<>v_expected_template then raise exception 'unsupported_or_mismatched_coretax_template' using errcode='23514'; end if;
  select * into strict v_template from public.coretax_template_registry where template_code=p_template_code and is_active and is_verified;
  if v_template.xml_template is null or v_template.template_sha256 is null or coalesce(v_template.generator_spec->>'status','')='SOURCE_REGISTERED_NOT_PARSED' then raise exception 'official_coretax_template_not_verified' using errcode='23514'; end if;
  select count(*) into v_self_count from public.tax_parties p where p.tenant_id=v_doc.tenant_id and p.party_kind='SELF' and p.valid_from<=v_doc.business_date and (p.valid_to is null or p.valid_to>=v_doc.business_date) and p.certificate_status='VALID';
  if v_self_count<>1 then raise exception 'exactly_one_valid_self_tax_identity_required' using errcode='23514'; end if;
  select * into strict v_self from public.tax_parties p where p.tenant_id=v_doc.tenant_id and p.party_kind='SELF' and p.valid_from<=v_doc.business_date and (p.valid_to is null or p.valid_to>=v_doc.business_date) and p.certificate_status='VALID';
  if v_doc.counterparty_id is not null then select * into strict v_counter from public.tax_parties where tenant_id=v_doc.tenant_id and party_id=v_doc.counterparty_id; end if;
  return jsonb_build_object(
    'template',jsonb_build_object('template_id',v_template.template_id,'template_code',v_template.template_code,'template_version',v_template.template_version,'xml_template',v_template.xml_template,'generator_spec',v_template.generator_spec,'template_sha256',v_template.template_sha256,'official_source_url',v_template.official_source_url),
    'data',jsonb_build_object('document',to_jsonb(v_doc),'self',to_jsonb(v_self),'counterparty',case when v_doc.counterparty_id is null then null else to_jsonb(v_counter) end),
    'actor_user_id',v_actor,'device_id',btrim(p_device_id),'reason',btrim(p_reason)
  );
exception when no_data_found then
  raise exception 'coretax_export_dependency_missing' using errcode='23514';
end;
$$;

create or replace function public.save_coretax_export_internal(
  p_tax_document_id uuid,p_template_id uuid,p_xml_payload text,p_actor_user_id uuid,p_device_id text,p_reason text
) returns uuid
language plpgsql security definer set search_path=''
as $$
declare v_role text:=lower(coalesce(auth.jwt()->>'role','')); v_doc public.tax_documents%rowtype; v_template public.coretax_template_registry%rowtype; v_outbox uuid; v_sha text;
begin
  if v_role<>'service_role' then raise exception 'service_role required' using errcode='42501'; end if;
  select * into strict v_doc from public.tax_documents where tax_document_id=p_tax_document_id for update;
  perform private.assert_accounting_hard_gate(v_doc.tenant_id);
  if v_doc.status<>'VALIDATED' then raise exception 'tax_document_must_be_validated_before_export' using errcode='55000'; end if;
  select * into strict v_template from public.coretax_template_registry where template_id=p_template_id and is_active and is_verified;
  if p_xml_payload is null or length(p_xml_payload)<20 or p_actor_user_id is null or p_device_id is null or length(btrim(p_reason))<3 then raise exception 'invalid_coretax_export_payload' using errcode='22023'; end if;
  if position('{{' in p_xml_payload)>0 or position('}}' in p_xml_payload)>0 then raise exception 'unresolved_coretax_xml_placeholder' using errcode='23514'; end if;
  v_sha:=encode(extensions.digest(convert_to(p_xml_payload,'UTF8'),'sha256'),'hex');
  insert into public.coretax_outbox(tax_document_id,tenant_id,xml_template_code,xml_payload,payload_sha256,status)
  values(p_tax_document_id,v_doc.tenant_id,v_template.template_code,p_xml_payload,v_sha,'EXPORTED') returning outbox_id into v_outbox;
  insert into public.tax_document_events(tax_document_id,tenant_id,event_type,details,actor_user_id,device_id,reason)
  values(p_tax_document_id,v_doc.tenant_id,'XML_EXPORTED',jsonb_build_object('outbox_id',v_outbox,'template_code',v_template.template_code,'template_version',v_template.template_version,'payload_sha256',v_sha),p_actor_user_id,btrim(p_device_id),btrim(p_reason));
  return v_outbox;
end;
$$;

create or replace function public.mark_coretax_submitted(
  p_outbox_id uuid,p_coretax_reference text,p_device_id text,p_app_version text,p_reason text
) returns void
language plpgsql security definer set search_path=''
as $$
declare v_actor uuid:=auth.uid(); v_o public.coretax_outbox%rowtype; v_doc public.tax_documents%rowtype;
begin
  select * into strict v_o from public.coretax_outbox where outbox_id=p_outbox_id for update;
  select * into strict v_doc from public.tax_documents where tax_document_id=v_o.tax_document_id for update;
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  perform accounting_private.require_member_role(v_doc.tenant_id,v_actor,array['owner','admin','accountant']);
  perform private.assert_accounting_hard_gate(v_doc.tenant_id);
  if v_o.status not in ('EXPORTED','REJECTED') or v_doc.status not in ('VALIDATED','REJECTED') then raise exception 'coretax_submission_state_invalid' using errcode='55000'; end if;
  if p_coretax_reference is null or length(btrim(p_coretax_reference))<3 or p_reason is null or length(btrim(p_reason))<3 then raise exception 'coretax_reference_and_reason_required' using errcode='22023'; end if;
  update public.coretax_outbox set status='SENT',ack_reference=btrim(p_coretax_reference),attempt_count=attempt_count+1,updated_at=now() where outbox_id=p_outbox_id;
  update public.tax_documents set status='SUBMITTED',coretax_reference=btrim(p_coretax_reference),updated_at=now() where tax_document_id=v_doc.tax_document_id;
  insert into public.tax_document_events(tax_document_id,tenant_id,event_type,details,actor_user_id,device_id,reason)
  values(v_doc.tax_document_id,v_doc.tenant_id,'SUBMITTED',jsonb_build_object('outbox_id',p_outbox_id,'coretax_reference',btrim(p_coretax_reference)),v_actor,btrim(p_device_id),btrim(p_reason));
end;
$$;

create or replace function public.record_coretax_result(
  p_outbox_id uuid,p_result text,p_reference text,p_details jsonb,p_device_id text,p_app_version text,p_reason text
) returns void
language plpgsql security definer set search_path=''
as $$
declare v_actor uuid:=auth.uid(); v_o public.coretax_outbox%rowtype; v_doc public.tax_documents%rowtype; v_result text:=upper(btrim(coalesce(p_result,'')));
begin
  if v_result not in ('ACK','REJECTED') or p_details is null or jsonb_typeof(p_details)<>'object' or p_reason is null or length(btrim(p_reason))<3 then raise exception 'invalid_coretax_result' using errcode='22023'; end if;
  select * into strict v_o from public.coretax_outbox where outbox_id=p_outbox_id for update;
  select * into strict v_doc from public.tax_documents where tax_document_id=v_o.tax_document_id for update;
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  perform accounting_private.require_member_role(v_doc.tenant_id,v_actor,array['owner','admin','accountant']);
  if v_o.status<>'SENT' or v_doc.status<>'SUBMITTED' then raise exception 'coretax_result_state_invalid' using errcode='55000'; end if;
  if v_result='ACK' then
    update public.coretax_outbox set status='ACK',ack_reference=coalesce(nullif(btrim(coalesce(p_reference,'')),''),ack_reference),rejection_detail='{}'::jsonb,updated_at=now() where outbox_id=p_outbox_id;
    update public.tax_documents set status='ACCEPTED',coretax_reference=coalesce(nullif(btrim(coalesce(p_reference,'')),''),coretax_reference),updated_at=now() where tax_document_id=v_doc.tax_document_id;
  else
    update public.coretax_outbox set status='REJECTED',rejection_detail=p_details,updated_at=now() where outbox_id=p_outbox_id;
    update public.tax_documents set status='REJECTED',updated_at=now() where tax_document_id=v_doc.tax_document_id;
  end if;
  insert into public.tax_document_events(tax_document_id,tenant_id,event_type,details,actor_user_id,device_id,reason)
  values(v_doc.tax_document_id,v_doc.tenant_id,'CORETAX_'||v_result,p_details||jsonb_build_object('outbox_id',p_outbox_id,'reference',p_reference),v_actor,btrim(p_device_id),btrim(p_reason));
end;
$$;

create or replace function public.get_coretax_status(p_tax_document_id uuid)
returns jsonb language plpgsql stable security definer set search_path=''
as $$
declare v_actor uuid:=auth.uid(); v_doc public.tax_documents%rowtype; v_out jsonb; v_pay jsonb;
begin
  select * into strict v_doc from public.tax_documents where tax_document_id=p_tax_document_id;
  perform accounting_private.require_member_role(v_doc.tenant_id,v_actor,array['owner','admin','accountant']);
  select coalesce(jsonb_agg(to_jsonb(o) order by o.created_at desc),'[]'::jsonb) into v_out from public.coretax_outbox o where o.tax_document_id=p_tax_document_id;
  select coalesce(jsonb_agg(to_jsonb(p) order by p.created_at desc),'[]'::jsonb) into v_pay from public.tax_payment_refs p where p.tax_document_id=p_tax_document_id;
  return jsonb_build_object('document_status',v_doc.status,'invoice_status',v_doc.invoice_status,'coretax_reference',v_doc.coretax_reference,'sealed_hash',v_doc.sealed_hash,'outbox',v_out,'payments',v_pay);
end;
$$;

create or replace function public.register_tax_payment_reference(
  p_tenant_id uuid,p_tax_document_id uuid,p_billing_code text,p_amount bigint,p_device_id text,p_app_version text,p_reason text
) returns uuid language plpgsql security definer set search_path=''
as $$
declare v_actor uuid:=auth.uid(); v_id uuid;
