do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid='public.product_master'::regclass
      and conname='product_master_vat_object_code_check'
  ) then
    alter table public.product_master
      add constraint product_master_vat_object_code_check
      check (vat_object_code in ('NON_LUXURY','LUXURY_CONSUMER'));
