end $$;

create table if not exists public.service_tax_profiles (
  tenant_id uuid not null references public.accounting_tenants(tenant_id),
  service_profile_id uuid not null default gen_random_uuid(),
  service_code text not null check (length(btrim(service_code))>=1),
  name_id text not null check (length(btrim(name_id))>=1),
  vat_exempt boolean not null default false,
  vat_object_code text not null default 'NON_LUXURY'
    check (vat_object_code in ('NON_LUXURY','LUXURY_CONSUMER')),
  valid_from date not null,
  valid_to date,
  legal_basis text not null check (length(btrim(legal_basis))>=3),
  actor_user_id uuid not null references auth.users(id),
  device_id text not null check (length(btrim(device_id))>=1),
  reason text not null check (length(btrim(reason))>=3),
  created_at timestamptz not null default now(),
  primary key(tenant_id,service_profile_id),
  unique(tenant_id,service_code,valid_from),
  check(valid_to is null or valid_to>=valid_from)
);

alter table public.service_tax_profiles enable row level security;
drop policy if exists service_tax_profiles_member_read on public.service_tax_profiles;
create policy service_tax_profiles_member_read
on public.service_tax_profiles for select to authenticated
using (
  auth.uid() is not null and exists(
    select 1 from public.accounting_memberships m
    where m.tenant_id=service_tax_profiles.tenant_id
      and m.user_id=(select auth.uid()) and m.is_active
  )
);
revoke all on public.service_tax_profiles from anon,authenticated,service_role;
grant select on public.service_tax_profiles to authenticated,service_role;

create or replace function private.guard_service_tax_profile()
returns trigger language plpgsql security definer set search_path=''
as $$
declare v_overlap boolean;
begin
  if current_user<>'postgres' then
    raise exception 'service tax profile direct mutation denied' using errcode='42501';
  end if;
  if tg_op='DELETE' then
    raise exception 'service tax profile history is immutable; close with valid_to' using errcode='55000';
  end if;
  if new.valid_to is not null and new.valid_to<new.valid_from then
    raise exception 'invalid service tax profile period' using errcode='23514';
  end if;
  if tg_op='UPDATE' and old.valid_from<=current_date then
    if (old.tenant_id,old.service_profile_id,old.service_code,old.name_id,old.vat_exempt,old.vat_object_code,old.valid_from,old.legal_basis,old.actor_user_id,old.device_id,old.reason,old.created_at)
       is distinct from
       (new.tenant_id,new.service_profile_id,new.service_code,new.name_id,new.vat_exempt,new.vat_object_code,new.valid_from,new.legal_basis,new.actor_user_id,new.device_id,new.reason,new.created_at) then
      raise exception 'historical service tax profile is immutable' using errcode='55000';
    end if;
    if old.valid_to is not null and new.valid_to is distinct from old.valid_to then
      raise exception 'closed service tax profile is immutable' using errcode='55000';
    end if;
    if old.valid_to is null and new.valid_to is not null and new.valid_to<current_date then
      raise exception 'service tax profile cannot close retroactively' using errcode='55000';
    end if;
  end if;
  select exists(
    select 1 from public.service_tax_profiles s
    where s.tenant_id=new.tenant_id
      and s.service_code=new.service_code
      and s.service_profile_id<>new.service_profile_id
      and daterange(s.valid_from,coalesce(s.valid_to+1,'infinity'::date),'[)')
          && daterange(new.valid_from,coalesce(new.valid_to+1,'infinity'::date),'[)')
  ) into v_overlap;
  if v_overlap then raise exception 'overlapping service tax profiles' using errcode='23514'; end if;
  return new;
end;
$$;

drop trigger if exists service_tax_profiles_guard on public.service_tax_profiles;
create trigger service_tax_profiles_guard before insert or update or delete
on public.service_tax_profiles for each row execute function private.guard_service_tax_profile();
revoke all on function private.guard_service_tax_profile() from public,anon,authenticated,service_role;

create or replace function public.create_service_tax_profile(
  p_tenant_id uuid,p_service_code text,p_name_id text,p_vat_exempt boolean,p_vat_object_code text,
  p_valid_from date,p_valid_to date,p_legal_basis text,p_device_id text,p_app_version text,p_reason text
) returns uuid
language plpgsql security definer set search_path=''
as $$
declare v_actor uuid:=auth.uid(); v_id uuid;
begin
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  perform accounting_private.require_member_role(p_tenant_id,v_actor,array['owner','admin','accountant']);
  if p_service_code is null or length(btrim(p_service_code))<1 or p_name_id is null or length(btrim(p_name_id))<1 then raise exception 'service_identity_required' using errcode='22023'; end if;
  if p_vat_object_code not in ('NON_LUXURY','LUXURY_CONSUMER') then raise exception 'invalid_vat_object_code' using errcode='22023'; end if;
  if p_valid_from is null or (p_valid_to is not null and p_valid_to<p_valid_from) then raise exception 'invalid_service_tax_profile_period' using errcode='22023'; end if;
  if p_legal_basis is null or length(btrim(p_legal_basis))<3 or p_reason is null or length(btrim(p_reason))<3 then raise exception 'service_tax_evidence_required' using errcode='22023'; end if;
  insert into public.service_tax_profiles(tenant_id,service_code,name_id,vat_exempt,vat_object_code,valid_from,valid_to,legal_basis,actor_user_id,device_id,reason)
  values(p_tenant_id,upper(btrim(p_service_code)),btrim(p_name_id),coalesce(p_vat_exempt,false),p_vat_object_code,p_valid_from,p_valid_to,btrim(p_legal_basis),v_actor,btrim(p_device_id),btrim(p_reason))
  returning service_profile_id into v_id;
  insert into private.audit_logs(tenant_id,actor_id,device_id,source,reason,action)
  values(p_tenant_id::text,v_actor,btrim(p_device_id),'service_tax_profile:create:'||v_id::text,btrim(p_reason),'success');
  return v_id;
end;
$$;

create or replace function public.close_service_tax_profile(
  p_tenant_id uuid,p_service_profile_id uuid,p_valid_to date,p_device_id text,p_app_version text,p_reason text
) returns void
language plpgsql security definer set search_path=''
as $$
declare v_actor uuid:=auth.uid(); v_old public.service_tax_profiles%rowtype;
begin
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  perform accounting_private.require_member_role(p_tenant_id,v_actor,array['owner','admin','accountant']);
  if p_reason is null or length(btrim(p_reason))<3 then raise exception 'audit_reason_required' using errcode='22023'; end if;
  select * into strict v_old from public.service_tax_profiles
  where tenant_id=p_tenant_id and service_profile_id=p_service_profile_id for update;
  if v_old.valid_to is not null then raise exception 'service_tax_profile_already_closed' using errcode='55000'; end if;
  if p_valid_to is null or p_valid_to<v_old.valid_from or p_valid_to<current_date then raise exception 'service_tax_profile_cannot_close_retroactively' using errcode='55000'; end if;
  update public.service_tax_profiles set valid_to=p_valid_to
  where tenant_id=p_tenant_id and service_profile_id=p_service_profile_id;
  insert into private.audit_logs(tenant_id,actor_id,device_id,source,reason,action)
  values(p_tenant_id::text,v_actor,btrim(p_device_id),'service_tax_profile:close:'||p_service_profile_id::text,btrim(p_reason),'success');
end;
$$;

revoke all on function public.create_service_tax_profile(uuid,text,text,boolean,text,date,date,text,text,text,text) from public,anon,service_role;
grant execute on function public.create_service_tax_profile(uuid,text,text,boolean,text,date,date,text,text,text,text) to authenticated;
revoke all on function public.close_service_tax_profile(uuid,uuid,date,text,text,text) from public,anon,service_role;
grant execute on function public.close_service_tax_profile(uuid,uuid,date,text,text,text) to authenticated;

create or replace function private.build_sale_lines(
  p_tenant_id uuid,p_transaction_ref text,p_business_date date,p_facts jsonb,
  p_payment_account text,p_actor uuid,p_device_id text,p_reason text
) returns jsonb
language plpgsql security definer set search_path=''
as $$
declare
  v_lines jsonb:=coalesce(p_facts->'lines','[]'::jsonb);
  v_line jsonb; v_i int:=0; v_line_key text; v_kind text; v_product uuid; v_service uuid; v_qty bigint; v_amount bigint;
  v_self_count int; v_self public.tax_parties%rowtype; v_is_pkp boolean;
  v_inclusive boolean:=coalesce((p_facts->>'prices_include_vat')::boolean,false);
  v_facility text:=upper(coalesce(nullif(btrim(p_facts->>'facility_context'),''),'NORMAL'));
  v_master_exempt boolean; v_line_taxable boolean; v_line_object text;
  v_tax jsonb:='{}'::jsonb; v_line_tax jsonb:='{}'::jsonb; v_tax_rules jsonb:='[]'::jsonb; v_rate numeric:=0; v_tax_code text;
  v_dpp bigint; v_vat bigint; v_gross bigint; v_cogs bigint:=0;
  v_stock_dpp bigint:=0; v_service_dpp bigint:=0; v_taxable_dpp bigint:=0; v_taxable_gross bigint:=0; v_total_vat bigint:=0; v_total_gross bigint:=0; v_total_cogs bigint:=0;
  v_any_taxable boolean:=false; v_sale_evidence jsonb:='[]'::jsonb; v_journal jsonb:='[]'::jsonb;
begin
  perform private.assert_no_accounting_fields(p_facts);
  if p_payment_account not in ('1-1010','1-1020','1-1030','1-1050') then raise exception 'invalid_internal_payment_mapping' using errcode='23514'; end if;
  if p_transaction_ref is null or length(btrim(p_transaction_ref))=0 or p_business_date is null then raise exception 'sale_identity_required' using errcode='22023'; end if;
  if jsonb_typeof(v_lines)<>'array' or jsonb_array_length(v_lines)<1 or jsonb_array_length(v_lines)>50 then raise exception 'sale_lines_required' using errcode='22023'; end if;
  if v_facility='ASSET_16D' then raise exception 'asset_16d_not_supported_by_pos_sale_intent' using errcode='22023'; end if;
  v_tax_code:=private.resolve_vat_transaction_code(v_facility);

  select count(*) into v_self_count from public.tax_parties tp
  where tp.tenant_id=p_tenant_id and tp.party_kind='SELF'
    and tp.valid_from<=p_business_date and (tp.valid_to is null or tp.valid_to>=p_business_date)
    and ((tp.is_pkp and tp.certificate_status='VALID') or (not tp.is_pkp and tp.certificate_status in ('VALID','NOT_REQUIRED')));
  if v_self_count<>1 then raise exception 'exactly_one_effective_self_tax_profile_required' using errcode='23514'; end if;
  select * into strict v_self from public.tax_parties tp
  where tp.tenant_id=p_tenant_id and tp.party_kind='SELF'
    and tp.valid_from<=p_business_date and (tp.valid_to is null or tp.valid_to>=p_business_date)
    and ((tp.is_pkp and tp.certificate_status='VALID') or (not tp.is_pkp and tp.certificate_status in ('VALID','NOT_REQUIRED')));
  v_is_pkp:=v_self.is_pkp;
  if p_facts ? 'is_pkp' and coalesce((p_facts->>'is_pkp')::boolean,false) is distinct from v_is_pkp then
    raise exception 'tenant_pkp_status_mismatch' using errcode='23514';
  end if;

  for v_line in select value from jsonb_array_elements(v_lines) loop
    v_i:=v_i+1;
    v_line_key:=coalesce(nullif(btrim(v_line->>'line_key'),''),v_i::text);
    v_kind:=upper(coalesce(v_line->>'kind',''));
    if v_kind not in ('STOCK','SERVICE') then raise exception 'invalid_sale_line_kind' using errcode='22023'; end if;
    if coalesce(v_line->>'qty','') !~ '^[1-9][0-9]*$' or coalesce(v_line->>'amount','') !~ '^[1-9][0-9]*$' then raise exception 'sale_qty_amount_must_be_positive_integer_rupiah' using errcode='22023'; end if;
    v_qty:=(v_line->>'qty')::bigint; v_amount:=(v_line->>'amount')::bigint;

    if v_kind='STOCK' then
      begin v_product:=(v_line->>'product_id')::uuid; exception when others then raise exception 'valid_product_id_required_for_stock_line' using errcode='22023'; end;
      select p.ppn_exempt,p.vat_object_code into strict v_master_exempt,v_line_object
      from public.product_master p
      where p.tenant_id=p_tenant_id and p.product_id=v_product and p.is_active;
      v_service:=null;
    else
      if v_line ? 'product_id' and nullif(btrim(v_line->>'product_id'),'') is not null then raise exception 'service_line_cannot_reference_inventory_product' using errcode='22023'; end if;
      begin v_service:=(v_line->>'service_profile_id')::uuid; exception when others then raise exception 'service_profile_id_required' using errcode='22023'; end;
      select s.vat_exempt,s.vat_object_code into strict v_master_exempt,v_line_object
      from public.service_tax_profiles s
      where s.tenant_id=p_tenant_id and s.service_profile_id=v_service
        and s.valid_from<=p_business_date and (s.valid_to is null or s.valid_to>=p_business_date);
      v_product:=null;
    end if;

    v_line_taxable:=v_is_pkp and not v_master_exempt;
    if v_line ? 'taxable' and (v_line->>'taxable')::boolean is distinct from v_line_taxable then
      raise exception 'sale_line_taxability_mismatch' using errcode='23514';
    end if;
    if v_line ? 'tax_object_code' and upper(btrim(v_line->>'tax_object_code')) is distinct from v_line_object then
      raise exception 'sale_line_tax_object_mismatch' using errcode='23514';
    end if;

    v_line_tax:='{}'::jsonb; v_rate:=0;
    if v_line_taxable then
      v_line_tax:=private.resolve_tax_rate_snapshot('PPN',v_line_object,p_business_date,'DEFAULT');
      v_rate:=(v_line_tax->>'effective_rate')::numeric;
      v_any_taxable:=true;
      v_tax_rules:=v_tax_rules||jsonb_build_array(jsonb_build_object('line_key',v_line_key,'object_code',v_line_object,'rule',v_line_tax));
      if v_tax='{}'::jsonb then v_tax:=v_line_tax; end if;
    end if;

    if v_line_taxable and v_facility='NORMAL' then
      if v_inclusive then
        v_dpp:=round(v_amount::numeric/(1+v_rate))::bigint;
        v_vat:=v_amount-v_dpp;
        v_gross:=v_amount;
      else
        v_dpp:=v_amount;
        v_vat:=round(v_dpp::numeric*v_rate)::bigint;
        v_gross:=v_dpp+v_vat;
      end if;
    else
      v_dpp:=v_amount; v_vat:=0; v_gross:=v_amount;
    end if;
    if v_dpp<=0 or v_gross<=0 or v_vat<0 then raise exception 'invalid_sale_tax_calculation' using errcode='23514'; end if;

    if v_kind='STOCK' then
      v_cogs:=inventory_private.average_consume(p_tenant_id,v_product,v_qty,'sale:'||btrim(p_transaction_ref)||':'||v_line_key,btrim(p_transaction_ref),p_actor,p_device_id,p_reason);
      if v_cogs<=0 then raise exception 'stocked_sale_cogs_must_be_positive' using errcode='23514'; end if;
      v_stock_dpp:=v_stock_dpp+v_dpp; v_total_cogs:=v_total_cogs+v_cogs;
    else
      v_cogs:=0; v_service_dpp:=v_service_dpp+v_dpp;
    end if;
    if v_line_taxable then v_taxable_dpp:=v_taxable_dpp+v_dpp; v_taxable_gross:=v_taxable_gross+v_gross; end if;
    v_total_vat:=v_total_vat+v_vat; v_total_gross:=v_total_gross+v_gross;
    v_sale_evidence:=v_sale_evidence||jsonb_build_array(jsonb_build_object(
      'line_key',v_line_key,'line_kind',v_kind,'product_id',v_product,'service_profile_id',v_service,'quantity',v_qty,
      'revenue_account',case when v_kind='STOCK' then '4-4010' else '4-4050' end,
      'dpp',v_dpp,'vat_amount',v_vat,'gross_amount',v_gross,'original_cogs',v_cogs,'taxable',v_line_taxable,
      'tax_snapshot',case when v_line_taxable then v_line_tax||jsonb_build_object('vat_transaction_code',v_tax_code,'facility_context',v_facility,'object_code',v_line_object) else jsonb_build_object('taxable',false,'master_exempt',v_master_exempt) end
    ));
  end loop;

  v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code',p_payment_account,'debit',v_total_gross,'credit',0,'memo','Pembayaran penjualan'));
  if v_stock_dpp>0 then v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','4-4010','debit',0,'credit',v_stock_dpp,'memo','Penjualan barang')); end if;
  if v_service_dpp>0 then v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','4-4050','debit',0,'credit',v_service_dpp,'memo','Pendapatan jasa')); end if;
  if v_total_vat>0 then v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','2-2010','debit',0,'credit',v_total_vat,'memo','PPN dari penjualan')); end if;
  if v_total_cogs>0 then
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','5-5010','debit',v_total_cogs,'credit',0,'memo','Harga modal rata-rata otomatis'));
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','1-1040','debit',0,'credit',v_total_cogs,'memo','Pengurangan persediaan'));
  end if;
  return jsonb_build_object(
    'journal_lines',v_journal,'sale_lines',v_sale_evidence,
    'tax_snapshot',case when v_any_taxable then v_tax||jsonb_build_object('vat_transaction_code',v_tax_code,'facility_context',v_facility,'line_rules',v_tax_rules) else '{}'::jsonb end,
    'is_pkp',v_is_pkp,'vat_transaction_code',case when v_any_taxable then v_tax_code else null end,
    'tax_document_required',v_any_taxable,
    'dpp',v_stock_dpp+v_service_dpp,'taxable_dpp',v_taxable_dpp,'vat_amount',v_total_vat,'gross_amount',v_total_gross,'taxable_gross',v_taxable_gross
  );
exception when no_data_found then
  raise exception 'sale_tax_master_dependency_missing' using errcode='23514';
end;
$$;
revoke all on function private.build_sale_lines(uuid,text,date,jsonb,text,uuid,text,text) from public,anon,authenticated,service_role;

create or replace function public.create_auto_journal(
  p_tenant_id uuid,
  p_transaction_type text,
  p_transaction_ref text,
  p_business_date date,
  p_facts jsonb,
  p_device_id text,
  p_app_version text,
  p_reason text
) returns uuid
language plpgsql
security definer
set search_path=''
as $$
declare
  v_actor uuid:=auth.uid(); v_member_role text; v_type text:=upper(btrim(coalesce(p_transaction_type,'')));
  v_fingerprint jsonb; v_existing public.accounting_transaction_evidence%rowtype; v_build jsonb; v_lines jsonb;
  v_source text; v_payment text; v_journal uuid; v_item jsonb; v_counterparty uuid; v_tax_doc uuid; v_original_tax public.tax_documents%rowtype;
  v_input_doc uuid; v_withholding bigint; v_tax_code text; v_required_bad int;
begin
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  v_member_role:=accounting_private.require_member_role(p_tenant_id,v_actor,array['owner','admin','accountant','cashier']);
  if p_reason is null or length(btrim(p_reason))<3 then raise exception 'audit_reason_required' using errcode='22023'; end if;
  if p_business_date is null or p_transaction_ref is null or length(btrim(p_transaction_ref))=0 then raise exception 'transaction_identity_required' using errcode='22023'; end if;
  if v_type not in ('JUAL_TUNAI','JUAL_QRIS','JUAL_TRANSFER','JUAL_KREDIT','BELI_KREDIT','BAYAR_VENDOR','RETUR_PENJUALAN','STOCK_OPNAME') then raise exception 'unsupported_transaction_template' using errcode='22023'; end if;
  if v_type in ('RETUR_PENJUALAN','STOCK_OPNAME') and v_member_role='cashier' then raise exception 'sensitive_transaction_requires_accounting_supervisor' using errcode='42501'; end if;
  perform private.assert_no_accounting_fields(p_facts);

  select count(*) into v_required_bad from (values
    ('1-1010','Aset Lancar','debit'),('1-1020','Aset Lancar','debit'),('1-1030','Aset Lancar','debit'),('1-1040','Aset Lancar','debit'),('1-1050','Aset Lancar','debit'),
    ('1-1090','Aset Lancar','debit'),('2-2010','Kewajiban','credit'),('2-2020','Kewajiban','credit'),('2-2050','Kewajiban','credit'),('2-2060','Kewajiban','credit'),
    ('4-4010','Pendapatan','credit'),('4-4030','Pendapatan','debit'),('4-4050','Pendapatan','credit'),('4-4060','Pendapatan','credit'),
    ('5-5010','HPP','debit'),('6-6080','Beban','debit')
  ) x(code,typ,bal)
  where not exists(select 1 from public.accounting_coa c where c.account_code=x.code and c.account_type=x.typ and c.normal_balance=x.bal);
  if v_required_bad<>0 then raise exception 'canonical COA mapping missing or semantically invalid' using errcode='23514'; end if;

  v_fingerprint:=jsonb_build_object('transaction_type',v_type,'transaction_ref',btrim(p_transaction_ref),'business_date',p_business_date::text,'facts',p_facts,'actor_user_id',v_actor::text,'device_id',btrim(p_device_id),'app_version',btrim(p_app_version),'reason',btrim(p_reason));
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||btrim(p_transaction_ref),7331));
  select * into v_existing from public.accounting_transaction_evidence where tenant_id=p_tenant_id and transaction_ref=btrim(p_transaction_ref);
  if found then
    if v_existing.request_fingerprint=v_fingerprint then return v_existing.journal_id; end if;
    raise exception 'transaction_idempotency_conflict' using errcode='23505';
  end if;

  case v_type
    when 'JUAL_TUNAI' then v_payment:='1-1010'; v_source:='pos_sale'; v_build:=private.build_sale_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_payment,v_actor,p_device_id,p_reason);
    when 'JUAL_QRIS' then v_payment:='1-1020'; v_source:='pos_sale'; v_build:=private.build_sale_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_payment,v_actor,p_device_id,p_reason);
    when 'JUAL_TRANSFER' then v_payment:='1-1030'; v_source:='pos_sale'; v_build:=private.build_sale_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_payment,v_actor,p_device_id,p_reason);
    when 'JUAL_KREDIT' then
      if nullif(btrim(coalesce(p_facts->>'customer_id','')),'') is null then raise exception 'customer_required_for_credit_sale' using errcode='22023'; end if;
      v_payment:='1-1050'; v_source:='pos_sale'; v_build:=private.build_sale_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_payment,v_actor,p_device_id,p_reason);
    when 'BELI_KREDIT' then
      if nullif(btrim(coalesce(p_facts->>'supplier_id','')),'') is null then raise exception 'supplier_required_for_credit_purchase' using errcode='22023'; end if;
      v_source:='purchase_receipt'; v_build:=private.build_purchase_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_actor,p_device_id,p_reason);
    when 'BAYAR_VENDOR' then v_source:='supplier_payment'; v_build:=private.build_supplier_payment_lines(p_tenant_id,p_business_date,p_facts);
    when 'RETUR_PENJUALAN' then v_source:='sale_return'; v_build:=private.build_sale_return_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_actor,p_device_id,p_reason);
    when 'STOCK_OPNAME' then v_source:='manual'; v_build:=private.build_stock_opname_lines(p_tenant_id,p_transaction_ref,p_facts,v_actor,p_device_id,p_reason);
  end case;
  v_lines:=v_build->'journal_lines';
  if jsonb_typeof(v_lines)<>'array' or jsonb_array_length(v_lines)<2 then raise exception 'auto_journal_builder_failed' using errcode='23514'; end if;

  v_journal:=accounting_private.post_journal(p_tenant_id,'auto:'||btrim(p_transaction_ref),btrim(p_transaction_ref),p_business_date,v_type,v_source,v_lines,p_device_id,p_app_version);
  insert into public.accounting_transaction_evidence(tenant_id,transaction_ref,transaction_type,business_date,request_fingerprint,facts_snapshot,tax_snapshot,journal_id,actor_user_id,device_id,app_version,reason)
  values(p_tenant_id,btrim(p_transaction_ref),v_type,p_business_date,v_fingerprint,p_facts,coalesce(v_build->'tax_snapshot','{}'::jsonb),v_journal,v_actor,btrim(p_device_id),btrim(p_app_version),btrim(p_reason));

  if v_type in ('JUAL_TUNAI','JUAL_QRIS','JUAL_TRANSFER','JUAL_KREDIT') then
    for v_item in select value from jsonb_array_elements(v_build->'sale_lines') loop
      insert into public.sale_line_evidence(tenant_id,transaction_ref,line_key,product_id,line_kind,quantity,revenue_account,dpp,vat_amount,gross_amount,original_cogs,tax_snapshot)
      values(p_tenant_id,btrim(p_transaction_ref),v_item->>'line_key',nullif(v_item->>'product_id','')::uuid,v_item->>'line_kind',(v_item->>'quantity')::bigint,v_item->>'revenue_account',(v_item->>'dpp')::bigint,(v_item->>'vat_amount')::bigint,(v_item->>'gross_amount')::bigint,(v_item->>'original_cogs')::bigint,coalesce(v_item->'tax_snapshot','{}'::jsonb));
    end loop;
    if coalesce((v_build->>'tax_document_required')::boolean,false) then
      if p_facts ? 'customer_tax_party_id' and nullif(btrim(p_facts->>'customer_tax_party_id'),'') is not null then
        begin v_counterparty:=(p_facts->>'customer_tax_party_id')::uuid; exception when others then raise exception 'invalid_customer_tax_party_id' using errcode='22023'; end;
        if not exists(select 1 from public.tax_parties tp where tp.tenant_id=p_tenant_id and tp.party_id=v_counterparty and tp.party_kind='CUSTOMER' and tp.valid_from<=p_business_date and (tp.valid_to is null or tp.valid_to>=p_business_date)) then raise exception 'customer_tax_party_evidence_invalid' using errcode='23514'; end if;
      end if;
      v_tax_doc:=private.create_tax_document_internal(p_tenant_id,'VAT_OUTPUT',p_transaction_ref,p_business_date,v_counterparty,coalesce(v_build->'tax_snapshot'->>'facility_context','NORMAL'),v_build->'tax_snapshot',(v_build->>'taxable_dpp')::bigint,(v_build->>'vat_amount')::bigint,(v_build->>'taxable_gross')::bigint,v_journal,'VALID',false,null,v_actor,p_device_id,p_reason);
    end if;
  elsif v_type='BELI_KREDIT' then
    if nullif(v_build->>'input_tax_document_id','') is not null then
      v_input_doc:=(v_build->>'input_tax_document_id')::uuid;
      update public.tax_documents set journal_id=v_journal,updated_at=now() where tax_document_id=v_input_doc and tenant_id=p_tenant_id and journal_id is null;
      if not found then raise exception 'input_tax_document_journal_link_failed' using errcode='23514'; end if;
      insert into public.tax_document_events(tax_document_id,tenant_id,event_type,details,actor_user_id,device_id,reason)
      values(v_input_doc,p_tenant_id,'JOURNAL_LINKED',jsonb_build_object('journal_id',v_journal),v_actor,btrim(p_device_id),btrim(p_reason));
    end if;
  elsif v_type='BAYAR_VENDOR' then
    v_withholding:=coalesce((v_build->>'withholding_amount')::bigint,0);
    if v_withholding>0 then
      v_tax_code:=v_build->>'tax_code';
      v_tax_doc:=private.create_tax_document_internal(
        p_tenant_id,case when v_tax_code='PPH23' then 'PPH23_UNIFICATION' else 'PPH_FINAL' end,
        p_transaction_ref,p_business_date,(v_build->>'vendor_party_id')::uuid,null,v_build->'tax_snapshot',
        (v_build->>'withholding_base')::bigint,v_withholding,(v_build->>'withholding_base')::bigint,v_journal,
        'VALID',false,null,v_actor,p_device_id,p_reason
      );
    end if;
  elsif v_type='RETUR_PENJUALAN' then
    for v_item in select value from jsonb_array_elements(v_build->'return_lines') loop
      insert into public.sale_return_line_evidence(tenant_id,return_transaction_ref,original_transaction_ref,line_key,quantity,dpp_reversed,vat_reversed,cogs_restored)
      values(p_tenant_id,btrim(p_transaction_ref),v_item->>'original_transaction_ref',v_item->>'line_key',(v_item->>'quantity')::bigint,(v_item->>'dpp_reversed')::bigint,(v_item->>'vat_reversed')::bigint,(v_item->>'cogs_restored')::bigint);
    end loop;
    select * into v_original_tax from public.tax_documents where tenant_id=p_tenant_id and document_type='VAT_OUTPUT' and transaction_ref=v_build->>'original_transaction_ref';
    if found then
      v_tax_doc:=private.create_tax_document_internal(p_tenant_id,'VAT_RETURN',p_transaction_ref,p_business_date,v_original_tax.counterparty_id,v_original_tax.facility_context,v_original_tax.tax_rate_snapshot,(v_build->>'dpp')::bigint,(v_build->>'vat_amount')::bigint,(v_build->>'gross_amount')::bigint,v_journal,'VALID',false,v_original_tax.tax_document_id,v_actor,p_device_id,p_reason);
    elsif (v_build->>'vat_amount')::bigint>0 then raise exception 'taxable_return_requires_original_tax_document' using errcode='23514'; end if;
  end if;

  insert into private.audit_logs(tenant_id,actor_id,device_id,source,reason,action)
  values(p_tenant_id::text,v_actor,btrim(p_device_id),'auto_journal:'||lower(v_type),btrim(p_reason),'success');
  return v_journal;
end;
$$;

revoke all on function public.create_auto_journal(uuid,text,text,date,jsonb,text,text,text) from public,anon,service_role;
grant execute on function public.create_auto_journal(uuid,text,text,date,jsonb,text,text,text) to authenticated;

alter table public.service_tax_profiles
  add column if not exists unit_price bigint;
update public.service_tax_profiles set unit_price=1 where unit_price is null;
alter table public.service_tax_profiles alter column unit_price set not null;
do $$ begin
  if not exists(select 1 from pg_constraint where conrelid='public.service_tax_profiles'::regclass and conname='service_tax_profiles_unit_price_check') then
    alter table public.service_tax_profiles add constraint service_tax_profiles_unit_price_check check(unit_price>0);
  end if;
end $$;

revoke all on function public.create_service_tax_profile(uuid,text,text,boolean,text,date,date,text,text,text,text) from public,anon,authenticated,service_role;
drop function public.create_service_tax_profile(uuid,text,text,boolean,text,date,date,text,text,text,text);

create or replace function public.create_service_tax_profile(
  p_tenant_id uuid,p_service_code text,p_name_id text,p_unit_price bigint,p_vat_exempt boolean,p_vat_object_code text,
  p_valid_from date,p_valid_to date,p_legal_basis text,p_device_id text,p_app_version text,p_reason text
) returns uuid
language plpgsql security definer set search_path=''
as $$
declare v_actor uuid:=auth.uid(); v_id uuid;
begin
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  perform accounting_private.require_member_role(p_tenant_id,v_actor,array['owner','admin','accountant']);
  if p_service_code is null or length(btrim(p_service_code))<1 or p_name_id is null or length(btrim(p_name_id))<1 then raise exception 'service_identity_required' using errcode='22023'; end if;
  if p_unit_price is null or p_unit_price<=0 then raise exception 'service_unit_price_must_be_positive_integer_rupiah' using errcode='22023'; end if;
  if p_vat_object_code not in ('NON_LUXURY','LUXURY_CONSUMER') then raise exception 'invalid_vat_object_code' using errcode='22023'; end if;
  if p_valid_from is null or (p_valid_to is not null and p_valid_to<p_valid_from) then raise exception 'invalid_service_tax_profile_period' using errcode='22023'; end if;
  if p_legal_basis is null or length(btrim(p_legal_basis))<3 or p_reason is null or length(btrim(p_reason))<3 then raise exception 'service_tax_evidence_required' using errcode='22023'; end if;
  insert into public.service_tax_profiles(tenant_id,service_code,name_id,unit_price,vat_exempt,vat_object_code,valid_from,valid_to,legal_basis,actor_user_id,device_id,reason)
  values(p_tenant_id,upper(btrim(p_service_code)),btrim(p_name_id),p_unit_price,coalesce(p_vat_exempt,false),p_vat_object_code,p_valid_from,p_valid_to,btrim(p_legal_basis),v_actor,btrim(p_device_id),btrim(p_reason))
  returning service_profile_id into v_id;
  insert into private.audit_logs(tenant_id,actor_id,device_id,source,reason,action)
  values(p_tenant_id::text,v_actor,btrim(p_device_id),'service_tax_profile:create:'||v_id::text,btrim(p_reason),'success');
  return v_id;
end;
$$;
revoke all on function public.create_service_tax_profile(uuid,text,text,bigint,boolean,text,date,date,text,text,text,text) from public,anon,service_role;
grant execute on function public.create_service_tax_profile(uuid,text,text,bigint,boolean,text,date,date,text,text,text,text) to authenticated;

alter table public.sale_line_evidence
  add column service_profile_id uuid,
  add column item_code text not null,
  add column item_name text not null,
  add column unit_price bigint not null check(unit_price>0),
  add column list_amount bigint not null check(list_amount>0),
  add column discount_amount bigint not null default 0 check(discount_amount>=0),
  add column taxable boolean not null default false,
  add column tax_object_code text;

alter table public.sale_line_evidence
  add constraint sale_line_evidence_service_fk foreign key(tenant_id,service_profile_id)
  references public.service_tax_profiles(tenant_id,service_profile_id),
  add constraint sale_line_evidence_identity_check check(
    (line_kind='STOCK' and product_id is not null and service_profile_id is null)
    or (line_kind='SERVICE' and product_id is null and service_profile_id is not null)
  ),
  add constraint sale_line_evidence_discount_check check(discount_amount<list_amount);

create table public.tax_document_lines(
  tax_document_id uuid not null references public.tax_documents(tax_document_id),
  tenant_id uuid not null references public.accounting_tenants(tenant_id),
  line_key text not null,
  line_kind text not null check(line_kind in ('STOCK','SERVICE')),
  item_code text not null check(length(btrim(item_code))>=1),
  item_name text not null check(length(btrim(item_name))>=1),
  quantity bigint not null check(quantity>0),
  unit_price bigint not null check(unit_price>0),
  list_amount bigint not null check(list_amount>0),
  discount_amount bigint not null check(discount_amount>=0 and discount_amount<list_amount),
  dpp bigint not null check(dpp>=0),
  tax_amount bigint not null check(tax_amount>=0),
  gross_amount bigint not null check(gross_amount>=0),
  tax_object_code text not null,
  tax_rule_snapshot jsonb not null check(jsonb_typeof(tax_rule_snapshot)='object'),
  created_at timestamptz not null default now(),
  primary key(tax_document_id,line_key),
  check(gross_amount=dpp+tax_amount)
);
alter table public.tax_document_lines enable row level security;
revoke all on public.tax_document_lines from anon,authenticated,service_role;
grant select on public.tax_document_lines to service_role;

create trigger tax_document_lines_immutable before update or delete on public.tax_document_lines
for each row execute function private.reject_tax_evidence_mutation();

create or replace function private.populate_tax_document_lines()
returns trigger language plpgsql security definer set search_path=''
as $$
begin
  if new.document_type in ('VAT_OUTPUT','VAT_REPLACEMENT') then
    insert into public.tax_document_lines(
      tax_document_id,tenant_id,line_key,line_kind,item_code,item_name,quantity,unit_price,list_amount,discount_amount,
      dpp,tax_amount,gross_amount,tax_object_code,tax_rule_snapshot
    )
    select new.tax_document_id,s.tenant_id,s.line_key,s.line_kind,s.item_code,s.item_name,s.quantity,s.unit_price,s.list_amount,s.discount_amount,
           s.dpp,s.vat_amount,s.gross_amount,coalesce(s.tax_object_code,'NON_LUXURY'),s.tax_snapshot
    from public.sale_line_evidence s
    where s.tenant_id=new.tenant_id and s.transaction_ref=new.transaction_ref and s.taxable;
  elsif new.document_type='VAT_RETURN' and new.reference_document_id is not null then
    insert into public.tax_document_lines(
      tax_document_id,tenant_id,line_key,line_kind,item_code,item_name,quantity,unit_price,list_amount,discount_amount,
      dpp,tax_amount,gross_amount,tax_object_code,tax_rule_snapshot
    )
    select new.tax_document_id,o.tenant_id,r.line_key,o.line_kind,o.item_code,o.item_name,r.quantity,o.unit_price,
           round(o.list_amount::numeric*r.quantity::numeric/o.quantity::numeric)::bigint,
           greatest(round(o.discount_amount::numeric*r.quantity::numeric/o.quantity::numeric)::bigint,0),
           r.dpp_reversed,r.vat_reversed,r.dpp_reversed+r.vat_reversed,coalesce(o.tax_object_code,'NON_LUXURY'),o.tax_snapshot
    from public.sale_return_line_evidence r
    join public.sale_line_evidence o
      on o.tenant_id=r.tenant_id and o.transaction_ref=r.original_transaction_ref and o.line_key=r.line_key
    where r.tenant_id=new.tenant_id and r.return_transaction_ref=new.transaction_ref and o.taxable;
  end if;
  return new;
end;
$$;
revoke all on function private.populate_tax_document_lines() from public,anon,authenticated,service_role;
drop trigger if exists tax_documents_populate_lines on public.tax_documents;
create trigger tax_documents_populate_lines after insert on public.tax_documents
for each row execute function private.populate_tax_document_lines();

create or replace function private.build_sale_lines(
  p_tenant_id uuid,p_transaction_ref text,p_business_date date,p_facts jsonb,
  p_payment_account text,p_actor uuid,p_device_id text,p_reason text
) returns jsonb
language plpgsql security definer set search_path=''
as $$
declare
  v_lines jsonb:=coalesce(p_facts->'lines','[]'::jsonb);
  v_line jsonb; v_i int:=0; v_line_key text; v_kind text; v_product uuid; v_service uuid; v_qty bigint; v_amount bigint;
  v_self_count int; v_self public.tax_parties%rowtype; v_is_pkp boolean;
  v_inclusive boolean:=coalesce((p_facts->>'prices_include_vat')::boolean,false);
  v_facility text:=upper(coalesce(nullif(btrim(p_facts->>'facility_context'),''),'NORMAL'));
  v_master_exempt boolean; v_line_taxable boolean; v_line_object text; v_unit_price bigint; v_list_amount bigint; v_discount bigint; v_item_code text; v_item_name text;
  v_tax jsonb:='{}'::jsonb; v_line_tax jsonb:='{}'::jsonb; v_tax_rules jsonb:='[]'::jsonb; v_rate numeric:=0; v_tax_code text;
  v_dpp bigint; v_vat bigint; v_gross bigint; v_cogs bigint:=0;
  v_stock_dpp bigint:=0; v_service_dpp bigint:=0; v_taxable_dpp bigint:=0; v_taxable_gross bigint:=0; v_total_vat bigint:=0; v_total_gross bigint:=0; v_total_cogs bigint:=0;
  v_any_taxable boolean:=false; v_sale_evidence jsonb:='[]'::jsonb; v_journal jsonb:='[]'::jsonb;
begin
  perform private.assert_no_accounting_fields(p_facts);
  if p_payment_account not in ('1-1010','1-1020','1-1030','1-1050') then raise exception 'invalid_internal_payment_mapping' using errcode='23514'; end if;
  if p_transaction_ref is null or length(btrim(p_transaction_ref))=0 or p_business_date is null then raise exception 'sale_identity_required' using errcode='22023'; end if;
  if jsonb_typeof(v_lines)<>'array' or jsonb_array_length(v_lines)<1 or jsonb_array_length(v_lines)>50 then raise exception 'sale_lines_required' using errcode='22023'; end if;
  if v_facility='ASSET_16D' then raise exception 'asset_16d_not_supported_by_pos_sale_intent' using errcode='22023'; end if;
  v_tax_code:=private.resolve_vat_transaction_code(v_facility);

  select count(*) into v_self_count from public.tax_parties tp
  where tp.tenant_id=p_tenant_id and tp.party_kind='SELF'
    and tp.valid_from<=p_business_date and (tp.valid_to is null or tp.valid_to>=p_business_date)
    and ((tp.is_pkp and tp.certificate_status='VALID') or (not tp.is_pkp and tp.certificate_status in ('VALID','NOT_REQUIRED')));
  if v_self_count<>1 then raise exception 'exactly_one_effective_self_tax_profile_required' using errcode='23514'; end if;
  select * into strict v_self from public.tax_parties tp
  where tp.tenant_id=p_tenant_id and tp.party_kind='SELF'
    and tp.valid_from<=p_business_date and (tp.valid_to is null or tp.valid_to>=p_business_date)
    and ((tp.is_pkp and tp.certificate_status='VALID') or (not tp.is_pkp and tp.certificate_status in ('VALID','NOT_REQUIRED')));
  v_is_pkp:=v_self.is_pkp;
  if p_facts ? 'is_pkp' and coalesce((p_facts->>'is_pkp')::boolean,false) is distinct from v_is_pkp then
    raise exception 'tenant_pkp_status_mismatch' using errcode='23514';
  end if;

  for v_line in select value from jsonb_array_elements(v_lines) loop
    v_i:=v_i+1;
    v_line_key:=coalesce(nullif(btrim(v_line->>'line_key'),''),v_i::text);
    v_kind:=upper(coalesce(v_line->>'kind',''));
    if v_kind not in ('STOCK','SERVICE') then raise exception 'invalid_sale_line_kind' using errcode='22023'; end if;
    if coalesce(v_line->>'qty','') !~ '^[1-9][0-9]*$' then raise exception 'sale_qty_must_be_positive_integer' using errcode='22023'; end if;
    if v_line ? 'discount_amount' and coalesce(v_line->>'discount_amount','') !~ '^(0|[1-9][0-9]*)$' then raise exception 'sale_discount_must_be_nonnegative_integer_rupiah' using errcode='22023'; end if;
    v_qty:=(v_line->>'qty')::bigint; v_discount:=coalesce((v_line->>'discount_amount')::bigint,0);

    if v_kind='STOCK' then
      begin v_product:=(v_line->>'product_id')::uuid; exception when others then raise exception 'valid_product_id_required_for_stock_line' using errcode='22023'; end;
      select p.ppn_exempt,p.vat_object_code,p.price,p.sku,p.name_id into strict v_master_exempt,v_line_object,v_unit_price,v_item_code,v_item_name
      from public.product_master p
      where p.tenant_id=p_tenant_id and p.product_id=v_product and p.is_active;
      v_service:=null;
    else
      if v_line ? 'product_id' and nullif(btrim(v_line->>'product_id'),'') is not null then raise exception 'service_line_cannot_reference_inventory_product' using errcode='22023'; end if;
      begin v_service:=(v_line->>'service_profile_id')::uuid; exception when others then raise exception 'service_profile_id_required' using errcode='22023'; end;
      select s.vat_exempt,s.vat_object_code,s.unit_price,s.service_code,s.name_id into strict v_master_exempt,v_line_object,v_unit_price,v_item_code,v_item_name
      from public.service_tax_profiles s
      where s.tenant_id=p_tenant_id and s.service_profile_id=v_service
        and s.valid_from<=p_business_date and (s.valid_to is null or s.valid_to>=p_business_date);
      v_product:=null;
    end if;

    if v_qty::numeric*v_unit_price::numeric>9223372036854775807::numeric then raise exception 'sale_value_out_of_range' using errcode='22003'; end if;
    v_list_amount:=v_qty*v_unit_price;
    if v_discount>=v_list_amount then raise exception 'sale_discount_must_be_less_than_list_amount' using errcode='22023'; end if;
    v_amount:=v_list_amount-v_discount;
    if v_line ? 'amount' and coalesce(v_line->>'amount','') !~ '^[1-9][0-9]*$' then raise exception 'sale_amount_claim_must_be_positive_integer_rupiah' using errcode='22023'; end if;
    if v_line ? 'amount' and (v_line->>'amount')::bigint<>v_amount then raise exception 'sale_amount_does_not_match_server_price_and_discount' using errcode='23514'; end if;

    v_line_taxable:=v_is_pkp and not v_master_exempt;
    if v_line ? 'taxable' and (v_line->>'taxable')::boolean is distinct from v_line_taxable then raise exception 'sale_line_taxability_mismatch' using errcode='23514'; end if;
    if v_line ? 'tax_object_code' and upper(btrim(v_line->>'tax_object_code')) is distinct from v_line_object then raise exception 'sale_line_tax_object_mismatch' using errcode='23514'; end if;

    v_line_tax:='{}'::jsonb; v_rate:=0;
    if v_line_taxable then
      v_line_tax:=private.resolve_tax_rate_snapshot('PPN',v_line_object,p_business_date,'DEFAULT');
      v_rate:=(v_line_tax->>'effective_rate')::numeric;
      v_any_taxable:=true;
      v_tax_rules:=v_tax_rules||jsonb_build_array(jsonb_build_object('line_key',v_line_key,'object_code',v_line_object,'rule',v_line_tax));
      if v_tax='{}'::jsonb then v_tax:=v_line_tax; end if;
    end if;

    if v_line_taxable and v_facility='NORMAL' then
      if v_inclusive then v_dpp:=round(v_amount::numeric/(1+v_rate))::bigint; v_vat:=v_amount-v_dpp; v_gross:=v_amount;
      else v_dpp:=v_amount; v_vat:=round(v_dpp::numeric*v_rate)::bigint; v_gross:=v_dpp+v_vat; end if;
    else v_dpp:=v_amount; v_vat:=0; v_gross:=v_amount; end if;
    if v_dpp<=0 or v_gross<=0 or v_vat<0 then raise exception 'invalid_sale_tax_calculation' using errcode='23514'; end if;

    if v_kind='STOCK' then
      v_cogs:=inventory_private.average_consume(p_tenant_id,v_product,v_qty,'sale:'||btrim(p_transaction_ref)||':'||v_line_key,btrim(p_transaction_ref),p_actor,p_device_id,p_reason);
      if v_cogs<=0 then raise exception 'stocked_sale_cogs_must_be_positive' using errcode='23514'; end if;
      v_stock_dpp:=v_stock_dpp+v_dpp; v_total_cogs:=v_total_cogs+v_cogs;
    else v_cogs:=0; v_service_dpp:=v_service_dpp+v_dpp; end if;
    if v_line_taxable then v_taxable_dpp:=v_taxable_dpp+v_dpp; v_taxable_gross:=v_taxable_gross+v_gross; end if;
    v_total_vat:=v_total_vat+v_vat; v_total_gross:=v_total_gross+v_gross;
    v_sale_evidence:=v_sale_evidence||jsonb_build_array(jsonb_build_object(
      'line_key',v_line_key,'line_kind',v_kind,'product_id',v_product,'service_profile_id',v_service,'item_code',v_item_code,'item_name',v_item_name,
      'quantity',v_qty,'unit_price',v_unit_price,'list_amount',v_list_amount,'discount_amount',v_discount,
      'revenue_account',case when v_kind='STOCK' then '4-4010' else '4-4050' end,
      'dpp',v_dpp,'vat_amount',v_vat,'gross_amount',v_gross,'original_cogs',v_cogs,'taxable',v_line_taxable,'tax_object_code',v_line_object,
      'tax_snapshot',case when v_line_taxable then v_line_tax||jsonb_build_object('taxable',true,'vat_transaction_code',v_tax_code,'facility_context',v_facility,'object_code',v_line_object) else jsonb_build_object('taxable',false,'master_exempt',v_master_exempt) end
    ));
  end loop;

  v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code',p_payment_account,'debit',v_total_gross,'credit',0,'memo','Pembayaran penjualan'));
  if v_stock_dpp>0 then v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','4-4010','debit',0,'credit',v_stock_dpp,'memo','Penjualan barang')); end if;
  if v_service_dpp>0 then v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','4-4050','debit',0,'credit',v_service_dpp,'memo','Pendapatan jasa')); end if;
  if v_total_vat>0 then v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','2-2010','debit',0,'credit',v_total_vat,'memo','PPN dari penjualan')); end if;
  if v_total_cogs>0 then
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','5-5010','debit',v_total_cogs,'credit',0,'memo','Harga modal rata-rata otomatis'));
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','1-1040','debit',0,'credit',v_total_cogs,'memo','Pengurangan persediaan'));
  end if;
  return jsonb_build_object('journal_lines',v_journal,'sale_lines',v_sale_evidence,
    'tax_snapshot',case when v_any_taxable then v_tax||jsonb_build_object('vat_transaction_code',v_tax_code,'facility_context',v_facility,'line_rules',v_tax_rules) else '{}'::jsonb end,
    'is_pkp',v_is_pkp,'vat_transaction_code',case when v_any_taxable then v_tax_code else null end,'tax_document_required',v_any_taxable,
    'dpp',v_stock_dpp+v_service_dpp,'taxable_dpp',v_taxable_dpp,'vat_amount',v_total_vat,'gross_amount',v_total_gross,'taxable_gross',v_taxable_gross);
exception when no_data_found then raise exception 'sale_tax_master_dependency_missing' using errcode='23514';
end;
$$;
revoke all on function private.build_sale_lines(uuid,text,date,jsonb,text,uuid,text,text) from public,anon,authenticated,service_role;

create or replace function public.create_auto_journal(
  p_tenant_id uuid,p_transaction_type text,p_transaction_ref text,p_business_date date,p_facts jsonb,p_device_id text,p_app_version text,p_reason text
) returns uuid
language plpgsql security definer set search_path=''
as $$
declare
  v_actor uuid:=auth.uid(); v_member_role text; v_type text:=upper(btrim(coalesce(p_transaction_type,'')));
  v_fingerprint jsonb; v_existing public.accounting_transaction_evidence%rowtype; v_build jsonb; v_lines jsonb;
  v_source text; v_payment text; v_journal uuid; v_item jsonb; v_counterparty uuid; v_tax_doc uuid; v_original_tax public.tax_documents%rowtype;
  v_input_doc uuid; v_withholding bigint; v_tax_code text; v_required_bad int;
begin
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  v_member_role:=accounting_private.require_member_role(p_tenant_id,v_actor,array['owner','admin','accountant','cashier']);
  if p_reason is null or length(btrim(p_reason))<3 then raise exception 'audit_reason_required' using errcode='22023'; end if;
  if p_business_date is null or p_transaction_ref is null or length(btrim(p_transaction_ref))=0 then raise exception 'transaction_identity_required' using errcode='22023'; end if;
  if v_type not in ('JUAL_TUNAI','JUAL_QRIS','JUAL_TRANSFER','JUAL_KREDIT','BELI_KREDIT','BAYAR_VENDOR','RETUR_PENJUALAN','STOCK_OPNAME') then raise exception 'unsupported_transaction_template' using errcode='22023'; end if;
  if v_type in ('RETUR_PENJUALAN','STOCK_OPNAME') and v_member_role='cashier' then raise exception 'sensitive_transaction_requires_accounting_supervisor' using errcode='42501'; end if;
  perform private.assert_no_accounting_fields(p_facts);
  select count(*) into v_required_bad from (values
    ('1-1010','Aset Lancar','debit'),('1-1020','Aset Lancar','debit'),('1-1030','Aset Lancar','debit'),('1-1040','Aset Lancar','debit'),('1-1050','Aset Lancar','debit'),('1-1090','Aset Lancar','debit'),('2-2010','Kewajiban','credit'),('2-2020','Kewajiban','credit'),('2-2050','Kewajiban','credit'),('2-2060','Kewajiban','credit'),('4-4010','Pendapatan','credit'),('4-4030','Pendapatan','debit'),('4-4050','Pendapatan','credit'),('4-4060','Pendapatan','credit'),('5-5010','HPP','debit'),('6-6080','Beban','debit')
  ) x(code,typ,bal) where not exists(select 1 from public.accounting_coa c where c.account_code=x.code and c.account_type=x.typ and c.normal_balance=x.bal);
  if v_required_bad<>0 then raise exception 'canonical COA mapping missing or semantically invalid' using errcode='23514'; end if;
  v_fingerprint:=jsonb_build_object('transaction_type',v_type,'transaction_ref',btrim(p_transaction_ref),'business_date',p_business_date::text,'facts',p_facts,'actor_user_id',v_actor::text,'device_id',btrim(p_device_id),'app_version',btrim(p_app_version),'reason',btrim(p_reason));
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||btrim(p_transaction_ref),7331));
  select * into v_existing from public.accounting_transaction_evidence where tenant_id=p_tenant_id and transaction_ref=btrim(p_transaction_ref);
  if found then if v_existing.request_fingerprint=v_fingerprint then return v_existing.journal_id; end if; raise exception 'transaction_idempotency_conflict' using errcode='23505'; end if;
  case v_type
    when 'JUAL_TUNAI' then v_payment:='1-1010'; v_source:='pos_sale'; v_build:=private.build_sale_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_payment,v_actor,p_device_id,p_reason);
    when 'JUAL_QRIS' then v_payment:='1-1020'; v_source:='pos_sale'; v_build:=private.build_sale_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_payment,v_actor,p_device_id,p_reason);
    when 'JUAL_TRANSFER' then v_payment:='1-1030'; v_source:='pos_sale'; v_build:=private.build_sale_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_payment,v_actor,p_device_id,p_reason);
    when 'JUAL_KREDIT' then if nullif(btrim(coalesce(p_facts->>'customer_id','')),'') is null then raise exception 'customer_required_for_credit_sale' using errcode='22023'; end if; v_payment:='1-1050'; v_source:='pos_sale'; v_build:=private.build_sale_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_payment,v_actor,p_device_id,p_reason);
    when 'BELI_KREDIT' then if nullif(btrim(coalesce(p_facts->>'supplier_id','')),'') is null then raise exception 'supplier_required_for_credit_purchase' using errcode='22023'; end if; v_source:='purchase_receipt'; v_build:=private.build_purchase_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_actor,p_device_id,p_reason);
    when 'BAYAR_VENDOR' then v_source:='supplier_payment'; v_build:=private.build_supplier_payment_lines(p_tenant_id,p_business_date,p_facts);
    when 'RETUR_PENJUALAN' then v_source:='sale_return'; v_build:=private.build_sale_return_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_actor,p_device_id,p_reason);
    when 'STOCK_OPNAME' then v_source:='manual'; v_build:=private.build_stock_opname_lines(p_tenant_id,p_transaction_ref,p_facts,v_actor,p_device_id,p_reason);
  end case;
  v_lines:=v_build->'journal_lines'; if jsonb_typeof(v_lines)<>'array' or jsonb_array_length(v_lines)<2 then raise exception 'auto_journal_builder_failed' using errcode='23514'; end if;
  v_journal:=accounting_private.post_journal(p_tenant_id,'auto:'||btrim(p_transaction_ref),btrim(p_transaction_ref),p_business_date,v_type,v_source,v_lines,p_device_id,p_app_version);
  insert into public.accounting_transaction_evidence(tenant_id,transaction_ref,transaction_type,business_date,request_fingerprint,facts_snapshot,tax_snapshot,journal_id,actor_user_id,device_id,app_version,reason)
  values(p_tenant_id,btrim(p_transaction_ref),v_type,p_business_date,v_fingerprint,p_facts,coalesce(v_build->'tax_snapshot','{}'::jsonb),v_journal,v_actor,btrim(p_device_id),btrim(p_app_version),btrim(p_reason));
  if v_type in ('JUAL_TUNAI','JUAL_QRIS','JUAL_TRANSFER','JUAL_KREDIT') then
    for v_item in select value from jsonb_array_elements(v_build->'sale_lines') loop
      insert into public.sale_line_evidence(tenant_id,transaction_ref,line_key,product_id,service_profile_id,line_kind,item_code,item_name,quantity,unit_price,list_amount,discount_amount,revenue_account,dpp,vat_amount,gross_amount,original_cogs,taxable,tax_object_code,tax_snapshot)
