create or replace function private.guard_tenant_accounting_link()
returns trigger
language plpgsql
security definer
set search_path=''
as $$
declare
  v_overlap boolean;
begin
  if current_user<>'postgres' then
    raise exception 'tenant accounting link direct mutation denied' using errcode='42501';
  end if;
  if tg_op='DELETE' then
    raise exception 'tenant accounting link history is immutable; close with valid_to' using errcode='55000';
  end if;
  if new.valid_to is not null and new.valid_to<new.valid_from then
    raise exception 'invalid tenant accounting link period' using errcode='23514';
  end if;
  if tg_op='UPDATE' and old.valid_from<=current_date then
    if (old.link_id,old.config_tenant_id,old.accounting_tenant_id,old.valid_from,old.actor_user_id,old.device_id,old.reason,old.created_at)
       is distinct from
       (new.link_id,new.config_tenant_id,new.accounting_tenant_id,new.valid_from,new.actor_user_id,new.device_id,new.reason,new.created_at) then
      raise exception 'historical tenant accounting link is immutable' using errcode='55000';
    end if;
    if old.valid_to is not null and new.valid_to is distinct from old.valid_to then
      raise exception 'closed tenant accounting link is immutable' using errcode='55000';
    end if;
    if old.valid_to is null and new.valid_to is not null and new.valid_to<current_date then
      raise exception 'tenant accounting link cannot close retroactively' using errcode='55000';
    end if;
  end if;

  select exists(
    select 1 from private.tenant_accounting_links l
    where l.link_id<>new.link_id
      and (l.config_tenant_id=new.config_tenant_id or l.accounting_tenant_id=new.accounting_tenant_id)
      and daterange(l.valid_from,coalesce(l.valid_to+1,'infinity'::date),'[)')
          && daterange(new.valid_from,coalesce(new.valid_to+1,'infinity'::date),'[)')
  ) into v_overlap;
  if v_overlap then
    raise exception 'overlapping tenant accounting link' using errcode='23514';
  end if;
  return new;
end;
$$;

revoke all on function private.guard_tenant_accounting_link() from public,anon,authenticated,service_role;
drop trigger if exists tenant_accounting_links_guard on private.tenant_accounting_links;
create trigger tenant_accounting_links_guard before insert or update or delete
on private.tenant_accounting_links for each row execute function private.guard_tenant_accounting_link();

create or replace function public.create_tenant_accounting_link(
  p_config_tenant_id text,
  p_accounting_tenant_id uuid,
  p_valid_from date,
  p_valid_to date,
  p_device_id text,
  p_app_version text,
  p_reason text
) returns uuid
language plpgsql
security definer
set search_path=''
as $$
declare
  v_actor uuid:=auth.uid();
  v_link uuid;
  v_device_tenant text;
begin
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  perform accounting_private.require_member_role(p_accounting_tenant_id,v_actor,array['owner','admin']);
  if p_reason is null or length(btrim(p_reason))<3 then raise exception 'audit_reason_required' using errcode='22023'; end if;
  if p_valid_from is null or (p_valid_to is not null and p_valid_to<p_valid_from) then raise exception 'invalid_link_period' using errcode='22023'; end if;

  select d.tenant_id into strict v_device_tenant
  from public.devices d
  where d.device_id=btrim(p_device_id) and d.user_id=v_actor;
  if v_device_tenant<>p_config_tenant_id then raise exception 'device_config_tenant_mismatch' using errcode='42501'; end if;
  if not exists(select 1 from public.tenants t where t.tenant_id=p_config_tenant_id and t.status='active' and not t.is_blocked) then
    raise exception 'config_tenant_not_active' using errcode='23514';
  end if;
  if not exists(select 1 from public.accounting_tenants t where t.tenant_id=p_accounting_tenant_id and t.status='active') then
    raise exception 'accounting_tenant_not_active' using errcode='23514';
  end if;

  insert into private.tenant_accounting_links(config_tenant_id,accounting_tenant_id,valid_from,valid_to,actor_user_id,device_id,reason)
  values(p_config_tenant_id,p_accounting_tenant_id,p_valid_from,p_valid_to,v_actor,btrim(p_device_id),btrim(p_reason))
  returning link_id into v_link;

  insert into private.audit_logs(tenant_id,actor_id,device_id,source,reason,action)
  values(p_accounting_tenant_id::text,v_actor,btrim(p_device_id),'tenant_accounting_link:create:'||v_link::text,btrim(p_reason),'success');
  return v_link;
end;
$$;

create or replace function public.close_tenant_accounting_link(
  p_link_id uuid,
  p_valid_to date,
  p_device_id text,
  p_app_version text,
  p_reason text
) returns void
language plpgsql
security definer
set search_path=''
as $$
declare
  v_actor uuid:=auth.uid();
  v_link private.tenant_accounting_links%rowtype;
begin
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  select * into strict v_link from private.tenant_accounting_links where link_id=p_link_id for update;
  perform accounting_private.require_member_role(v_link.accounting_tenant_id,v_actor,array['owner','admin']);
  if p_reason is null or length(btrim(p_reason))<3 then raise exception 'audit_reason_required' using errcode='22023'; end if;
