create or replace function public.rpc_verify_manager_pin(
  p_tenant_id text,
  p_pin text,
  p_required_action text,
  p_device_id text
) returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  v_actor uuid := auth.uid();
  v_tenant text := nullif(trim(coalesce(p_tenant_id, '')), '');
  v_device text := nullif(trim(coalesce(p_device_id, '')), '');
  v_action text := lower(trim(coalesce(p_required_action, '')));
  v_pin_hash text;
  v_is_active boolean;
  v_attempts integer;
  v_locked_until timestamptz;
  v_now timestamptz := now();
  v_ok boolean := false;
begin
  if v_actor is null then
    raise exception 'authenticated session required' using errcode = '42501';
  end if;
  if v_tenant is null or v_device is null or nullif(coalesce(p_pin, ''), '') is null then
    raise exception 'tenant, device and pin are required' using errcode = '22023';
  end if;
  if v_action not in ('return_sale','void_sale','close_shift_variance') then
    raise exception 'unsupported manager pin action' using errcode = '22023';
  end if;

  if not exists (
    select 1 from public.devices d
    where d.device_id = v_device
      and d.tenant_id = v_tenant
      and d.user_id = v_actor
  ) then
    raise exception 'device is not bound to actor and tenant' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.pos_memberships m
    where m.tenant_id = v_tenant
      and m.user_id = v_actor
      and m.is_active = true
  ) then
    raise exception 'active POS membership required' using errcode = '42501';
  end if;

  select p.pin_hash, p.is_active, p.failed_attempts, p.locked_until
    into v_pin_hash, v_is_active, v_attempts, v_locked_until
  from public.pos_manager_pins p
  where p.tenant_id = v_tenant
  for update;

  if v_pin_hash is null or not coalesce(v_is_active, false) then
    insert into public.pos_pin_audit (
      tenant_id, actor_id, device_id, required_action, success,
      failure_reason, attempt_count, locked_until
    ) values (
      v_tenant, v_actor, v_device, v_action, false,
      'pin_not_configured_or_inactive', coalesce(v_attempts, 0), v_locked_until
    );
    return jsonb_build_object(
      'ok', false,
      'is_active', coalesce(v_is_active, false),
      'attempts', coalesce(v_attempts, 0),
      'locked_until', v_locked_until
    );
  end if;

  if v_locked_until is not null and v_locked_until > v_now then
    insert into public.pos_pin_audit (
      tenant_id, actor_id, device_id, required_action, success,
      failure_reason, attempt_count, locked_until
    ) values (
      v_tenant, v_actor, v_device, v_action, false,
      'locked', v_attempts, v_locked_until
    );
    return jsonb_build_object(
      'ok', false,
      'is_active', true,
      'attempts', v_attempts,
      'locked_until', v_locked_until
    );
  end if;

  if v_locked_until is not null and v_locked_until <= v_now then
    v_attempts := 0;
    v_locked_until := null;
  end if;

  v_ok := extensions.crypt(p_pin, v_pin_hash) = v_pin_hash;

  if v_ok then
    v_attempts := 0;
    v_locked_until := null;
    update public.pos_manager_pins
       set failed_attempts = 0,
           locked_until = null,
           updated_at = v_now
     where tenant_id = v_tenant;
  else
    v_attempts := least(coalesce(v_attempts, 0) + 1, 3);
    if v_attempts >= 3 then
      v_locked_until := v_now + interval '5 minutes';
    else
      v_locked_until := null;
    end if;
    update public.pos_manager_pins
       set failed_attempts = v_attempts,
           locked_until = v_locked_until,
           updated_at = v_now
     where tenant_id = v_tenant;
  end if;

  insert into public.pos_pin_audit (
    tenant_id, actor_id, device_id, required_action, success,
    failure_reason, attempt_count, locked_until
  ) values (
    v_tenant, v_actor, v_device, v_action, v_ok,
    case when v_ok then null else 'invalid_pin' end,
    v_attempts, v_locked_until
  );

  return jsonb_build_object(
    'ok', v_ok,
    'is_active', true,
    'attempts', v_attempts,
    'locked_until', v_locked_until
  );
end;
$$;

create or replace function private.verify_manager_pin_internal(
  p_device_id text,
  p_outlet_id text,
  p_pin text,
  p_required_action text
) returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  v_actor uuid := auth.uid();
  v_tenant text;
  v_role text;
  v_hash text;
  v_active boolean;
  v_attempts integer;
  v_locked timestamptz;
  v_now timestamptz := now();
  v_ok boolean := false;
begin
  if v_actor is null then raise exception 'authenticated session required' using errcode='42501'; end if;
  if trim(p_device_id) = '' or trim(p_outlet_id) = '' or coalesce(p_pin,'') = '' then
    raise exception 'device, outlet and pin are required' using errcode='22023';
  end if;
  if p_required_action not in ('return_sale','void_sale','close_shift_variance') then
    raise exception 'unsupported manager pin action' using errcode='22023';
  end if;
  select d.tenant_id into v_tenant
  from public.devices d
  where d.device_id = trim(p_device_id) and d.user_id = v_actor;
  if v_tenant is null then raise exception 'device is not bound to actor' using errcode='42501'; end if;

  select role, pin_hash, is_active, attempts, locked_until
    into v_role, v_hash, v_active, v_attempts, v_locked
  from private.manager_pins
  where tenant_id = v_tenant and outlet_id = trim(p_outlet_id)
  for update;

  if v_hash is null or not coalesce(v_active,false) then
    insert into private.audit_logs(tenant_id, actor_id, device_id, source, reason, action)
    values (v_tenant, v_actor, trim(p_device_id), 'pos_pin', p_required_action, 'fail');
    return jsonb_build_object('ok',false,'role',v_role,'isActive',coalesce(v_active,false),'attempts',coalesce(v_attempts,0),'lockedUntil',v_locked);
  end if;

  if v_locked is not null and v_locked > v_now then
    insert into private.audit_logs(tenant_id, actor_id, device_id, source, reason, action)
    values (v_tenant, v_actor, trim(p_device_id), 'pos_pin', p_required_action, 'fail');
    return jsonb_build_object('ok',false,'role',v_role,'isActive',true,'attempts',v_attempts,'lockedUntil',v_locked);
  end if;

  v_ok := extensions.crypt(p_pin, v_hash) = v_hash;
  if v_ok then
    update private.manager_pins
       set attempts = 0, locked_until = null, updated_at = v_now
     where tenant_id = v_tenant and outlet_id = trim(p_outlet_id);
  else
    v_attempts := case when v_locked is not null and v_locked <= v_now then 1 else least(v_attempts + 1, 3) end;
    v_locked := case when v_attempts >= 3 then v_now + interval '5 minutes' else null end;
    update private.manager_pins
       set attempts = v_attempts, locked_until = v_locked, updated_at = v_now
     where tenant_id = v_tenant and outlet_id = trim(p_outlet_id);
  end if;

  insert into private.audit_logs(tenant_id, actor_id, device_id, source, reason, action)
  values (v_tenant, v_actor, trim(p_device_id), 'pos_pin', p_required_action, case when v_ok then 'success' else 'fail' end);

  return jsonb_build_object('ok',v_ok,'role',v_role,'isActive',true,'attempts',case when v_ok then 0 else v_attempts end,'lockedUntil',case when v_ok then null else v_locked end);
end;
$$;

