create or replace function private.build_supplier_payment_lines(
  p_tenant_id uuid,
  p_business_date date,
  p_facts jsonb
) returns jsonb
language plpgsql
stable
security definer
set search_path=''
as $$
declare
  v_gross bigint; v_base bigint; v_tax bigint:=0; v_net bigint; v_method text;
  v_party_id uuid; v_party public.tax_parties%rowtype; v_object text; v_tax_code text; v_rate_object text;
  v_tax_rule jsonb:='{}'::jsonb; v_rate numeric:=0; v_liability_account text:='2-2020'; v_payable_account text;
  v_payment_account text; v_journal jsonb:='[]'::jsonb; v_final_valid boolean:=false;
begin
  perform private.assert_no_accounting_fields(p_facts);
  if coalesce(p_facts->>'gross_liability','') !~ '^[1-9][0-9]*$' then raise exception 'gross_liability_required' using errcode='22023'; end if;
  v_gross:=(p_facts->>'gross_liability')::bigint;
  v_method:=upper(coalesce(p_facts->>'payment_method',''));
  if v_method='CASH' then v_payment_account:='1-1010'; elsif v_method='BANK' then v_payment_account:='1-1030'; else raise exception 'payment_method_must_be_cash_or_bank' using errcode='22023'; end if;
  begin v_party_id:=(p_facts->>'vendor_party_id')::uuid; exception when others then raise exception 'vendor_tax_party_required' using errcode='22023'; end;
  select * into strict v_party from public.tax_parties
  where tenant_id=p_tenant_id and party_id=v_party_id and party_kind='VENDOR'
    and valid_from<=p_business_date and (valid_to is null or valid_to>=p_business_date);

  v_object:=upper(coalesce(nullif(btrim(p_facts->>'tax_object'),''),'NONE'));
  if v_object<>'NONE' then
    if v_party.tax_object is null or upper(v_party.tax_object)<>v_object then
      raise exception 'vendor_tax_object_evidence_mismatch' using errcode='23514';
    end if;
  end if;

  if v_object='NONE' then
    v_net:=v_gross;
  else
    if coalesce(p_facts->>'pph_base','') !~ '^[1-9][0-9]*$' then raise exception 'pph_base_required_and_separate_from_vat_dpp' using errcode='22023'; end if;
    v_base:=(p_facts->>'pph_base')::bigint;
    if v_base>v_gross then raise exception 'pph_base_exceeds_liability' using errcode='23514'; end if;

    if v_object='LAND_BUILDING_RENT' then
      v_tax_code:='PPH_FINAL_4_2'; v_rate_object:='LAND_BUILDING_RENT'; v_payable_account:='2-2060';
    elsif v_object in ('SERVICE','ASSET_RENT_NON_LAND_BUILDING') then
      if upper(v_party.tax_regime)='PPH_FINAL_UMKM' then
        v_final_valid:=private.is_pph_final_umkm_evidence_valid(
          v_party.tax_regime,
          v_party.taxpayer_type,
          v_party.turnover_eligibility,
          v_party.certificate_status,
          v_party.legal_basis,
          p_business_date
        );
        if not v_final_valid then raise exception 'vendor_final_tax_evidence_invalid' using errcode='23514'; end if;
        v_tax_code:='PPH_FINAL_UMKM'; v_rate_object:='TURNOVER'; v_payable_account:='2-2060';
      else
        v_tax_code:='PPH23'; v_rate_object:=v_object; v_payable_account:='2-2050';
      end if;
    elsif v_object in ('DIVIDEND','INTEREST','ROYALTY') then
      v_tax_code:='PPH23'; v_rate_object:=v_object; v_payable_account:='2-2050';
    else
      raise exception 'unsupported_vendor_tax_object' using errcode='22023';
    end if;
    v_tax_rule:=private.resolve_tax_rate_snapshot(v_tax_code,v_rate_object,p_business_date,'DEFAULT');
    v_rate:=(v_tax_rule->>'effective_rate')::numeric;
    v_tax:=round(v_base::numeric*v_rate)::bigint;
    if v_tax<=0 or v_tax>=v_gross then raise exception 'invalid_withholding_amount' using errcode='23514'; end if;
    v_net:=v_gross-v_tax;
  end if;

  v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code',v_liability_account,'debit',v_gross,'credit',0,'memo','Pelunasan utang supplier'));
  v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code',v_payment_account,'debit',0,'credit',v_net,'memo','Pembayaran vendor'));
  if v_tax>0 then v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code',v_payable_account,'debit',0,'credit',v_tax,'memo','Pajak dipotong saat bayar')); end if;
  return jsonb_build_object(
    'journal_lines',v_journal,'vendor_party_id',v_party_id,'gross_liability',v_gross,'cash_paid',v_net,
    'withholding_amount',v_tax,'withholding_base',coalesce(v_base,0),'tax_code',v_tax_code,'tax_object',v_rate_object,
    'tax_snapshot',v_tax_rule,'withholding_account',v_payable_account
  );
end;
$$;

