create or replace function private.build_customer_receipt_lines(
  p_tenant_id uuid,
  p_business_date date,
  p_facts jsonb
) returns jsonb
language plpgsql
stable
security definer
set search_path=''
as $$
declare
  v_source text:=nullif(btrim(coalesce(p_facts->>'source_sale_ref','')),'');
  v_customer text:=nullif(btrim(coalesce(p_facts->>'customer_id','')),'');
  v_amount bigint;
  v_method text:=upper(coalesce(p_facts->>'payment_method',''));
  v_payment_account text;
  v_journal jsonb:='[]'::jsonb;
begin
  perform private.assert_no_accounting_fields(p_facts);
  if p_business_date is null then raise exception 'business_date_required' using errcode='22023'; end if;
  if v_source is null then raise exception 'source_sale_ref_required' using errcode='22023'; end if;
  if v_customer is null then raise exception 'customer_required_for_receivable_collection' using errcode='22023'; end if;
  if coalesce(p_facts->>'gross_receipt','') !~ '^[1-9][0-9]*$' then raise exception 'gross_receipt_required' using errcode='22023'; end if;
  v_amount:=(p_facts->>'gross_receipt')::bigint;
  if v_method='CASH' then v_payment_account:='1-1010';
  elsif v_method='QRIS' then v_payment_account:='1-1020';
  elsif v_method='BANK' then v_payment_account:='1-1030';
  else raise exception 'payment_method_must_be_cash_qris_or_bank' using errcode='22023'; end if;
  v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code',v_payment_account,'debit',v_amount,'credit',0,'memo','Penerimaan pembayaran pelanggan'));
  v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','1-1050','debit',0,'credit',v_amount,'memo','Pengurangan piutang pelanggan'));
  return jsonb_build_object('journal_lines',v_journal,'source_sale_ref',v_source,'customer_id',v_customer,'gross_receipt',v_amount);
end;
$$;
revoke all on function private.build_customer_receipt_lines(uuid,date,jsonb) from public,anon,authenticated,service_role;

create or replace function private.enforce_customer_receivable_evidence()
returns trigger
language plpgsql
security definer
set search_path=''
as $$
declare
  v_customer text;
  v_source text;
  v_amount bigint;
  v_ar_delta bigint;
  v_rec public.customer_receivables%rowtype;
  v_orig_type text;
begin
  if new.transaction_type='JUAL_KREDIT' then
    v_customer:=nullif(btrim(coalesce(new.facts_snapshot->>'customer_id','')),'');
    if v_customer is null then raise exception 'customer_required_for_credit_sale' using errcode='22023'; end if;
    select coalesce(sum(l.debit-l.credit),0)::bigint into v_ar_delta
    from public.accounting_journal_lines l
    where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code='1-1050';
    if v_ar_delta<=0 then raise exception 'credit_sale_receivable_missing' using errcode='23514'; end if;
    insert into public.customer_receivables(
      tenant_id,sale_transaction_ref,customer_ref,business_date,original_amount,remaining_amount,
      sale_journal_id,actor_user_id,device_id,reason
    ) values(
      new.tenant_id,new.transaction_ref,v_customer,new.business_date,v_ar_delta,v_ar_delta,
      new.journal_id,new.actor_user_id,new.device_id,new.reason
    );
  elsif new.transaction_type='TERIMA_PIUTANG' then
    v_source:=nullif(btrim(coalesce(new.facts_snapshot->>'source_sale_ref','')),'');
    v_customer:=nullif(btrim(coalesce(new.facts_snapshot->>'customer_id','')),'');
    if v_source is null or v_customer is null then raise exception 'receivable_collection_identity_required' using errcode='22023'; end if;
    if coalesce(new.facts_snapshot->>'gross_receipt','') !~ '^[1-9][0-9]*$' then raise exception 'gross_receipt_required' using errcode='22023'; end if;
    v_amount:=(new.facts_snapshot->>'gross_receipt')::bigint;
    select * into v_rec from public.customer_receivables r
    where r.tenant_id=new.tenant_id and r.sale_transaction_ref=v_source for update;
    if not found then raise exception 'customer_receivable_not_found' using errcode='P0002'; end if;
    if v_rec.customer_ref<>v_customer then raise exception 'customer_receivable_customer_mismatch' using errcode='23514'; end if;
    if new.business_date<v_rec.business_date then raise exception 'customer_receipt_before_credit_sale_date' using errcode='23514'; end if;
    if v_rec.remaining_amount<v_amount then raise exception 'customer_receipt_exceeds_outstanding_receivable' using errcode='23514'; end if;
    select coalesce(sum(l.credit-l.debit),0)::bigint into v_ar_delta
    from public.accounting_journal_lines l
    where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code='1-1050';
    if v_ar_delta<>v_amount then raise exception 'customer_receipt_gl_mismatch' using errcode='23514'; end if;
    update public.customer_receivables set remaining_amount=remaining_amount-v_amount,updated_at=now()
    where tenant_id=new.tenant_id and sale_transaction_ref=v_source;
    insert into public.customer_receivable_allocations(
      tenant_id,receipt_transaction_ref,sale_transaction_ref,customer_ref,amount_applied,
      receipt_journal_id,business_date,actor_user_id,device_id,reason
    ) values(
      new.tenant_id,new.transaction_ref,v_source,v_customer,v_amount,
      new.journal_id,new.business_date,new.actor_user_id,new.device_id,new.reason
    );
  elsif new.transaction_type='RETUR_PENJUALAN' then
    v_source:=nullif(btrim(coalesce(new.facts_snapshot->>'original_transaction_ref','')),'');
    select e.transaction_type into v_orig_type from public.accounting_transaction_evidence e
      where e.tenant_id=new.tenant_id and e.transaction_ref=v_source;
    if v_orig_type='JUAL_KREDIT' then
      select * into v_rec from public.customer_receivables r
      where r.tenant_id=new.tenant_id and r.sale_transaction_ref=v_source for update;
      if not found then raise exception 'credit_sale_receivable_not_found' using errcode='P0002'; end if;
      select coalesce(sum(l.credit-l.debit),0)::bigint into v_ar_delta
      from public.accounting_journal_lines l
      where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code='1-1050';
      if v_ar_delta<=0 then raise exception 'credit_sale_return_receivable_reduction_missing' using errcode='23514'; end if;
      if v_rec.remaining_amount<v_ar_delta then
        raise exception 'credit_sale_return_exceeds_open_receivable_requires_refund_flow' using errcode='23514';
      end if;
      update public.customer_receivables set remaining_amount=remaining_amount-v_ar_delta,updated_at=now()
      where tenant_id=new.tenant_id and sale_transaction_ref=v_source;
    end if;
  end if;
  return new;
end;
$$;
revoke all on function private.enforce_customer_receivable_evidence() from public,anon,authenticated,service_role;

