create or replace function public.mark_coretax_submitted(
  p_outbox_id uuid,
  p_coretax_reference text,
  p_device_id text,
  p_app_version text,
  p_reason text
) returns void
language plpgsql
security definer
set search_path=''
as $$
declare v_actor uuid:=auth.uid(); v_o public.coretax_outbox%rowtype; v_doc public.tax_documents%rowtype;
begin
  select * into strict v_o from public.coretax_outbox where outbox_id=p_outbox_id for update;
  select * into strict v_doc from public.tax_documents where tax_document_id=v_o.tax_document_id for update;
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  perform accounting_private.require_member_role(v_doc.tenant_id,v_actor,array['owner','admin','accountant']);
  perform private.assert_accounting_hard_gate(v_doc.tenant_id);
  if v_o.status<>'EXPORTED' or v_doc.status<>'VALIDATED' then
    raise exception 'coretax_submission_state_invalid' using errcode='55000';
  end if;
  if p_coretax_reference is null or length(btrim(p_coretax_reference))<3 or p_reason is null or length(btrim(p_reason))<3 then
    raise exception 'coretax_reference_and_reason_required' using errcode='22023';
  end if;
  update public.coretax_outbox
    set status='SENT',ack_reference=btrim(p_coretax_reference),attempt_count=attempt_count+1,updated_at=now()
    where outbox_id=p_outbox_id;
  update public.tax_documents
    set status='SUBMITTED',coretax_reference=btrim(p_coretax_reference),updated_at=now()
    where tax_document_id=v_doc.tax_document_id;
  insert into public.tax_document_events(tax_document_id,tenant_id,event_type,details,actor_user_id,device_id,reason)
  values(v_doc.tax_document_id,v_doc.tenant_id,'SUBMITTED',jsonb_build_object('outbox_id',p_outbox_id,'coretax_reference',btrim(p_coretax_reference)),v_actor,btrim(p_device_id),btrim(p_reason));
end;
$$;

revoke all on function public.mark_coretax_submitted(uuid,text,text,text,text) from public,anon,service_role;
grant execute on function public.mark_coretax_submitted(uuid,text,text,text,text) to authenticated;

do $patch$
declare v_def text; v_old text;
begin
  v_def:=pg_get_functiondef('private.compute_accounting_hard_gate(uuid)'::regprocedure);

  v_old:=v_def;
  v_def:=replace(v_def,
    $a$v_customer_subledger bigint; v_customer_gl bigint; v_customer_delta bigint; v_customer_negative bigint;$a$,
    $a$v_customer_subledger bigint; v_customer_gl bigint; v_customer_delta bigint; v_customer_negative bigint; v_tax_gl_mismatch bigint; v_tax_line_mismatch bigint; v_tax_event_lineage bigint;$a$);
  if v_def=v_old then raise exception 'tax_recon_declaration_anchor_missing'; end if;

  v_old:=v_def;
  v_def:=replace(v_def,
    $a$  v_customer_delta:=v_customer_subledger-v_customer_gl;

  return jsonb_build_object($a$,
    $a$  v_customer_delta:=v_customer_subledger-v_customer_gl;

  select count(*)::bigint into v_tax_gl_mismatch
  from public.tax_documents d
  left join lateral (
    select
      coalesce(sum(case when l.account_code='2-2010' then l.credit-l.debit else 0 end),0)::bigint as vat_output_net,
      coalesce(sum(case when l.account_code='1-1090' then l.debit-l.credit else 0 end),0)::bigint as vat_input_net,
      coalesce(sum(case when l.account_code='2-2040' then l.credit-l.debit else 0 end),0)::bigint as pph21_net,
      coalesce(sum(case when l.account_code='2-2050' then l.credit-l.debit else 0 end),0)::bigint as pph23_net,
      coalesce(sum(case when l.account_code='2-2060' then l.credit-l.debit else 0 end),0)::bigint as pph_final_net
    from public.accounting_journal_lines l
    where l.tenant_id=d.tenant_id and l.journal_id=d.journal_id
  ) g on true
  where d.tenant_id=p_tenant_id and (
    (d.document_type in ('VAT_OUTPUT','VAT_REPLACEMENT') and (d.journal_id is null or g.vat_output_net<>d.tax_amount))
    or (d.document_type in ('VAT_RETURN','VAT_CANCELLATION') and (d.journal_id is null or g.vat_output_net<>-d.tax_amount))
    or (d.document_type='VAT_INPUT' and d.journal_id is not null and (
      (d.creditable_input_vat and g.vat_input_net<>d.tax_amount)
      or (not d.creditable_input_vat and g.vat_input_net<>0)
    ))
    or (d.document_type='PPH21_26' and (d.journal_id is null or g.pph21_net<>d.tax_amount))
    or (d.document_type='PPH23_UNIFICATION' and (d.journal_id is null or g.pph23_net<>d.tax_amount))
    or (d.document_type='PPH_FINAL' and (d.journal_id is null or g.pph_final_net<>d.tax_amount))
  );

  select count(*)::bigint into v_tax_line_mismatch
  from public.tax_documents d
  left join lateral (
    select count(*)::bigint n,
           coalesce(sum(l.dpp),0)::bigint dpp,
           coalesce(sum(l.tax_amount),0)::bigint tax_amount,
           coalesce(sum(l.gross_amount),0)::bigint gross_amount
    from public.tax_document_lines l where l.tax_document_id=d.tax_document_id
  ) x on true
  where d.tenant_id=p_tenant_id and d.document_type in ('VAT_OUTPUT','VAT_RETURN','VAT_REPLACEMENT')
    and (x.n=0 or x.dpp<>d.dpp or x.tax_amount<>d.tax_amount or x.gross_amount<>d.gross_amount);

  select count(*)::bigint into v_tax_event_lineage
  from public.tax_documents d
  where d.tenant_id=p_tenant_id and (
    not exists(select 1 from public.tax_document_events e where e.tax_document_id=d.tax_document_id and e.event_type='VALIDATED')
    or (d.status in ('SUBMITTED','ACCEPTED','REJECTED','REPORTED') and not exists(
      select 1 from public.tax_document_events e where e.tax_document_id=d.tax_document_id and e.event_type='SUBMITTED'))
    or (d.status in ('ACCEPTED','REPORTED') and not exists(
      select 1 from public.tax_document_events e where e.tax_document_id=d.tax_document_id and e.event_type='CORETAX_ACK'))
    or (d.status='REJECTED' and not exists(
      select 1 from public.tax_document_events e where e.tax_document_id=d.tax_document_id and e.event_type='CORETAX_REJECTED'))
  );

  return jsonb_build_object($a$);
  if v_def=v_old then raise exception 'tax_recon_compute_anchor_missing'; end if;

  v_old:=v_def;
  v_def:=replace(v_def,
    $a$'customer_receivable_negative_count',v_customer_negative,$a$,
    $a$'customer_receivable_negative_count',v_customer_negative,
    'tax_document_gl_mismatch_count',v_tax_gl_mismatch,
    'tax_document_line_mismatch_count',v_tax_line_mismatch,
    'tax_document_event_lineage_missing_count',v_tax_event_lineage,$a$);
  if v_def=v_old then raise exception 'tax_recon_output_anchor_missing'; end if;

  v_old:=v_def;
  v_def:=replace(v_def,
    $a$v_customer_delta=0 and v_customer_negative=0)$a$,
    $a$v_customer_delta=0 and v_customer_negative=0 and v_tax_gl_mismatch=0 and v_tax_line_mismatch=0 and v_tax_event_lineage=0)$a$);
  if v_def=v_old then raise exception 'tax_recon_allzero_anchor_missing'; end if;

  execute v_def;
end;
$patch$;

