create or replace function private.enforce_supplier_liability_evidence()
returns trigger
language plpgsql
security definer
set search_path=''
as $$
declare
  v_vendor uuid;
  v_supplier_ref text;
  v_purchase_ref text;
  v_gross bigint;
  v_cash bigint;
  v_withholding bigint;
  v_ap_delta bigint;
  v_liability public.supplier_liabilities%rowtype;
  v_input_doc public.tax_documents%rowtype;
  v_payment_object text;
begin
  if new.transaction_type='BELI_KREDIT' then
    v_supplier_ref:=nullif(btrim(coalesce(new.facts_snapshot->>'supplier_id','')),'');
    if v_supplier_ref is null then
      raise exception 'supplier_required_for_credit_purchase' using errcode='22023';
    end if;
    if upper(coalesce(nullif(btrim(new.facts_snapshot->>'tax_object'),''),'NONE'))<>'NONE' then
      raise exception 'inventory_purchase_cannot_define_withholding_tax_object' using errcode='23514';
    end if;
    begin
      v_vendor:=(new.facts_snapshot->>'vendor_party_id')::uuid;
    exception when others then
      raise exception 'vendor_tax_party_required_for_credit_purchase' using errcode='22023';
    end;
    if not exists(
      select 1 from public.tax_parties tp
      where tp.tenant_id=new.tenant_id and tp.party_id=v_vendor and tp.party_kind='VENDOR'
        and tp.valid_from<=new.business_date and (tp.valid_to is null or tp.valid_to>=new.business_date)
    ) then
      raise exception 'vendor_tax_party_evidence_invalid' using errcode='23514';
    end if;

    if nullif(btrim(coalesce(new.facts_snapshot->>'input_tax_document_id','')),'') is not null then
      begin
        select * into strict v_input_doc
        from public.tax_documents d
        where d.tenant_id=new.tenant_id
          and d.tax_document_id=(new.facts_snapshot->>'input_tax_document_id')::uuid
          and d.document_type='VAT_INPUT';
      exception when no_data_found then
        raise exception 'input_tax_document_not_found' using errcode='P0002';
      end;
      if v_input_doc.counterparty_id is distinct from v_vendor then
        raise exception 'input_tax_invoice_vendor_mismatch' using errcode='23514';
      end if;
    end if;

    select coalesce(sum(l.credit-l.debit),0)::bigint into v_ap_delta
    from public.accounting_journal_lines l
    where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code='2-2020';
    if v_ap_delta<=0 then
      raise exception 'purchase_supplier_liability_missing' using errcode='23514';
    end if;

    insert into public.supplier_liabilities(
      tenant_id,purchase_transaction_ref,supplier_ref,vendor_party_id,business_date,
      original_amount,remaining_amount,purchase_journal_id,actor_user_id,device_id,reason,
      liability_kind,tax_object_code
    ) values(
      new.tenant_id,new.transaction_ref,v_supplier_ref,v_vendor,new.business_date,
      v_ap_delta,v_ap_delta,new.journal_id,new.actor_user_id,new.device_id,new.reason,
      'INVENTORY','NONE'
    );

  elsif new.transaction_type='BAYAR_VENDOR' then
    v_purchase_ref:=nullif(btrim(coalesce(new.facts_snapshot->>'source_purchase_ref','')),'');
    if v_purchase_ref is null then
      raise exception 'source_purchase_ref_required' using errcode='22023';
    end if;
    begin
      v_vendor:=(new.facts_snapshot->>'vendor_party_id')::uuid;
    exception when others then
      raise exception 'vendor_tax_party_required' using errcode='22023';
    end;
    if coalesce(new.facts_snapshot->>'gross_liability','') !~ '^[1-9][0-9]*$' then
      raise exception 'gross_liability_required' using errcode='22023';
    end if;
    v_gross:=(new.facts_snapshot->>'gross_liability')::bigint;
    v_payment_object:=upper(coalesce(nullif(btrim(new.facts_snapshot->>'tax_object'),''),'NONE'));

    select * into v_liability
    from public.supplier_liabilities s
    where s.tenant_id=new.tenant_id and s.purchase_transaction_ref=v_purchase_ref
    for update;
    if not found then
      raise exception 'supplier_liability_not_found' using errcode='P0002';
    end if;
    if v_liability.vendor_party_id<>v_vendor then
      raise exception 'supplier_liability_vendor_mismatch' using errcode='23514';
    end if;
    if v_payment_object<>v_liability.tax_object_code then
      raise exception 'supplier_payment_tax_object_must_match_source_liability' using errcode='23514';
    end if;
    if new.business_date<v_liability.business_date then
      raise exception 'supplier_payment_before_purchase_date' using errcode='23514';
    end if;
    if v_liability.remaining_amount<v_gross then
      raise exception 'supplier_payment_exceeds_outstanding_liability' using errcode='23514';
    end if;

    select coalesce(sum(l.debit-l.credit),0)::bigint into v_ap_delta
    from public.accounting_journal_lines l
    where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code='2-2020';
    if v_ap_delta<>v_gross then
      raise exception 'supplier_payment_gl_liability_mismatch' using errcode='23514';
    end if;

    select coalesce(sum(l.credit-l.debit),0)::bigint into v_withholding
    from public.accounting_journal_lines l
    where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code in ('2-2050','2-2060');
    if v_liability.tax_object_code='NONE' and v_withholding<>0 then
      raise exception 'source_liability_does_not_allow_withholding' using errcode='23514';
    end if;
    v_cash:=v_gross-v_withholding;
    if v_cash<0 then raise exception 'supplier_payment_cash_invalid' using errcode='23514'; end if;

    update public.supplier_liabilities
      set remaining_amount=remaining_amount-v_gross,updated_at=now()
    where tenant_id=new.tenant_id and purchase_transaction_ref=v_purchase_ref;

    insert into public.supplier_payment_allocations(
      tenant_id,payment_transaction_ref,purchase_transaction_ref,vendor_party_id,
      gross_applied,cash_paid,withholding_amount,payment_journal_id,business_date,
      actor_user_id,device_id,reason
    ) values(
      new.tenant_id,new.transaction_ref,v_purchase_ref,v_vendor,
      v_gross,v_cash,v_withholding,new.journal_id,new.business_date,
      new.actor_user_id,new.device_id,new.reason
    );
  end if;
  return new;
end;
$$;

revoke all on function private.enforce_supplier_liability_evidence()
  from public,anon,authenticated,service_role;

create or replace function public.get_compliance_readiness(
  p_tenant_id uuid,
  p_business_date date,
  p_device_id text,
  p_app_version text
) returns jsonb
language plpgsql
stable
security definer
set search_path=''
as $$
declare
  v_actor uuid:=auth.uid();
  v_gate jsonb;
  v_self_row_count bigint;
  v_self_count bigint;
  v_coretax_self_count bigint;
  v_template_count bigint;
  v_templates jsonb;
  v_blockers jsonb:='[]'::jsonb;
  v_accounting_ready boolean;
  v_sale_tax_ready boolean;
  v_coretax_ready boolean;
  v_pph21_payroll_ready boolean;
  v_vendor_withholding_source_ready boolean;
  v_owner_adjustment_intents_ready boolean;
  v_full_compliance_ready boolean;
begin
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  perform accounting_private.require_member_role(p_tenant_id,v_actor,array['owner','admin','accountant','cashier']);
  if p_business_date is null then
    raise exception 'business_date_required' using errcode='22023';
  end if;

  v_gate:=private.compute_accounting_hard_gate(p_tenant_id);
  v_accounting_ready:=coalesce((v_gate->>'all_zero')::boolean,false);

  select count(*)::bigint into v_self_row_count
  from public.tax_parties tp
  where tp.tenant_id=p_tenant_id
    and tp.party_kind='SELF'
    and tp.valid_from<=p_business_date
    and (tp.valid_to is null or tp.valid_to>=p_business_date);

  select count(*)::bigint into v_self_count
  from public.tax_parties tp
  where tp.tenant_id=p_tenant_id
    and tp.party_kind='SELF'
    and tp.valid_from<=p_business_date
    and (tp.valid_to is null or tp.valid_to>=p_business_date)
    and (
      (tp.is_pkp and tp.certificate_status='VALID')
      or (not tp.is_pkp and tp.certificate_status in ('VALID','NOT_REQUIRED'))
    );

  select count(*)::bigint into v_coretax_self_count
  from public.tax_parties tp
  where tp.tenant_id=p_tenant_id
    and tp.party_kind='SELF'
    and tp.valid_from<=p_business_date
    and (tp.valid_to is null or tp.valid_to>=p_business_date)
    and tp.certificate_status='VALID';

  select count(*)::bigint,
         coalesce(jsonb_object_agg(template_code,jsonb_build_object(
           'verified',is_verified,
           'active',is_active,
           'has_xml',xml_template is not null,
           'has_sha256',template_sha256 is not null,
           'version',template_version,
           'official_source_url',official_source_url,
           'generator_status',coalesce(generator_spec->>'status','')
         )),'{}'::jsonb)
  into v_template_count,v_templates
  from public.coretax_template_registry
  where template_code in ('FAKTUR_KELUARAN','BPPU','BPMP')
    and is_verified and is_active and xml_template is not null
    and template_sha256 ~ '^[0-9a-f]{64}$'
    and coalesce(generator_spec->>'status','')<>'SOURCE_REGISTERED_NOT_PARSED';

  v_sale_tax_ready:=v_accounting_ready and v_self_count=1;
  v_coretax_ready:=v_accounting_ready and v_coretax_self_count=1 and v_template_count=3;

  v_pph21_payroll_ready :=
    to_regclass('public.employee_tax_profiles') is not null
    and to_regclass('public.payroll_tax_evidence') is not null
    and to_regprocedure('private.build_payroll_lines(uuid,date,jsonb,uuid,text,text)') is not null;

  v_vendor_withholding_source_ready :=
    to_regprocedure('private.build_vendor_expense_accrual_lines(uuid,text,date,jsonb,uuid,text,text)') is not null;

  v_owner_adjustment_intents_ready :=
    to_regprocedure('private.build_owner_draw_lines(uuid,date,jsonb)') is not null
    and to_regprocedure('private.build_depreciation_lines(uuid,date,jsonb)') is not null
    and to_regprocedure('private.build_bad_debt_allowance_lines(uuid,date,jsonb)') is not null;

  v_full_compliance_ready :=
    v_accounting_ready
    and v_sale_tax_ready
    and v_coretax_ready
    and v_pph21_payroll_ready
    and v_vendor_withholding_source_ready
    and v_owner_adjustment_intents_ready;

  if not v_accounting_ready then
    v_blockers:=v_blockers||jsonb_build_array('ACCOUNTING_HARD_GATE_NOT_ZERO');
  end if;
  if v_self_count<>1 then
    v_blockers:=v_blockers||jsonb_build_array('EXACTLY_ONE_EFFECTIVE_SELF_TAX_PROFILE_REQUIRED');
  end if;
  if v_coretax_self_count<>1 then
    v_blockers:=v_blockers||jsonb_build_array('EXACTLY_ONE_VALID_SELF_TAX_PROFILE_REQUIRED_FOR_CORETAX');
  end if;
  if v_template_count<>3 then
    v_blockers:=v_blockers||jsonb_build_array('CORETAX_OFFICIAL_TEMPLATES_NOT_VERIFIED');
  end if;
  if not v_pph21_payroll_ready then
    v_blockers:=v_blockers||jsonb_build_array('PPH21_PAYROLL_EVIDENCE_ENGINE_NOT_READY');
  end if;
  if not v_vendor_withholding_source_ready then
    v_blockers:=v_blockers||jsonb_build_array('VENDOR_WITHHOLDING_SOURCE_ACCRUAL_NOT_READY');
  end if;
  if not v_owner_adjustment_intents_ready then
    v_blockers:=v_blockers||jsonb_build_array('OWNER_ACCOUNTING_ADJUSTMENT_INTENTS_NOT_READY');
  end if;

  return jsonb_build_object(
    'business_date',p_business_date,
    'accounting_ready',v_accounting_ready,
    'sale_tax_ready',v_sale_tax_ready,
    'coretax_ready',v_coretax_ready,
    'full_compliance_ready',v_full_compliance_ready,
    'capabilities',jsonb_build_object(
      'pph21_payroll_engine_ready',v_pph21_payroll_ready,
      'vendor_withholding_source_ready',v_vendor_withholding_source_ready,
      'owner_adjustment_intents_ready',v_owner_adjustment_intents_ready
    ),
    'effective_self_tax_profile_row_count',v_self_row_count,
    'effective_self_tax_profile_count',v_self_count,
    'effective_coretax_self_tax_profile_count',v_coretax_self_count,
    'verified_active_coretax_template_count',v_template_count,
    'required_coretax_template_count',3,
    'coretax_templates',v_templates,
    'accounting_gate',v_gate,
    'blockers',v_blockers
  );
end;
$$;

revoke all on function public.get_compliance_readiness(uuid,date,text,text)
  from public,anon,service_role;
grant execute on function public.get_compliance_readiness(uuid,date,text,text)
  to authenticated;

alter table public.supplier_liabilities
  add column if not exists withholding_base_original bigint not null default 0,
  add column if not exists withholding_base_remaining bigint not null default 0;

alter table public.supplier_liabilities
  drop constraint if exists supplier_liabilities_withholding_base_check;
alter table public.supplier_liabilities
  add constraint supplier_liabilities_withholding_base_check
  check (
    withholding_base_original>=0
    and withholding_base_remaining>=0
    and withholding_base_remaining<=withholding_base_original
  );

create or replace function private.build_vendor_expense_accrual_lines(
  p_tenant_id uuid,
  p_transaction_ref text,
  p_business_date date,
  p_facts jsonb,
  p_actor uuid,
  p_device_id text,
  p_reason text
) returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  v_vendor uuid;
  v_party public.tax_parties%rowtype;
  v_object text;
  v_kind text;
  v_expense_account text;
  v_base bigint;
  v_withholding_base bigint;
  v_vat_mode text:=upper(coalesce(nullif(btrim(p_facts->>'vat_mode'),''),'NONE'));
  v_doc_id uuid;
  v_doc public.tax_documents%rowtype;
  v_tax bigint:=0;
  v_expense_debit bigint;
  v_liability bigint;
  v_journal jsonb:='[]'::jsonb;
begin
  perform private.assert_no_accounting_fields(p_facts);
  if p_transaction_ref is null or length(btrim(p_transaction_ref))=0 or p_business_date is null then
    raise exception 'vendor_expense_identity_required' using errcode='22023';
  end if;
  begin
    v_vendor:=(p_facts->>'vendor_party_id')::uuid;
  exception when others then
    raise exception 'vendor_tax_party_required' using errcode='22023';
  end;
  select * into strict v_party
  from public.tax_parties tp
  where tp.tenant_id=p_tenant_id and tp.party_id=v_vendor and tp.party_kind='VENDOR'
    and tp.valid_from<=p_business_date and (tp.valid_to is null or tp.valid_to>=p_business_date);

  v_object:=upper(coalesce(v_party.tax_object,''));
  if v_object='SERVICE' then
    v_kind:='SERVICE';
    v_expense_account:='6-6030';
  elsif v_object in ('LAND_BUILDING_RENT','ASSET_RENT_NON_LAND_BUILDING') then
    v_kind:='RENT';
    v_expense_account:='6-6040';
  else
    raise exception 'vendor_tax_object_not_supported_for_expense_accrual' using errcode='23514';
  end if;

  if coalesce(p_facts->>'expense_base','') !~ '^[1-9][0-9]*$' then
    raise exception 'expense_base_required' using errcode='22023';
  end if;
  if coalesce(p_facts->>'withholding_base','') !~ '^[1-9][0-9]*$' then
    raise exception 'withholding_base_required_separate_from_vat_dpp' using errcode='22023';
  end if;
  v_base:=(p_facts->>'expense_base')::bigint;
  v_withholding_base:=(p_facts->>'withholding_base')::bigint;
  if v_withholding_base>v_base then
    raise exception 'withholding_base_exceeds_expense_base' using errcode='23514';
  end if;
  if v_object='LAND_BUILDING_RENT' and v_withholding_base<>v_base then
    raise exception 'land_building_rent_withholding_base_must_equal_gross_rent' using errcode='23514';
  end if;
  if v_vat_mode not in ('NONE','CREDITABLE','NON_CREDITABLE') then
    raise exception 'invalid_vendor_expense_vat_mode' using errcode='22023';
  end if;

  if v_vat_mode<>'NONE' then
    begin
      v_doc_id:=(p_facts->>'input_tax_document_id')::uuid;
    exception when others then
      raise exception 'input_tax_document_id_required' using errcode='22023';
    end;
    select * into strict v_doc
    from public.tax_documents d
    where d.tax_document_id=v_doc_id
      and d.tenant_id=p_tenant_id
      and d.document_type='VAT_INPUT';
    if v_doc.counterparty_id is distinct from v_vendor then
      raise exception 'input_tax_invoice_vendor_mismatch' using errcode='23514';
    end if;
    if v_doc.status not in ('VALIDATED','ACCEPTED','REPORTED') then
      raise exception 'input_tax_invoice_not_validated' using errcode='23514';
    end if;
    if v_doc.dpp<>v_base then
      raise exception 'vendor_expense_dpp_does_not_match_input_tax_invoice' using errcode='23514';
    end if;
    if v_vat_mode='CREDITABLE' then
      if v_doc.invoice_status<>'VALID' or not v_doc.creditable_input_vat or v_doc.tax_amount<=0 then
        raise exception 'input_tax_invoice_not_creditable' using errcode='23514';
      end if;
    else
      if v_doc.creditable_input_vat then
        raise exception 'creditable_input_vat_cannot_be_capitalized_to_expense' using errcode='23514';
      end if;
    end if;
    v_tax:=v_doc.tax_amount;
  elsif p_facts ? 'input_tax_document_id' and nullif(btrim(p_facts->>'input_tax_document_id'),'') is not null then
    raise exception 'vat_mode_required_when_input_tax_document_present' using errcode='22023';
  end if;

  v_expense_debit:=v_base + case when v_vat_mode='NON_CREDITABLE' then v_tax else 0 end;
  v_liability:=v_base+v_tax;
  v_journal:=v_journal||jsonb_build_array(jsonb_build_object(
    'account_code',v_expense_account,'debit',v_expense_debit,'credit',0,
    'memo',case when v_kind='RENT' then 'Beban sewa vendor' else 'Beban jasa vendor' end
  ));
  if v_vat_mode='CREDITABLE' and v_tax>0 then
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object(
      'account_code','1-1090','debit',v_tax,'credit',0,'memo','PPN pembelian yang bisa diperhitungkan'
    ));
  end if;
  v_journal:=v_journal||jsonb_build_array(jsonb_build_object(
    'account_code','2-2020','debit',0,'credit',v_liability,'memo','Utang supplier jasa/sewa'
  ));

  return jsonb_build_object(
    'journal_lines',v_journal,
    'vendor_party_id',v_vendor,
    'liability_kind',v_kind,
    'tax_object',v_object,
    'expense_base',v_base,
    'withholding_base',v_withholding_base,
    'vat_mode',v_vat_mode,
    'input_tax_document_id',v_doc_id,
    'input_vat',case when v_vat_mode='CREDITABLE' then v_tax else 0 end,
    'liability',v_liability,
    'tax_snapshot',case when v_doc_id is null then '{}'::jsonb else v_doc.tax_rate_snapshot end
  );
exception when no_data_found then
  raise exception 'vendor_expense_tax_master_dependency_missing' using errcode='23514';
end;
$$;
revoke all on function private.build_vendor_expense_accrual_lines(uuid,text,date,jsonb,uuid,text,text)
  from public,anon,authenticated,service_role;

create or replace function private.build_supplier_payment_lines(
  p_tenant_id uuid,
  p_business_date date,
  p_facts jsonb
) returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  v_source_ref text:=nullif(btrim(coalesce(p_facts->>'source_purchase_ref','')),'');
  v_liability public.supplier_liabilities%rowtype;
  v_gross bigint;
  v_base bigint:=0;
  v_tax bigint:=0;
  v_net bigint;
  v_method text;
  v_party public.tax_parties%rowtype;
  v_object text;
  v_tax_code text;
  v_rate_object text;
  v_tax_rule jsonb:='{}'::jsonb;
  v_rate numeric:=0;
  v_payable_account text;
  v_payment_account text;
  v_journal jsonb:='[]'::jsonb;
  v_final_valid boolean:=false;
  v_claim_vendor uuid;
begin
  perform private.assert_no_accounting_fields(p_facts);
  if p_business_date is null then raise exception 'business_date_required' using errcode='22023'; end if;
  if v_source_ref is null then raise exception 'source_purchase_ref_required' using errcode='22023'; end if;

  select * into strict v_liability
  from public.supplier_liabilities s
  where s.tenant_id=p_tenant_id and s.purchase_transaction_ref=v_source_ref
  for update;
  if p_business_date<v_liability.business_date then
    raise exception 'supplier_payment_before_source_liability_date' using errcode='23514';
  end if;
  if v_liability.remaining_amount<=0 then
    raise exception 'supplier_liability_already_settled' using errcode='23514';
  end if;

  if p_facts ? 'vendor_party_id' and nullif(btrim(p_facts->>'vendor_party_id'),'') is not null then
    begin v_claim_vendor:=(p_facts->>'vendor_party_id')::uuid;
    exception when others then raise exception 'invalid_vendor_party_id' using errcode='22023'; end;
    if v_claim_vendor<>v_liability.vendor_party_id then
      raise exception 'supplier_liability_vendor_mismatch' using errcode='23514';
    end if;
  end if;

  select * into strict v_party
  from public.tax_parties tp
  where tp.tenant_id=p_tenant_id and tp.party_id=v_liability.vendor_party_id and tp.party_kind='VENDOR'
    and tp.valid_from<=p_business_date and (tp.valid_to is null or tp.valid_to>=p_business_date);

  v_method:=upper(coalesce(p_facts->>'payment_method',''));
  if v_method='CASH' then v_payment_account:='1-1010';
  elsif v_method='BANK' then v_payment_account:='1-1030';
  else raise exception 'payment_method_must_be_cash_or_bank' using errcode='22023'; end if;

  v_object:=v_liability.tax_object_code;
  if p_facts ? 'tax_object' and upper(coalesce(nullif(btrim(p_facts->>'tax_object'),''),'NONE'))<>v_object then
    raise exception 'supplier_payment_tax_object_claim_mismatch' using errcode='23514';
  end if;

  if v_object='NONE' then
    if p_facts ? 'pph_base' and nullif(btrim(p_facts->>'pph_base'),'') is not null then
      raise exception 'pph_base_not_allowed_for_non_withholding_liability' using errcode='23514';
    end if;
    if p_facts ? 'gross_liability' then
      if coalesce(p_facts->>'gross_liability','') !~ '^[1-9][0-9]*$' then
        raise exception 'gross_liability_must_be_positive_integer' using errcode='22023';
      end if;
      v_gross:=(p_facts->>'gross_liability')::bigint;
    else
      v_gross:=v_liability.remaining_amount;
    end if;
    if v_gross>v_liability.remaining_amount then
      raise exception 'supplier_payment_exceeds_outstanding_liability' using errcode='23514';
    end if;
  else
    if v_liability.withholding_base_remaining<=0 then
      raise exception 'withholding_source_base_missing' using errcode='23514';
    end if;
    if p_facts ? 'gross_liability' and (p_facts->>'gross_liability')::bigint<>v_liability.remaining_amount then
      raise exception 'taxed_supplier_liability_requires_full_settlement' using errcode='23514';
    end if;
    if p_facts ? 'pph_base' and (p_facts->>'pph_base')::bigint<>v_liability.withholding_base_remaining then
      raise exception 'pph_base_claim_mismatch_source_liability' using errcode='23514';
    end if;
    v_gross:=v_liability.remaining_amount;
    v_base:=v_liability.withholding_base_remaining;

    if v_object='LAND_BUILDING_RENT' then
      v_tax_code:='PPH_FINAL_4_2'; v_rate_object:='LAND_BUILDING_RENT'; v_payable_account:='2-2060';
    elsif v_object in ('SERVICE','ASSET_RENT_NON_LAND_BUILDING') then
      if upper(v_party.tax_regime)='PPH_FINAL_UMKM' then
        v_final_valid:=private.is_pph_final_umkm_evidence_valid(
          v_party.tax_regime,v_party.taxpayer_type,v_party.turnover_eligibility,
          v_party.certificate_status,v_party.legal_basis,p_business_date
        );
        if not v_final_valid then raise exception 'vendor_final_tax_evidence_invalid' using errcode='23514'; end if;
        v_tax_code:='PPH_FINAL_UMKM'; v_rate_object:='TURNOVER'; v_payable_account:='2-2060';
      else
        v_tax_code:='PPH23'; v_rate_object:=v_object; v_payable_account:='2-2050';
      end if;
    else
      raise exception 'unsupported_source_liability_tax_object' using errcode='23514';
    end if;
    v_tax_rule:=private.resolve_tax_rate_snapshot(v_tax_code,v_rate_object,p_business_date,'DEFAULT');
    v_rate:=(v_tax_rule->>'effective_rate')::numeric;
    v_tax:=round(v_base::numeric*v_rate)::bigint;
    if v_tax<=0 or v_tax>=v_gross then raise exception 'invalid_withholding_amount' using errcode='23514'; end if;
  end if;

  v_net:=v_gross-v_tax;
  v_journal:=v_journal||jsonb_build_array(jsonb_build_object(
    'account_code','2-2020','debit',v_gross,'credit',0,'memo','Pelunasan utang supplier'
  ));
  v_journal:=v_journal||jsonb_build_array(jsonb_build_object(
    'account_code',v_payment_account,'debit',0,'credit',v_net,'memo','Pembayaran vendor'
  ));
  if v_tax>0 then
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object(
      'account_code',v_payable_account,'debit',0,'credit',v_tax,'memo','Pajak dipotong saat bayar'
    ));
  end if;
  return jsonb_build_object(
    'journal_lines',v_journal,
    'source_purchase_ref',v_source_ref,
    'vendor_party_id',v_liability.vendor_party_id,
    'gross_liability',v_gross,
    'cash_paid',v_net,
    'withholding_amount',v_tax,
    'withholding_base',v_base,
    'tax_code',v_tax_code,
    'tax_object',case when v_object='NONE' then null else v_rate_object end,
    'tax_snapshot',v_tax_rule,
    'withholding_account',v_payable_account
  );
exception when no_data_found then
  raise exception 'supplier_payment_source_dependency_missing' using errcode='23514';
end;
$$;
revoke all on function private.build_supplier_payment_lines(uuid,date,jsonb)
  from public,anon,authenticated,service_role;

create or replace function private.enforce_supplier_liability_evidence()
returns trigger
language plpgsql
security definer
set search_path=''
as $$
declare
  v_vendor uuid;
  v_supplier_ref text;
  v_source_ref text;
  v_ap_delta bigint;
  v_liability public.supplier_liabilities%rowtype;
  v_input_doc public.tax_documents%rowtype;
  v_withholding bigint;
  v_expected_withholding bigint:=0;
  v_expected_tax jsonb;
  v_party public.tax_parties%rowtype;
  v_expected_tax_code text;
  v_expected_rate_object text;
begin
  if new.transaction_type in ('BELI_KREDIT','BEBAN_VENDOR_KREDIT') then
    v_supplier_ref:=nullif(btrim(coalesce(new.facts_snapshot->>'supplier_id','')),'');
    if v_supplier_ref is null then raise exception 'supplier_required_for_credit_liability' using errcode='22023'; end if;
    begin v_vendor:=(new.facts_snapshot->>'vendor_party_id')::uuid;
    exception when others then raise exception 'vendor_tax_party_required_for_credit_liability' using errcode='22023'; end;
    if not exists(
      select 1 from public.tax_parties tp
      where tp.tenant_id=new.tenant_id and tp.party_id=v_vendor and tp.party_kind='VENDOR'
        and tp.valid_from<=new.business_date and (tp.valid_to is null or tp.valid_to>=new.business_date)
    ) then raise exception 'vendor_tax_party_evidence_invalid' using errcode='23514'; end if;

    if nullif(btrim(coalesce(new.facts_snapshot->>'input_tax_document_id','')),'') is not null then
      select * into strict v_input_doc
      from public.tax_documents d
      where d.tenant_id=new.tenant_id
        and d.tax_document_id=(new.facts_snapshot->>'input_tax_document_id')::uuid
        and d.document_type='VAT_INPUT';
      if v_input_doc.counterparty_id is distinct from v_vendor then
        raise exception 'input_tax_invoice_vendor_mismatch' using errcode='23514';
      end if;
    end if;

    select coalesce(sum(l.credit-l.debit),0)::bigint into v_ap_delta
    from public.accounting_journal_lines l
    where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code='2-2020';
    if v_ap_delta<=0 then raise exception 'supplier_liability_missing' using errcode='23514'; end if;

    if new.transaction_type='BELI_KREDIT' then
      if upper(coalesce(nullif(btrim(new.facts_snapshot->>'tax_object'),''),'NONE'))<>'NONE' then
        raise exception 'inventory_purchase_cannot_define_withholding_tax_object' using errcode='23514';
      end if;
      insert into public.supplier_liabilities(
        tenant_id,purchase_transaction_ref,supplier_ref,vendor_party_id,business_date,
        original_amount,remaining_amount,purchase_journal_id,actor_user_id,device_id,reason,
        liability_kind,tax_object_code,withholding_base_original,withholding_base_remaining
      ) values(
        new.tenant_id,new.transaction_ref,v_supplier_ref,v_vendor,new.business_date,
        v_ap_delta,v_ap_delta,new.journal_id,new.actor_user_id,new.device_id,new.reason,
        'INVENTORY','NONE',0,0
      );
    else
      select * into strict v_party
      from public.tax_parties tp
      where tp.tenant_id=new.tenant_id and tp.party_id=v_vendor;
      if coalesce(new.facts_snapshot->>'withholding_base','') !~ '^[1-9][0-9]*$' then
        raise exception 'withholding_base_required_for_vendor_expense' using errcode='22023';
      end if;
      insert into public.supplier_liabilities(
        tenant_id,purchase_transaction_ref,supplier_ref,vendor_party_id,business_date,
        original_amount,remaining_amount,purchase_journal_id,actor_user_id,device_id,reason,
        liability_kind,tax_object_code,withholding_base_original,withholding_base_remaining
      ) values(
        new.tenant_id,new.transaction_ref,v_supplier_ref,v_vendor,new.business_date,
        v_ap_delta,v_ap_delta,new.journal_id,new.actor_user_id,new.device_id,new.reason,
        case when upper(v_party.tax_object)='SERVICE' then 'SERVICE' else 'RENT' end,
        upper(v_party.tax_object),
        (new.facts_snapshot->>'withholding_base')::bigint,
        (new.facts_snapshot->>'withholding_base')::bigint
      );
    end if;

  elsif new.transaction_type='BAYAR_VENDOR' then
    v_source_ref:=nullif(btrim(coalesce(new.facts_snapshot->>'source_purchase_ref','')),'');
    if v_source_ref is null then raise exception 'source_purchase_ref_required' using errcode='22023'; end if;
    select * into v_liability
    from public.supplier_liabilities s
    where s.tenant_id=new.tenant_id and s.purchase_transaction_ref=v_source_ref
    for update;
    if not found then raise exception 'supplier_liability_not_found' using errcode='P0002'; end if;
    if new.business_date<v_liability.business_date then raise exception 'supplier_payment_before_source_liability_date' using errcode='23514'; end if;

    select coalesce(sum(l.debit-l.credit),0)::bigint into v_ap_delta
    from public.accounting_journal_lines l
    where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code='2-2020';
    if v_ap_delta<=0 or v_ap_delta>v_liability.remaining_amount then
      raise exception 'supplier_payment_gl_liability_mismatch' using errcode='23514';
    end if;

    select coalesce(sum(l.credit-l.debit),0)::bigint into v_withholding
    from public.accounting_journal_lines l
    where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code in ('2-2050','2-2060');

    if v_liability.tax_object_code='NONE' then
      if v_withholding<>0 then raise exception 'source_liability_does_not_allow_withholding' using errcode='23514'; end if;
    else
      if v_ap_delta<>v_liability.remaining_amount then
        raise exception 'taxed_supplier_liability_requires_full_settlement' using errcode='23514';
      end if;
      select * into strict v_party from public.tax_parties tp
      where tp.tenant_id=new.tenant_id and tp.party_id=v_liability.vendor_party_id
        and tp.valid_from<=new.business_date and (tp.valid_to is null or tp.valid_to>=new.business_date);
      if v_liability.tax_object_code='LAND_BUILDING_RENT' then
        v_expected_tax_code:='PPH_FINAL_4_2'; v_expected_rate_object:='LAND_BUILDING_RENT';
      elsif v_liability.tax_object_code in ('SERVICE','ASSET_RENT_NON_LAND_BUILDING') then
        if upper(v_party.tax_regime)='PPH_FINAL_UMKM' then
          if not private.is_pph_final_umkm_evidence_valid(
            v_party.tax_regime,v_party.taxpayer_type,v_party.turnover_eligibility,
            v_party.certificate_status,v_party.legal_basis,new.business_date
          ) then raise exception 'vendor_final_tax_evidence_invalid' using errcode='23514'; end if;
          v_expected_tax_code:='PPH_FINAL_UMKM'; v_expected_rate_object:='TURNOVER';
        else
          v_expected_tax_code:='PPH23'; v_expected_rate_object:=v_liability.tax_object_code;
        end if;
      else
        raise exception 'unsupported_source_liability_tax_object' using errcode='23514';
      end if;
      v_expected_tax:=private.resolve_tax_rate_snapshot(v_expected_tax_code,v_expected_rate_object,new.business_date,'DEFAULT');
      v_expected_withholding:=round(v_liability.withholding_base_remaining::numeric*(v_expected_tax->>'effective_rate')::numeric)::bigint;
      if v_withholding<>v_expected_withholding then
        raise exception 'supplier_payment_withholding_does_not_match_source_tax_rule' using errcode='23514';
      end if;
    end if;

    update public.supplier_liabilities
      set remaining_amount=remaining_amount-v_ap_delta,
          withholding_base_remaining=case when tax_object_code='NONE' then withholding_base_remaining else 0 end,
          updated_at=now()
    where tenant_id=new.tenant_id and purchase_transaction_ref=v_source_ref;

    insert into public.supplier_payment_allocations(
      tenant_id,payment_transaction_ref,purchase_transaction_ref,vendor_party_id,
      gross_applied,cash_paid,withholding_amount,payment_journal_id,business_date,
      actor_user_id,device_id,reason
    ) values(
      new.tenant_id,new.transaction_ref,v_source_ref,v_liability.vendor_party_id,
      v_ap_delta,v_ap_delta-v_withholding,v_withholding,new.journal_id,new.business_date,
      new.actor_user_id,new.device_id,new.reason
    );
  end if;
  return new;
end;
$$;
revoke all on function private.enforce_supplier_liability_evidence()
  from public,anon,authenticated,service_role;

alter table public.accounting_transaction_evidence
  drop constraint accounting_transaction_evidence_transaction_type_check;
alter table public.accounting_transaction_evidence
  add constraint accounting_transaction_evidence_transaction_type_check
  check (transaction_type = any (array[
    'JUAL_TUNAI'::text,'JUAL_QRIS'::text,'JUAL_TRANSFER'::text,'JUAL_KREDIT'::text,
    'BELI_KREDIT'::text,'BEBAN_VENDOR_KREDIT'::text,'BAYAR_VENDOR'::text,'TERIMA_PIUTANG'::text,
    'RETUR_PENJUALAN'::text,'STOCK_OPNAME'::text
  ]));

do $patch$
declare v_def text; v_old text;
begin
  v_def:=pg_get_functiondef('public.create_auto_journal(uuid,text,text,date,jsonb,text,text,text)'::regprocedure);
  v_old:=v_def;
  v_def:=replace(v_def,
    $a$if v_type not in ('JUAL_TUNAI','JUAL_QRIS','JUAL_TRANSFER','JUAL_KREDIT','BELI_KREDIT','BAYAR_VENDOR','TERIMA_PIUTANG','RETUR_PENJUALAN','STOCK_OPNAME') then$a$,
    $a$if v_type not in ('JUAL_TUNAI','JUAL_QRIS','JUAL_TRANSFER','JUAL_KREDIT','BELI_KREDIT','BEBAN_VENDOR_KREDIT','BAYAR_VENDOR','TERIMA_PIUTANG','RETUR_PENJUALAN','STOCK_OPNAME') then$a$);
  if v_def=v_old then raise exception 'vendor_expense_whitelist_patch_anchor_missing'; end if;

  v_old:=v_def;
  v_def:=replace(v_def,
    $a$    when 'BELI_KREDIT' then if nullif(btrim(coalesce(p_facts->>'supplier_id','')),'') is null then raise exception 'supplier_required_for_credit_purchase' using errcode='22023'; end if; v_source:='purchase_receipt'; v_build:=private.build_purchase_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_actor,p_device_id,p_reason);$a$,
    $a$    when 'BELI_KREDIT' then if nullif(btrim(coalesce(p_facts->>'supplier_id','')),'') is null then raise exception 'supplier_required_for_credit_purchase' using errcode='22023'; end if; v_source:='purchase_receipt'; v_build:=private.build_purchase_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_actor,p_device_id,p_reason);
    when 'BEBAN_VENDOR_KREDIT' then if nullif(btrim(coalesce(p_facts->>'supplier_id','')),'') is null then raise exception 'supplier_required_for_vendor_expense' using errcode='22023'; end if; v_source:='purchase_receipt'; v_build:=private.build_vendor_expense_accrual_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_actor,p_device_id,p_reason);$a$);
  if v_def=v_old then raise exception 'vendor_expense_case_patch_anchor_missing'; end if;

  v_old:=v_def;
  v_def:=replace(v_def,
    $a$  elsif v_type='BELI_KREDIT' then$a$,
    $a$  elsif v_type in ('BELI_KREDIT','BEBAN_VENDOR_KREDIT') then$a$);
  if v_def=v_old then raise exception 'vendor_expense_input_vat_link_patch_anchor_missing'; end if;
  execute v_def;

  v_def:=pg_get_functiondef('private.guard_domain_journal_reversal()'::regprocedure);
  v_old:=v_def;
  v_def:=replace(v_def,
    $a$'BELI_KREDIT','BAYAR_VENDOR','TERIMA_PIUTANG','RETUR_PENJUALAN','STOCK_OPNAME'$a$,
    $a$'BELI_KREDIT','BEBAN_VENDOR_KREDIT','BAYAR_VENDOR','TERIMA_PIUTANG','RETUR_PENJUALAN','STOCK_OPNAME'$a$);
  if v_def=v_old then raise exception 'vendor_expense_reversal_guard_patch_anchor_missing'; end if;
  execute v_def;
end;
$patch$;

create table public.employee_tax_profiles (
  tenant_id uuid not null references public.accounting_tenants(tenant_id),
  profile_id uuid not null default extensions.gen_random_uuid(),
  employee_party_id uuid not null,
  employment_type text not null default 'PERMANENT' check (employment_type='PERMANENT'),
  marital_status text not null check (marital_status in ('TK','K')),
  dependents integer not null check (dependents between 0 and 3),
  ptkp_status text not null,
  ptkp_amount bigint not null check (ptkp_amount>0),
  ter_category text not null check (ter_category in ('A','B','C')),
  tax_method text not null check (tax_method in ('EMPLOYEE_BORNE','GROSS_UP')),
  valid_from date not null,
  valid_to date,
  legal_basis text not null check (length(btrim(legal_basis))>=3),
  actor_user_id uuid not null references auth.users(id),
  device_id text not null check (length(btrim(device_id))>=1),
  reason text not null check (length(btrim(reason))>=3),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (tenant_id,profile_id),
  foreign key (tenant_id,employee_party_id) references public.tax_parties(tenant_id,party_id),
  check (valid_to is null or valid_to>=valid_from)
);

alter table public.employee_tax_profiles enable row level security;
revoke all on public.employee_tax_profiles from public,anon,authenticated,service_role;

create or replace function private.pph21_ptkp_amount(
  p_marital_status text,
  p_dependents integer
) returns bigint
language plpgsql
immutable
set search_path=''
as $$
declare v_status text:=upper(btrim(coalesce(p_marital_status,'')));
begin
  if v_status not in ('TK','K') or p_dependents is null or p_dependents<0 or p_dependents>3 then
    raise exception 'invalid_ptkp_status' using errcode='22023';
  end if;
  return 54000000
    + case when v_status='K' then 4500000 else 0 end
    + (p_dependents::bigint*4500000);
end;
$$;

create or replace function private.pph21_ptkp_status(
  p_marital_status text,
  p_dependents integer
) returns text
language plpgsql
immutable
set search_path=''
as $$
declare v_status text:=upper(btrim(coalesce(p_marital_status,'')));
begin
  if v_status not in ('TK','K') or p_dependents is null or p_dependents<0 or p_dependents>3 then
    raise exception 'invalid_ptkp_status' using errcode='22023';
  end if;
  return v_status||'/'||p_dependents::text;
end;
$$;

create or replace function private.pph21_article17_tax(p_taxable_income bigint)
returns bigint
language plpgsql
immutable
set search_path=''
as $$
declare
  v_remaining bigint:=greatest(coalesce(p_taxable_income,0),0);
  v_tax numeric:=0;
begin
  v_tax:=v_tax+least(v_remaining,60000000)::numeric*0.05;
  v_remaining:=greatest(v_remaining-60000000,0);
  v_tax:=v_tax+least(v_remaining,190000000)::numeric*0.15;
  v_remaining:=greatest(v_remaining-190000000,0);
  v_tax:=v_tax+least(v_remaining,250000000)::numeric*0.25;
  v_remaining:=greatest(v_remaining-250000000,0);
  v_tax:=v_tax+least(v_remaining,4500000000)::numeric*0.30;
  v_remaining:=greatest(v_remaining-4500000000,0);
  v_tax:=v_tax+v_remaining::numeric*0.35;
  return round(v_tax)::bigint;
end;
$$;

create or replace function private.guard_employee_tax_profile()
returns trigger
language plpgsql
security definer
set search_path=''
as $$
declare
  v_expected_category text;
  v_expected_ptkp bigint;
  v_expected_status text;
  v_effective_date date;
begin
  if tg_op='DELETE' then
    raise exception 'employee tax profile history is immutable; close with valid_to' using errcode='55000';
  end if;

  v_expected_category:=private.resolve_ter_category(new.marital_status,new.dependents);
  v_expected_ptkp:=private.pph21_ptkp_amount(new.marital_status,new.dependents);
  v_expected_status:=private.pph21_ptkp_status(new.marital_status,new.dependents);
  new.ter_category:=v_expected_category;
  new.ptkp_amount:=v_expected_ptkp;
  new.ptkp_status:=v_expected_status;
  new.updated_at:=now();

  if new.valid_to is not null and new.valid_to<new.valid_from then
    raise exception 'employee_tax_profile_invalid_period' using errcode='22023';
  end if;
  if not exists(
    select 1 from public.tax_parties tp
    where tp.tenant_id=new.tenant_id
      and tp.party_id=new.employee_party_id
      and tp.party_kind='EMPLOYEE'
      and tp.valid_from<=new.valid_from
      and (tp.valid_to is null or tp.valid_to>=coalesce(new.valid_to,new.valid_from))
  ) then
    raise exception 'employee_tax_party_evidence_not_effective_for_profile_period' using errcode='23514';
  end if;

  if tg_op='UPDATE' then
    if old.tenant_id is distinct from new.tenant_id
       or old.profile_id is distinct from new.profile_id
       or old.employee_party_id is distinct from new.employee_party_id
       or old.employment_type is distinct from new.employment_type
       or old.marital_status is distinct from new.marital_status
       or old.dependents is distinct from new.dependents
       or old.tax_method is distinct from new.tax_method
       or old.valid_from is distinct from new.valid_from
       or old.legal_basis is distinct from new.legal_basis
       or old.actor_user_id is distinct from new.actor_user_id
       or old.device_id is distinct from new.device_id
       or old.reason is distinct from new.reason
       or old.created_at is distinct from new.created_at then
      raise exception 'employee tax profile economics are immutable; close and insert a new version' using errcode='55000';
    end if;
    if old.valid_to is not null and new.valid_to is distinct from old.valid_to then
      raise exception 'closed employee tax profile is immutable' using errcode='55000';
    end if;
    if new.valid_to is not null and new.valid_to<current_date then
      raise exception 'employee tax profile cannot be closed retroactively' using errcode='23514';
    end if;
  end if;

  v_effective_date:=new.valid_from;
  if exists(
    select 1 from public.employee_tax_profiles p
    where p.tenant_id=new.tenant_id
      and p.employee_party_id=new.employee_party_id
      and (tg_op='INSERT' or p.profile_id<>new.profile_id)
      and daterange(p.valid_from,coalesce(p.valid_to+1,'infinity'::date),'[)')
          && daterange(new.valid_from,coalesce(new.valid_to+1,'infinity'::date),'[)')
  ) then
    raise exception 'employee_tax_profile_period_overlap' using errcode='23P01';
  end if;
  return new;
end;
$$;

revoke all on function private.guard_employee_tax_profile() from public,anon,authenticated,service_role;
create trigger employee_tax_profiles_guard
before insert or update or delete on public.employee_tax_profiles
for each row execute function private.guard_employee_tax_profile();

create or replace function public.create_employee_tax_profile(
  p_tenant_id uuid,
  p_employee_party_id uuid,
  p_marital_status text,
  p_dependents integer,
  p_tax_method text,
  p_valid_from date,
  p_valid_to date,
  p_legal_basis text,
  p_device_id text,
  p_app_version text,
  p_reason text
) returns uuid
language plpgsql
security definer
set search_path=''
as $$
declare
  v_actor uuid:=auth.uid();
  v_id uuid;
  v_method text:=upper(btrim(coalesce(p_tax_method,'')));
begin
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  perform accounting_private.require_member_role(p_tenant_id,v_actor,array['owner','admin','accountant']);
  if p_employee_party_id is null or p_valid_from is null then
    raise exception 'employee_profile_identity_and_valid_from_required' using errcode='22023';
  end if;
  if v_method not in ('EMPLOYEE_BORNE','GROSS_UP') then
    raise exception 'invalid_pph21_tax_method' using errcode='22023';
  end if;
  if p_legal_basis is null or length(btrim(p_legal_basis))<3 then
    raise exception 'employee_tax_profile_legal_basis_required' using errcode='22023';
  end if;
  if p_reason is null or length(btrim(p_reason))<3 then
    raise exception 'audit_reason_required' using errcode='22023';
  end if;

  insert into public.employee_tax_profiles(
    tenant_id,employee_party_id,employment_type,marital_status,dependents,
    ptkp_status,ptkp_amount,ter_category,tax_method,valid_from,valid_to,legal_basis,
    actor_user_id,device_id,reason
  ) values(
    p_tenant_id,p_employee_party_id,'PERMANENT',upper(btrim(p_marital_status)),p_dependents,
    private.pph21_ptkp_status(p_marital_status,p_dependents),
    private.pph21_ptkp_amount(p_marital_status,p_dependents),
    private.resolve_ter_category(p_marital_status,p_dependents),
    v_method,p_valid_from,p_valid_to,btrim(p_legal_basis),
    v_actor,btrim(p_device_id),btrim(p_reason)
  ) returning profile_id into v_id;

  insert into private.audit_logs(tenant_id,actor_id,device_id,source,reason,action)
  values(p_tenant_id::text,v_actor,btrim(p_device_id),'employee_tax_profile:'||v_id::text,btrim(p_reason),'create');
  return v_id;
end;
$$;

create or replace function public.close_employee_tax_profile(
  p_tenant_id uuid,
  p_profile_id uuid,
  p_valid_to date,
  p_device_id text,
  p_app_version text,
  p_reason text
) returns void
language plpgsql
security definer
set search_path=''
as $$
declare v_actor uuid:=auth.uid();
begin
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  perform accounting_private.require_member_role(p_tenant_id,v_actor,array['owner','admin','accountant']);
  if p_valid_to is null or p_valid_to<current_date then
    raise exception 'valid_to_must_be_today_or_future' using errcode='22023';
  end if;
  if p_reason is null or length(btrim(p_reason))<3 then
    raise exception 'audit_reason_required' using errcode='22023';
  end if;
  update public.employee_tax_profiles
    set valid_to=p_valid_to
  where tenant_id=p_tenant_id and profile_id=p_profile_id and valid_to is null;
  if not found then raise exception 'open_employee_tax_profile_not_found' using errcode='P0002'; end if;
  insert into private.audit_logs(tenant_id,actor_id,device_id,source,reason,action)
  values(p_tenant_id::text,v_actor,btrim(p_device_id),'employee_tax_profile:'||p_profile_id::text,btrim(p_reason),'close');
end;
$$;

