create table public.payroll_tax_evidence (
  tenant_id uuid not null references public.accounting_tenants(tenant_id),
  payroll_ref text not null check (length(btrim(payroll_ref))>=1),
  employee_party_id uuid not null,
  profile_id uuid not null,
  payroll_month date not null,
  business_date date not null,
  is_final_period boolean not null,
  tax_method text not null check (tax_method in ('EMPLOYEE_BORNE','GROSS_UP')),
  ptkp_status text not null,
  ptkp_amount bigint not null check (ptkp_amount>0),
  ter_category text not null check (ter_category in ('A','B','C')),
  cash_compensation bigint not null check (cash_compensation>0),
  tax_allowance bigint not null check (tax_allowance>=0),
  taxable_gross bigint not null check (taxable_gross>0),
  employee_pension_contribution bigint not null check (employee_pension_contribution>=0),
  mandatory_religious_contribution bigint not null check (mandatory_religious_contribution>=0),
  job_expense_deduction bigint not null check (job_expense_deduction>=0),
  ytd_taxable_gross bigint not null check (ytd_taxable_gross>=0),
  ytd_job_expense bigint not null check (ytd_job_expense>=0),
  ytd_pension_contribution bigint not null check (ytd_pension_contribution>=0),
  ytd_religious_contribution bigint not null check (ytd_religious_contribution>=0),
  annual_taxable_income bigint not null check (annual_taxable_income>=0),
  annual_pph21 bigint not null check (annual_pph21>=0),
  prior_withholding bigint not null check (prior_withholding>=0),
  withholding_adjustment bigint not null,
  salary_payable_amount bigint not null check (salary_payable_amount>0),
  rule_snapshot jsonb not null check (jsonb_typeof(rule_snapshot)='object'),
  journal_id uuid not null references public.accounting_journals(journal_id),
  actor_user_id uuid not null references auth.users(id),
  device_id text not null check (length(btrim(device_id))>=1),
  reason text not null check (length(btrim(reason))>=3),
  created_at timestamptz not null default now(),
  primary key (tenant_id,payroll_ref),
  unique (tenant_id,employee_party_id,payroll_month),
  foreign key (tenant_id,employee_party_id) references public.tax_parties(tenant_id,party_id),
  foreign key (tenant_id,profile_id) references public.employee_tax_profiles(tenant_id,profile_id)
);

create table public.employee_payables (
