create or replace function private.pph21_periodic_calc(
  p_category text,
  p_cash_compensation bigint,
  p_tax_method text,
  p_business_date date
) returns jsonb
language plpgsql
stable
security definer
set search_path=''
as $$
declare
  v_method text:=upper(btrim(coalesce(p_tax_method,'')));
  v_allowance bigint:=0;
  v_new_allowance bigint:=0;
  v_gross bigint;
  v_tax bigint;
  v_rule jsonb;
  v_i integer;
begin
  if p_cash_compensation is null or p_cash_compensation<=0 or p_business_date is null then
    raise exception 'invalid_periodic_payroll_input' using errcode='22023';
  end if;
  if v_method='EMPLOYEE_BORNE' then
    v_gross:=p_cash_compensation;
    v_rule:=private.resolve_pph21_ter(p_category,v_gross,p_business_date);
    v_tax:=round(v_gross::numeric*(v_rule->>'rate')::numeric)::bigint;
    return jsonb_build_object(
      'taxable_gross',v_gross,'tax_allowance',0,'withholding_adjustment',v_tax,
      'rule',v_rule,'method','TER_PERIODIC_EMPLOYEE_BORNE'
    );
  elsif v_method<>'GROSS_UP' then
    raise exception 'invalid_pph21_tax_method' using errcode='22023';
  end if;

  for v_i in 1..100 loop
    if p_cash_compensation::numeric+v_allowance::numeric>9223372036854775807::numeric then
      raise exception 'payroll_value_out_of_range' using errcode='22003';
    end if;
    v_gross:=p_cash_compensation+v_allowance;
    v_rule:=private.resolve_pph21_ter(p_category,v_gross,p_business_date);
    v_new_allowance:=round(v_gross::numeric*(v_rule->>'rate')::numeric)::bigint;
    if v_new_allowance=v_allowance then
      return jsonb_build_object(
        'taxable_gross',v_gross,'tax_allowance',v_allowance,'withholding_adjustment',v_allowance,
        'rule',v_rule,'method','TER_PERIODIC_GROSS_UP','iterations',v_i
      );
    end if;
    v_allowance:=v_new_allowance;
  end loop;
  raise exception 'pph21_gross_up_did_not_converge' using errcode='23514';
end;
$$;
revoke all on function private.pph21_periodic_calc(text,bigint,text,date) from public,anon,authenticated,service_role;

create or replace function private.build_payroll_lines(
  p_tenant_id uuid,
  p_business_date date,
  p_facts jsonb,
  p_actor uuid,
  p_device_id text,
  p_reason text
) returns jsonb
language plpgsql
stable
security definer
set search_path=''
as $$
declare
  v_employee uuid;
  v_profile public.employee_tax_profiles%rowtype;
  v_profile_count bigint;
  v_month date:=date_trunc('month',p_business_date)::date;
  v_year integer:=extract(year from p_business_date)::integer;
  v_cash bigint;
  v_pension bigint:=0;
  v_religious bigint:=0;
  v_is_final boolean;
  v_calc jsonb;
  v_rule jsonb;
  v_allowance bigint:=0;
  v_gross bigint;
  v_job bigint;
  v_ytd_gross bigint:=0;
  v_ytd_job bigint:=0;
  v_ytd_pension bigint:=0;
  v_ytd_religious bigint:=0;
  v_prior bigint:=0;
  v_annual_taxable bigint:=0;
  v_annual_tax bigint:=0;
  v_adjustment bigint:=0;
  v_salary_payable bigint;
  v_i integer;
  v_new_allowance bigint;
  v_journal jsonb:='[]'::jsonb;
  v_snapshot jsonb;
begin
  perform private.assert_no_accounting_fields(p_facts);
  if p_business_date is null then raise exception 'business_date_required' using errcode='22023'; end if;
  begin v_employee:=(p_facts->>'employee_party_id')::uuid;
  exception when others then raise exception 'employee_party_id_required' using errcode='22023'; end;
  if coalesce(p_facts->>'cash_compensation','') !~ '^[1-9][0-9]*$' then
    raise exception 'cash_compensation_required' using errcode='22023';
  end if;
  v_cash:=(p_facts->>'cash_compensation')::bigint;
  if p_facts ? 'employee_pension_contribution' then
    if coalesce(p_facts->>'employee_pension_contribution','') !~ '^(0|[1-9][0-9]*)$' then
      raise exception 'invalid_employee_pension_contribution' using errcode='22023';
    end if;
    v_pension:=(p_facts->>'employee_pension_contribution')::bigint;
  end if;
  if p_facts ? 'mandatory_religious_contribution' then
    if coalesce(p_facts->>'mandatory_religious_contribution','') !~ '^(0|[1-9][0-9]*)$' then
      raise exception 'invalid_mandatory_religious_contribution' using errcode='22023';
    end if;
    v_religious:=(p_facts->>'mandatory_religious_contribution')::bigint;
  end if;
  if v_pension+v_religious>v_cash then
    raise exception 'employee_deductions_exceed_cash_compensation' using errcode='23514';
  end if;

  if not exists(
    select 1 from public.tax_parties tp
    where tp.tenant_id=p_tenant_id and tp.party_id=v_employee and tp.party_kind='EMPLOYEE'
      and tp.valid_from<=p_business_date and (tp.valid_to is null or tp.valid_to>=p_business_date)
  ) then raise exception 'effective_employee_tax_party_required' using errcode='23514'; end if;

  select count(*) into v_profile_count
  from public.employee_tax_profiles p
  where p.tenant_id=p_tenant_id and p.employee_party_id=v_employee
    and p.valid_from<=p_business_date and (p.valid_to is null or p.valid_to>=p_business_date);
  if v_profile_count<>1 then raise exception 'exactly_one_effective_employee_tax_profile_required' using errcode='23514'; end if;
  select * into strict v_profile
  from public.employee_tax_profiles p
  where p.tenant_id=p_tenant_id and p.employee_party_id=v_employee
    and p.valid_from<=p_business_date and (p.valid_to is null or p.valid_to>=p_business_date);

  if exists(
    select 1 from public.payroll_tax_evidence e
    where e.tenant_id=p_tenant_id and e.employee_party_id=v_employee and e.payroll_month=v_month
  ) then raise exception 'employee_payroll_month_already_posted' using errcode='23505'; end if;

  v_is_final := extract(month from p_business_date)=12
    or (v_profile.valid_to is not null and date_trunc('month',v_profile.valid_to)::date=v_month);

  if exists(
    select 1 from public.payroll_tax_evidence e
    where e.tenant_id=p_tenant_id and e.employee_party_id=v_employee
      and extract(year from e.payroll_month)=v_year and e.is_final_period
  ) then raise exception 'employee_tax_year_already_finalized' using errcode='23514'; end if;
  if v_is_final and exists(
    select 1 from public.payroll_tax_evidence e
    where e.tenant_id=p_tenant_id and e.employee_party_id=v_employee
      and extract(year from e.payroll_month)=v_year and e.payroll_month>v_month
  ) then raise exception 'final_period_cannot_precede_existing_payroll_month' using errcode='23514'; end if;

  select
    coalesce(sum(e.taxable_gross),0)::bigint,
    coalesce(sum(e.job_expense_deduction),0)::bigint,
    coalesce(sum(e.employee_pension_contribution),0)::bigint,
    coalesce(sum(e.mandatory_religious_contribution),0)::bigint,
    coalesce(sum(greatest(e.withholding_adjustment,0)),0)::bigint
  into v_ytd_gross,v_ytd_job,v_ytd_pension,v_ytd_religious,v_prior
  from public.payroll_tax_evidence e
  where e.tenant_id=p_tenant_id and e.employee_party_id=v_employee
    and extract(year from e.payroll_month)=v_year and e.payroll_month<v_month;

  if not v_is_final then
    v_calc:=private.pph21_periodic_calc(v_profile.ter_category,v_cash,v_profile.tax_method,p_business_date);
    v_gross:=(v_calc->>'taxable_gross')::bigint;
    v_allowance:=(v_calc->>'tax_allowance')::bigint;
    v_adjustment:=(v_calc->>'withholding_adjustment')::bigint;
    v_rule:=v_calc->'rule';
    v_job:=least(round(v_gross::numeric*0.05)::bigint,500000);
    v_ytd_gross:=v_ytd_gross+v_gross;
    v_ytd_job:=v_ytd_job+v_job;
    v_ytd_pension:=v_ytd_pension+v_pension;
    v_ytd_religious:=v_ytd_religious+v_religious;
  else
    if v_profile.tax_method='EMPLOYEE_BORNE' then
      v_gross:=v_cash;
      v_job:=least(round(v_gross::numeric*0.05)::bigint,500000);
      v_ytd_gross:=v_ytd_gross+v_gross;
      v_ytd_job:=v_ytd_job+v_job;
      v_ytd_pension:=v_ytd_pension+v_pension;
      v_ytd_religious:=v_ytd_religious+v_religious;
      v_annual_taxable:=greatest(v_ytd_gross-v_ytd_job-v_ytd_pension-v_ytd_religious-v_profile.ptkp_amount,0);
      v_annual_taxable:=(v_annual_taxable/1000)*1000;
      v_annual_tax:=private.pph21_article17_tax(v_annual_taxable);
      v_adjustment:=v_annual_tax-v_prior;
      v_rule:=jsonb_build_object(
        'tax_code','PPH21_FINAL','method','ARTICLE_17_FINAL_PERIOD','legal_basis','PMK 168/2023 jo. PP 58/2023',
        'ptkp_status',v_profile.ptkp_status,'ptkp_amount',v_profile.ptkp_amount,'taxable_income_rounded_down_1000',v_annual_taxable
      );
    else
      v_allowance:=0;
      for v_i in 1..100 loop
        if v_cash::numeric+v_allowance::numeric>9223372036854775807::numeric then
          raise exception 'payroll_value_out_of_range' using errcode='22003';
        end if;
        v_gross:=v_cash+v_allowance;
        v_job:=least(round(v_gross::numeric*0.05)::bigint,500000);
        v_annual_taxable:=greatest(
          (v_ytd_gross+v_gross)-(v_ytd_job+v_job)-(v_ytd_pension+v_pension)-(v_ytd_religious+v_religious)-v_profile.ptkp_amount,
          0
        );
        v_annual_taxable:=(v_annual_taxable/1000)*1000;
        v_annual_tax:=private.pph21_article17_tax(v_annual_taxable);
        v_adjustment:=v_annual_tax-v_prior;
        v_new_allowance:=greatest(v_adjustment,0);
        if v_new_allowance=v_allowance then exit; end if;
        v_allowance:=v_new_allowance;
        if v_i=100 then raise exception 'pph21_final_gross_up_did_not_converge' using errcode='23514'; end if;
      end loop;
      v_gross:=v_cash+v_allowance;
      v_job:=least(round(v_gross::numeric*0.05)::bigint,500000);
      v_ytd_gross:=v_ytd_gross+v_gross;
      v_ytd_job:=v_ytd_job+v_job;
      v_ytd_pension:=v_ytd_pension+v_pension;
      v_ytd_religious:=v_ytd_religious+v_religious;
      v_annual_taxable:=greatest(v_ytd_gross-v_ytd_job-v_ytd_pension-v_ytd_religious-v_profile.ptkp_amount,0);
      v_annual_taxable:=(v_annual_taxable/1000)*1000;
      v_annual_tax:=private.pph21_article17_tax(v_annual_taxable);
      v_adjustment:=v_annual_tax-v_prior;
      v_rule:=jsonb_build_object(
        'tax_code','PPH21_FINAL','method','ARTICLE_17_FINAL_PERIOD_GROSS_UP','legal_basis','PMK 168/2023 jo. PP 58/2023',
        'ptkp_status',v_profile.ptkp_status,'ptkp_amount',v_profile.ptkp_amount,'taxable_income_rounded_down_1000',v_annual_taxable,
        'iterations',v_i
      );
    end if;
  end if;

  if v_adjustment>=0 then
    v_salary_payable:=v_gross-v_adjustment;
  else
    v_salary_payable:=v_gross+abs(v_adjustment);
  end if;
  if v_salary_payable<=0 then raise exception 'invalid_salary_payable_amount' using errcode='23514'; end if;

  v_journal:=v_journal||jsonb_build_array(jsonb_build_object(
    'account_code','6-6010','debit',v_gross,'credit',0,'memo','Beban gaji'
  ));
  if v_adjustment<0 then
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object(
      'account_code','2-2040','debit',abs(v_adjustment),'credit',0,'memo','Pengembalian kelebihan potong PPh 21'
    ));
  end if;
  v_journal:=v_journal||jsonb_build_array(jsonb_build_object(
    'account_code','2-2030','debit',0,'credit',v_salary_payable,'memo','Utang gaji bersih'
  ));
  if v_adjustment>0 then
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object(
      'account_code','2-2040','debit',0,'credit',v_adjustment,'memo','PPh 21 yang harus disetor'
    ));
  end if;

  v_snapshot:=jsonb_build_object(
    'legal_basis','PMK 168/2023 jo. PP 58/2023',
    'profile_id',v_profile.profile_id,
    'employee_party_id',v_employee,
    'payroll_month',v_month,
    'is_final_period',v_is_final,
    'tax_method',v_profile.tax_method,
    'ptkp_status',v_profile.ptkp_status,
    'ptkp_amount',v_profile.ptkp_amount,
    'ter_category',v_profile.ter_category,
    'cash_compensation',v_cash,
    'tax_allowance',v_allowance,
    'taxable_gross',v_gross,
    'employee_pension_contribution',v_pension,
    'mandatory_religious_contribution',v_religious,
    'job_expense_deduction',v_job,
    'ytd_taxable_gross',v_ytd_gross,
    'ytd_job_expense',v_ytd_job,
    'ytd_pension_contribution',v_ytd_pension,
    'ytd_religious_contribution',v_ytd_religious,
    'annual_taxable_income',v_annual_taxable,
    'annual_pph21',v_annual_tax,
    'prior_withholding',v_prior,
    'withholding_adjustment',v_adjustment,
    'salary_payable_amount',v_salary_payable,
    'rule',v_rule
  );

  return jsonb_build_object('journal_lines',v_journal,'tax_snapshot',v_snapshot);
end;
$$;
revoke all on function private.build_payroll_lines(uuid,date,jsonb,uuid,text,text) from public,anon,authenticated,service_role;

create or replace function private.build_salary_payment_lines(
  p_tenant_id uuid,
  p_business_date date,
  p_facts jsonb
) returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  v_payroll_ref text:=nullif(btrim(coalesce(p_facts->>'source_payroll_ref','')),'');
  v_payable public.employee_payables%rowtype;
  v_amount bigint;
  v_method text:=upper(coalesce(p_facts->>'payment_method',''));
  v_payment_account text;
  v_claim_employee uuid;
  v_journal jsonb:='[]'::jsonb;
begin
  perform private.assert_no_accounting_fields(p_facts);
  if p_business_date is null or v_payroll_ref is null then raise exception 'salary_payment_identity_required' using errcode='22023'; end if;
  select * into strict v_payable
  from public.employee_payables p
  where p.tenant_id=p_tenant_id and p.payroll_ref=v_payroll_ref
  for update;
  if p_business_date<v_payable.business_date then raise exception 'salary_payment_before_payroll_date' using errcode='23514'; end if;
  if v_payable.remaining_amount<=0 then raise exception 'salary_already_fully_paid' using errcode='23514'; end if;
  if p_facts ? 'employee_party_id' and nullif(btrim(p_facts->>'employee_party_id'),'') is not null then
    begin v_claim_employee:=(p_facts->>'employee_party_id')::uuid;
    exception when others then raise exception 'invalid_employee_party_id' using errcode='22023'; end;
    if v_claim_employee<>v_payable.employee_party_id then raise exception 'salary_payment_employee_mismatch' using errcode='23514'; end if;
  end if;
  if p_facts ? 'amount' then
    if coalesce(p_facts->>'amount','') !~ '^[1-9][0-9]*$' then raise exception 'salary_payment_amount_invalid' using errcode='22023'; end if;
    v_amount:=(p_facts->>'amount')::bigint;
  else v_amount:=v_payable.remaining_amount; end if;
  if v_amount>v_payable.remaining_amount then raise exception 'salary_payment_exceeds_outstanding' using errcode='23514'; end if;
  if v_method='CASH' then v_payment_account:='1-1010';
  elsif v_method='BANK' then v_payment_account:='1-1030';
  else raise exception 'salary_payment_method_must_be_cash_or_bank' using errcode='22023'; end if;
  v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','2-2030','debit',v_amount,'credit',0,'memo','Pelunasan utang gaji'));
  v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code',v_payment_account,'debit',0,'credit',v_amount,'memo','Pembayaran gaji'));
  return jsonb_build_object(
    'journal_lines',v_journal,
    'source_payroll_ref',v_payroll_ref,
    'employee_party_id',v_payable.employee_party_id,
    'amount',v_amount,
    'tax_snapshot','{}'::jsonb
  );
exception when no_data_found then
  raise exception 'salary_payable_not_found' using errcode='P0002';
end;
$$;
revoke all on function private.build_salary_payment_lines(uuid,date,jsonb) from public,anon,authenticated,service_role;

create or replace function private.enforce_payroll_evidence()
returns trigger
language plpgsql
security definer
set search_path=''
as $$
declare
  v_s jsonb;
  v_employee uuid;
  v_profile uuid;
  v_expense bigint;
  v_salary bigint;
  v_pph bigint;
  v_source text;
  v_payable public.employee_payables%rowtype;
  v_amount bigint;
begin
  if new.transaction_type='GAJI_BULANAN' then
    v_s:=new.tax_snapshot;
    if jsonb_typeof(v_s)<>'object' or nullif(v_s->>'legal_basis','') is null then raise exception 'payroll_tax_snapshot_required' using errcode='23514'; end if;
    v_employee:=(v_s->>'employee_party_id')::uuid;
    v_profile:=(v_s->>'profile_id')::uuid;
    if v_employee is distinct from (new.facts_snapshot->>'employee_party_id')::uuid then raise exception 'payroll_employee_snapshot_mismatch' using errcode='23514'; end if;

    select coalesce(sum(l.debit-l.credit),0)::bigint into v_expense
    from public.accounting_journal_lines l where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code='6-6010';
    select coalesce(sum(l.credit-l.debit),0)::bigint into v_salary
    from public.accounting_journal_lines l where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code='2-2030';
    select coalesce(sum(l.credit-l.debit),0)::bigint into v_pph
    from public.accounting_journal_lines l where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code='2-2040';
    if v_expense<>(v_s->>'taxable_gross')::bigint
       or v_salary<>(v_s->>'salary_payable_amount')::bigint
       or v_pph<>(v_s->>'withholding_adjustment')::bigint then
      raise exception 'payroll_gl_does_not_match_tax_evidence' using errcode='23514';
    end if;

    insert into public.payroll_tax_evidence(
      tenant_id,payroll_ref,employee_party_id,profile_id,payroll_month,business_date,is_final_period,
      tax_method,ptkp_status,ptkp_amount,ter_category,cash_compensation,tax_allowance,taxable_gross,
      employee_pension_contribution,mandatory_religious_contribution,job_expense_deduction,
      ytd_taxable_gross,ytd_job_expense,ytd_pension_contribution,ytd_religious_contribution,
      annual_taxable_income,annual_pph21,prior_withholding,withholding_adjustment,salary_payable_amount,
      rule_snapshot,journal_id,actor_user_id,device_id,reason
    ) values(
      new.tenant_id,new.transaction_ref,v_employee,v_profile,(v_s->>'payroll_month')::date,new.business_date,(v_s->>'is_final_period')::boolean,
      v_s->>'tax_method',v_s->>'ptkp_status',(v_s->>'ptkp_amount')::bigint,v_s->>'ter_category',
      (v_s->>'cash_compensation')::bigint,(v_s->>'tax_allowance')::bigint,(v_s->>'taxable_gross')::bigint,
      (v_s->>'employee_pension_contribution')::bigint,(v_s->>'mandatory_religious_contribution')::bigint,(v_s->>'job_expense_deduction')::bigint,
      (v_s->>'ytd_taxable_gross')::bigint,(v_s->>'ytd_job_expense')::bigint,(v_s->>'ytd_pension_contribution')::bigint,(v_s->>'ytd_religious_contribution')::bigint,
      (v_s->>'annual_taxable_income')::bigint,(v_s->>'annual_pph21')::bigint,(v_s->>'prior_withholding')::bigint,(v_s->>'withholding_adjustment')::bigint,
      (v_s->>'salary_payable_amount')::bigint,v_s->'rule',new.journal_id,new.actor_user_id,new.device_id,new.reason
    );
    insert into public.employee_payables(
      tenant_id,payroll_ref,employee_party_id,business_date,original_amount,remaining_amount,payroll_journal_id,
      actor_user_id,device_id,reason
    ) values(
      new.tenant_id,new.transaction_ref,v_employee,new.business_date,(v_s->>'salary_payable_amount')::bigint,(v_s->>'salary_payable_amount')::bigint,
      new.journal_id,new.actor_user_id,new.device_id,new.reason
    );
  elsif new.transaction_type='BAYAR_GAJI' then
    v_source:=nullif(btrim(coalesce(new.facts_snapshot->>'source_payroll_ref','')),'');
    if v_source is null then raise exception 'source_payroll_ref_required' using errcode='22023'; end if;
    select * into v_payable from public.employee_payables p
    where p.tenant_id=new.tenant_id and p.payroll_ref=v_source for update;
    if not found then raise exception 'salary_payable_not_found' using errcode='P0002'; end if;
    select coalesce(sum(l.debit-l.credit),0)::bigint into v_amount
    from public.accounting_journal_lines l where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code='2-2030';
    if v_amount<=0 or v_amount>v_payable.remaining_amount then raise exception 'salary_payment_gl_mismatch' using errcode='23514'; end if;
    update public.employee_payables set remaining_amount=remaining_amount-v_amount,updated_at=now()
      where tenant_id=new.tenant_id and payroll_ref=v_source;
    insert into public.payroll_payment_allocations(
      tenant_id,payment_transaction_ref,payroll_ref,employee_party_id,amount_applied,payment_journal_id,business_date,
      actor_user_id,device_id,reason
    ) values(
      new.tenant_id,new.transaction_ref,v_source,v_payable.employee_party_id,v_amount,new.journal_id,new.business_date,
      new.actor_user_id,new.device_id,new.reason
    );
  end if;
  return new;
end;
$$;
revoke all on function private.enforce_payroll_evidence() from public,anon,authenticated,service_role;

create trigger accounting_transaction_payroll_guard
after insert on public.accounting_transaction_evidence
for each row
when (new.transaction_type in ('GAJI_BULANAN','BAYAR_GAJI'))
execute function private.enforce_payroll_evidence();

alter table public.accounting_transaction_evidence
  drop constraint accounting_transaction_evidence_transaction_type_check;
alter table public.accounting_transaction_evidence
  add constraint accounting_transaction_evidence_transaction_type_check
  check (transaction_type = any (array[
    'JUAL_TUNAI'::text,'JUAL_QRIS'::text,'JUAL_TRANSFER'::text,'JUAL_KREDIT'::text,
    'BELI_KREDIT'::text,'BEBAN_VENDOR_KREDIT'::text,'BAYAR_VENDOR'::text,'TERIMA_PIUTANG'::text,
    'GAJI_BULANAN'::text,'BAYAR_GAJI'::text,
    'RETUR_PENJUALAN'::text,'STOCK_OPNAME'::text
  ]));

do $patch$
declare v_def text; v_old text;
begin
  v_def:=pg_get_functiondef('public.create_auto_journal(uuid,text,text,date,jsonb,text,text,text)'::regprocedure);
  v_old:=v_def;
  v_def:=replace(v_def,
    $a$if v_type not in ('JUAL_TUNAI','JUAL_QRIS','JUAL_TRANSFER','JUAL_KREDIT','BELI_KREDIT','BEBAN_VENDOR_KREDIT','BAYAR_VENDOR','TERIMA_PIUTANG','RETUR_PENJUALAN','STOCK_OPNAME') then$a$,
    $a$if v_type not in ('JUAL_TUNAI','JUAL_QRIS','JUAL_TRANSFER','JUAL_KREDIT','BELI_KREDIT','BEBAN_VENDOR_KREDIT','BAYAR_VENDOR','TERIMA_PIUTANG','GAJI_BULANAN','BAYAR_GAJI','RETUR_PENJUALAN','STOCK_OPNAME') then$a$);
  if v_def=v_old then raise exception 'payroll_whitelist_patch_anchor_missing'; end if;

  v_old:=v_def;
  v_def:=replace(v_def,
    $a$if v_type in ('RETUR_PENJUALAN','STOCK_OPNAME') and v_member_role='cashier' then$a$,
    $a$if v_type in ('RETUR_PENJUALAN','STOCK_OPNAME','GAJI_BULANAN','BAYAR_GAJI') and v_member_role='cashier' then$a$);
  if v_def=v_old then raise exception 'payroll_role_patch_anchor_missing'; end if;

  v_old:=v_def;
  v_def:=replace(v_def,
    $a$    when 'TERIMA_PIUTANG' then v_source:='ar_receipt'; v_build:=private.build_customer_receipt_lines(p_tenant_id,p_business_date,p_facts);$a$,
    $a$    when 'TERIMA_PIUTANG' then v_source:='ar_receipt'; v_build:=private.build_customer_receipt_lines(p_tenant_id,p_business_date,p_facts);
    when 'GAJI_BULANAN' then v_source:='payroll_accrual'; v_build:=private.build_payroll_lines(p_tenant_id,p_business_date,p_facts,v_actor,p_device_id,p_reason);
    when 'BAYAR_GAJI' then v_source:='payroll_payment'; v_build:=private.build_salary_payment_lines(p_tenant_id,p_business_date,p_facts);$a$);
  if v_def=v_old then raise exception 'payroll_case_patch_anchor_missing'; end if;
  execute v_def;

  v_def:=pg_get_functiondef('private.guard_domain_journal_reversal()'::regprocedure);
  v_old:=v_def;
  v_def:=replace(v_def,
    $a$'BELI_KREDIT','BEBAN_VENDOR_KREDIT','BAYAR_VENDOR','TERIMA_PIUTANG','RETUR_PENJUALAN','STOCK_OPNAME'$a$,
    $a$'BELI_KREDIT','BEBAN_VENDOR_KREDIT','BAYAR_VENDOR','TERIMA_PIUTANG','GAJI_BULANAN','BAYAR_GAJI','RETUR_PENJUALAN','STOCK_OPNAME'$a$);
  if v_def=v_old then raise exception 'payroll_reversal_guard_patch_anchor_missing'; end if;
  execute v_def;

  v_def:=pg_get_functiondef('private.compute_accounting_hard_gate(uuid)'::regprocedure);
  v_old:=v_def;
  v_def:=replace(v_def,
    $a$v_tax_event_lineage bigint;$a$,
    $a$v_tax_event_lineage bigint; v_salary_subledger bigint; v_salary_gl bigint; v_salary_delta bigint; v_salary_negative bigint; v_pph21_payroll bigint; v_pph21_gl bigint; v_pph21_delta bigint;$a$);
  if v_def=v_old then raise exception 'payroll_gate_declaration_anchor_missing'; end if;

  v_old:=v_def;
  v_def:=replace(v_def,
    $a$  select count(*)::bigint into v_tax_gl_mismatch$a$,
    $a$  select coalesce(sum(remaining_amount),0)::bigint, count(*) filter (where remaining_amount<0)::bigint
  into v_salary_subledger,v_salary_negative
  from public.employee_payables where tenant_id=p_tenant_id;
  select coalesce(sum(credit-debit),0)::bigint into v_salary_gl
  from public.accounting_journal_lines where tenant_id=p_tenant_id and account_code='2-2030';
  v_salary_delta:=v_salary_subledger-v_salary_gl;
  select coalesce(sum(withholding_adjustment),0)::bigint into v_pph21_payroll
  from public.payroll_tax_evidence where tenant_id=p_tenant_id;
  select coalesce(sum(credit-debit),0)::bigint into v_pph21_gl
  from public.accounting_journal_lines where tenant_id=p_tenant_id and account_code='2-2040';
  v_pph21_delta:=v_pph21_payroll-v_pph21_gl;

  select count(*)::bigint into v_tax_gl_mismatch$a$);
  if v_def=v_old then raise exception 'payroll_gate_compute_anchor_missing'; end if;

  v_old:=v_def;
  v_def:=replace(v_def,
    $a$'customer_receivable_negative_count',v_customer_negative,$a$,
    $a$'customer_receivable_negative_count',v_customer_negative,
    'salary_payable_subledger_minus_gl_2_2030',v_salary_delta,
    'salary_payable_negative_count',v_salary_negative,
    'payroll_pph21_evidence_minus_gl_2_2040',v_pph21_delta,$a$);
  if v_def=v_old then raise exception 'payroll_gate_output_anchor_missing'; end if;

  v_old:=v_def;
  v_def:=replace(v_def,
    $a$v_tax_gl_mismatch=0 and v_tax_line_mismatch=0 and v_tax_event_lineage=0)$a$,
    $a$v_tax_gl_mismatch=0 and v_tax_line_mismatch=0 and v_tax_event_lineage=0 and v_salary_delta=0 and v_salary_negative=0 and v_pph21_delta=0)$a$);
  if v_def=v_old then raise exception 'payroll_gate_allzero_anchor_missing'; end if;
  execute v_def;
end;
$patch$;

do $patch$
declare v_def text; v_old text;
begin
  v_def:=pg_get_functiondef('public.create_employee_tax_profile(uuid,uuid,text,integer,text,date,date,text,text,text,text)'::regprocedure);
  v_old:=v_def;
  v_def:=replace(v_def,
    $a$values(p_tenant_id::text,v_actor,btrim(p_device_id),'employee_tax_profile:'||v_id::text,btrim(p_reason),'create');$a$,
    $a$values(p_tenant_id::text,v_actor,btrim(p_device_id),'employee_tax_profile:create:'||v_id::text,btrim(p_reason),'success');$a$);
  if v_def=v_old then raise exception 'employee_profile_create_audit_patch_anchor_missing'; end if;
  execute v_def;

  v_def:=pg_get_functiondef('public.close_employee_tax_profile(uuid,uuid,date,text,text,text)'::regprocedure);
  v_old:=v_def;
  v_def:=replace(v_def,
    $a$values(p_tenant_id::text,v_actor,btrim(p_device_id),'employee_tax_profile:'||p_profile_id::text,btrim(p_reason),'close');$a$,
    $a$values(p_tenant_id::text,v_actor,btrim(p_device_id),'employee_tax_profile:close:'||p_profile_id::text,btrim(p_reason),'success');$a$);
  if v_def=v_old then raise exception 'employee_profile_close_audit_patch_anchor_missing'; end if;
  execute v_def;
end;
$patch$;

create table public.fixed_assets (
  tenant_id uuid not null references public.accounting_tenants(tenant_id),
  asset_id uuid not null default extensions.gen_random_uuid(),
  asset_ref text not null check (length(btrim(asset_ref))>=1),
  asset_name text not null check (length(btrim(asset_name))>=1),
  acquisition_date date not null,
  depreciation_start_date date not null,
  cost bigint not null check (cost>0),
  residual_value bigint not null default 0 check (residual_value>=0),
  useful_life_months integer not null check (useful_life_months between 1 and 600),
  depreciation_method text not null default 'STRAIGHT_LINE' check (depreciation_method='STRAIGHT_LINE'),
  accumulated_depreciation bigint not null default 0 check (accumulated_depreciation>=0),
  status text not null default 'ACTIVE' check (status in ('ACTIVE','FULLY_DEPRECIATED')),
  acquisition_journal_id uuid not null references public.accounting_journals(journal_id),
  actor_user_id uuid not null references auth.users(id),
  device_id text not null check (length(btrim(device_id))>=1),
  reason text not null check (length(btrim(reason))>=3),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (tenant_id,asset_id),
  unique (tenant_id,asset_ref),
  check (residual_value<cost),
  check (depreciation_start_date>=acquisition_date),
  check (accumulated_depreciation<=cost-residual_value)
);

create table public.fixed_asset_depreciation_events (
  tenant_id uuid not null references public.accounting_tenants(tenant_id),
  asset_id uuid not null,
  depreciation_month date not null,
  sequence_no integer not null check (sequence_no>=1),
  amount bigint not null check (amount>0),
  accumulated_after bigint not null check (accumulated_after>0),
  journal_id uuid not null references public.accounting_journals(journal_id),
  transaction_ref text not null check (length(btrim(transaction_ref))>=1),
  actor_user_id uuid not null references auth.users(id),
  device_id text not null check (length(btrim(device_id))>=1),
  reason text not null check (length(btrim(reason))>=3),
  created_at timestamptz not null default now(),
  primary key (tenant_id,asset_id,depreciation_month),
  unique (tenant_id,transaction_ref),
  foreign key (tenant_id,asset_id) references public.fixed_assets(tenant_id,asset_id)
);

create table public.receivable_allowances (
  tenant_id uuid not null references public.accounting_tenants(tenant_id),
  sale_transaction_ref text not null,
  customer_ref text not null check (length(btrim(customer_ref))>=1),
  allowance_amount bigint not null check (allowance_amount>=0),
  updated_at timestamptz not null default now(),
  primary key (tenant_id,sale_transaction_ref),
  foreign key (tenant_id,sale_transaction_ref) references public.customer_receivables(tenant_id,sale_transaction_ref)
);

create table public.receivable_allowance_events (
  tenant_id uuid not null references public.accounting_tenants(tenant_id),
  adjustment_transaction_ref text not null check (length(btrim(adjustment_transaction_ref))>=1),
  sale_transaction_ref text not null,
  previous_allowance bigint not null check (previous_allowance>=0),
  target_allowance bigint not null check (target_allowance>=0),
  delta bigint not null,
  journal_id uuid not null references public.accounting_journals(journal_id),
  business_date date not null,
  actor_user_id uuid not null references auth.users(id),
  device_id text not null check (length(btrim(device_id))>=1),
  reason text not null check (length(btrim(reason))>=3),
  created_at timestamptz not null default now(),
  primary key (tenant_id,adjustment_transaction_ref),
  foreign key (tenant_id,sale_transaction_ref) references public.customer_receivables(tenant_id,sale_transaction_ref)
);

alter table public.fixed_assets enable row level security;
alter table public.fixed_asset_depreciation_events enable row level security;
alter table public.receivable_allowances enable row level security;
alter table public.receivable_allowance_events enable row level security;
