create or replace function private.build_bad_debt_allowance_lines(
  p_tenant_id uuid,p_business_date date,p_facts jsonb
) returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  v_source text:=nullif(btrim(coalesce(p_facts->>'source_sale_ref','')),'');
  v_rec public.customer_receivables%rowtype;
  v_target bigint;
  v_current bigint:=0;
  v_delta bigint;
  v_journal jsonb:='[]'::jsonb;
begin
  perform private.assert_no_accounting_fields(p_facts);
  if p_business_date is null or v_source is null then raise exception 'receivable_allowance_source_required' using errcode='22023'; end if;
  if coalesce(p_facts->>'target_allowance','') !~ '^(0|[1-9][0-9]*)$' then raise exception 'target_allowance_required' using errcode='22023'; end if;
  v_target:=(p_facts->>'target_allowance')::bigint;
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':allowance:'||v_source,7335));
  select * into strict v_rec from public.customer_receivables r where r.tenant_id=p_tenant_id and r.sale_transaction_ref=v_source for update;
  if v_target>v_rec.remaining_amount then raise exception 'allowance_cannot_exceed_outstanding_receivable' using errcode='23514'; end if;
  select coalesce(a.allowance_amount,0) into v_current from public.receivable_allowances a where a.tenant_id=p_tenant_id and a.sale_transaction_ref=v_source;
  v_delta:=v_target-v_current;
  if v_delta=0 then raise exception 'receivable_allowance_target_unchanged' using errcode='22023'; end if;
  if v_delta>0 then
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','6-6070','debit',v_delta,'credit',0,'memo','Estimasi piutang tidak tertagih'));
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','1-1080','debit',0,'credit',v_delta,'memo','Cadangan kerugian piutang'));
  else
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','1-1080','debit',abs(v_delta),'credit',0,'memo','Pengurangan cadangan piutang'));
    v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code','6-6070','debit',0,'credit',abs(v_delta),'memo','Pembalikan estimasi piutang'));
  end if;
  return jsonb_build_object('journal_lines',v_journal,'tax_snapshot','{}'::jsonb,'source_sale_ref',v_source,'customer_ref',v_rec.customer_ref,'previous_allowance',v_current,'target_allowance',v_target,'delta',v_delta);
exception when no_data_found then raise exception 'customer_receivable_not_found' using errcode='P0002';
end;
$$;
revoke all on function private.build_bad_debt_allowance_lines(uuid,date,jsonb) from public,anon,authenticated,service_role;

create or replace function private.enforce_owner_adjustment_evidence()
returns trigger
language plpgsql
security definer
set search_path=''
as $$
declare
  v_asset uuid;
  v_a public.fixed_assets%rowtype;
  v_cost bigint;
  v_amount bigint;
  v_accum_credit bigint;
  v_expense bigint;
  v_seq integer;
  v_month date;
  v_expected_month date;
  v_basis bigint;
  v_target bigint;
  v_source text;
  v_rec public.customer_receivables%rowtype;
  v_previous bigint:=0;
  v_target_allowance bigint;
  v_delta bigint;
  v_allowance_gl bigint;
begin
  if new.transaction_type='BELI_ASET_TUNAI' then
    v_cost:=(new.facts_snapshot->>'cost')::bigint;
    select coalesce(sum(l.debit-l.credit),0)::bigint into v_amount from public.accounting_journal_lines l where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code='1-1060';
    if v_amount<>v_cost then raise exception 'fixed_asset_acquisition_gl_mismatch' using errcode='23514'; end if;
    insert into public.fixed_assets(tenant_id,asset_ref,asset_name,acquisition_date,depreciation_start_date,cost,residual_value,useful_life_months,depreciation_method,accumulated_depreciation,status,acquisition_journal_id,actor_user_id,device_id,reason)
    values(new.tenant_id,btrim(new.facts_snapshot->>'asset_ref'),btrim(new.facts_snapshot->>'asset_name'),new.business_date,(new.facts_snapshot->>'depreciation_start_date')::date,v_cost,coalesce((new.facts_snapshot->>'residual_value')::bigint,0),(new.facts_snapshot->>'useful_life_months')::integer,'STRAIGHT_LINE',0,'ACTIVE',new.journal_id,new.actor_user_id,new.device_id,new.reason);
  elsif new.transaction_type='PENYUSUTAN_BULANAN' then
    v_asset:=(new.facts_snapshot->>'asset_id')::uuid;
    select * into strict v_a from public.fixed_assets a where a.tenant_id=new.tenant_id and a.asset_id=v_asset for update;
    select count(*)::integer+1 into v_seq from public.fixed_asset_depreciation_events e where e.tenant_id=new.tenant_id and e.asset_id=v_asset;
    if v_seq>v_a.useful_life_months then raise exception 'fixed_asset_fully_depreciated' using errcode='23514'; end if;
    v_month:=date_trunc('month',new.business_date)::date;
    v_expected_month:=(date_trunc('month',v_a.depreciation_start_date)::date+make_interval(months=>v_seq-1))::date;
    if v_month<>v_expected_month then raise exception 'depreciation_month_must_be_posted_sequentially' using errcode='23514'; end if;
    v_basis:=v_a.cost-v_a.residual_value;
    if v_seq=v_a.useful_life_months then v_target:=v_basis; else v_target:=round(v_basis::numeric*v_seq::numeric/v_a.useful_life_months::numeric)::bigint; end if;
    v_amount:=v_target-v_a.accumulated_depreciation;
    select coalesce(sum(l.debit-l.credit),0)::bigint into v_expense from public.accounting_journal_lines l where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code='6-6060';
    select coalesce(sum(l.credit-l.debit),0)::bigint into v_accum_credit from public.accounting_journal_lines l where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code='1-1070';
    if v_amount<=0 or v_expense<>v_amount or v_accum_credit<>v_amount then raise exception 'depreciation_gl_mismatch' using errcode='23514'; end if;
    insert into public.fixed_asset_depreciation_events(tenant_id,asset_id,depreciation_month,sequence_no,amount,accumulated_after,journal_id,transaction_ref,actor_user_id,device_id,reason)
    values(new.tenant_id,v_asset,v_month,v_seq,v_amount,v_target,new.journal_id,new.transaction_ref,new.actor_user_id,new.device_id,new.reason);
    update public.fixed_assets set accumulated_depreciation=v_target,status=case when v_target=v_basis then 'FULLY_DEPRECIATED' else 'ACTIVE' end,updated_at=now() where tenant_id=new.tenant_id and asset_id=v_asset;
  elsif new.transaction_type='ATUR_CADANGAN_PIUTANG' then
    v_source:=btrim(new.facts_snapshot->>'source_sale_ref');
    select * into strict v_rec from public.customer_receivables r where r.tenant_id=new.tenant_id and r.sale_transaction_ref=v_source for update;
    v_target_allowance:=(new.facts_snapshot->>'target_allowance')::bigint;
    select coalesce(a.allowance_amount,0) into v_previous from public.receivable_allowances a where a.tenant_id=new.tenant_id and a.sale_transaction_ref=v_source;
    v_delta:=v_target_allowance-v_previous;
    if v_target_allowance>v_rec.remaining_amount or v_delta=0 then raise exception 'invalid_receivable_allowance_target' using errcode='23514'; end if;
    select coalesce(sum(l.credit-l.debit),0)::bigint into v_allowance_gl from public.accounting_journal_lines l where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code='1-1080';
    select coalesce(sum(l.debit-l.credit),0)::bigint into v_expense from public.accounting_journal_lines l where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code='6-6070';
    if v_allowance_gl<>v_delta or v_expense<>v_delta then raise exception 'receivable_allowance_gl_mismatch' using errcode='23514'; end if;
    insert into public.receivable_allowances(tenant_id,sale_transaction_ref,customer_ref,allowance_amount) values(new.tenant_id,v_source,v_rec.customer_ref,v_target_allowance)
      on conflict(tenant_id,sale_transaction_ref) do update set allowance_amount=excluded.allowance_amount,updated_at=now();
    insert into public.receivable_allowance_events(tenant_id,adjustment_transaction_ref,sale_transaction_ref,previous_allowance,target_allowance,delta,journal_id,business_date,actor_user_id,device_id,reason)
    values(new.tenant_id,new.transaction_ref,v_source,v_previous,v_target_allowance,v_delta,new.journal_id,new.business_date,new.actor_user_id,new.device_id,new.reason);
  end if;
  return new;
end;
$$;
revoke all on function private.enforce_owner_adjustment_evidence() from public,anon,authenticated,service_role;

create trigger accounting_transaction_owner_adjustment_guard
after insert on public.accounting_transaction_evidence
for each row when (new.transaction_type in ('BELI_ASET_TUNAI','PENYUSUTAN_BULANAN','ATUR_CADANGAN_PIUTANG'))
execute function private.enforce_owner_adjustment_evidence();

alter table public.accounting_transaction_evidence drop constraint accounting_transaction_evidence_transaction_type_check;
alter table public.accounting_transaction_evidence add constraint accounting_transaction_evidence_transaction_type_check check (transaction_type=any(array[
  'JUAL_TUNAI'::text,'JUAL_QRIS'::text,'JUAL_TRANSFER'::text,'JUAL_KREDIT'::text,
  'BELI_KREDIT'::text,'BEBAN_VENDOR_KREDIT'::text,'BAYAR_VENDOR'::text,'TERIMA_PIUTANG'::text,
  'GAJI_BULANAN'::text,'BAYAR_GAJI'::text,
  'BELI_ASET_TUNAI'::text,'PENYUSUTAN_BULANAN'::text,'PRIVE_OWNER'::text,'ATUR_CADANGAN_PIUTANG'::text,
  'RETUR_PENJUALAN'::text,'STOCK_OPNAME'::text
]));

do $patch$
declare v_def text; v_old text;
begin
  v_def:=pg_get_functiondef('public.create_auto_journal(uuid,text,text,date,jsonb,text,text,text)'::regprocedure);
  v_old:=v_def; v_def:=replace(v_def,
    $a$if v_type not in ('JUAL_TUNAI','JUAL_QRIS','JUAL_TRANSFER','JUAL_KREDIT','BELI_KREDIT','BEBAN_VENDOR_KREDIT','BAYAR_VENDOR','TERIMA_PIUTANG','GAJI_BULANAN','BAYAR_GAJI','RETUR_PENJUALAN','STOCK_OPNAME') then$a$,
    $a$if v_type not in ('JUAL_TUNAI','JUAL_QRIS','JUAL_TRANSFER','JUAL_KREDIT','BELI_KREDIT','BEBAN_VENDOR_KREDIT','BAYAR_VENDOR','TERIMA_PIUTANG','GAJI_BULANAN','BAYAR_GAJI','BELI_ASET_TUNAI','PENYUSUTAN_BULANAN','PRIVE_OWNER','ATUR_CADANGAN_PIUTANG','RETUR_PENJUALAN','STOCK_OPNAME') then$a$);
  if v_def=v_old then raise exception 'owner_adjustment_whitelist_anchor_missing'; end if;
  v_old:=v_def; v_def:=replace(v_def,
    $a$if v_type in ('RETUR_PENJUALAN','STOCK_OPNAME','GAJI_BULANAN','BAYAR_GAJI') and v_member_role='cashier' then$a$,
    $a$if v_type in ('RETUR_PENJUALAN','STOCK_OPNAME','GAJI_BULANAN','BAYAR_GAJI','BELI_ASET_TUNAI','PENYUSUTAN_BULANAN','PRIVE_OWNER','ATUR_CADANGAN_PIUTANG') and v_member_role='cashier' then$a$);
  if v_def=v_old then raise exception 'owner_adjustment_role_anchor_missing'; end if;
  v_old:=v_def; v_def:=replace(v_def,
    $a$  perform private.assert_no_accounting_fields(p_facts);$a$,
    $a$  if v_type='PRIVE_OWNER' and v_member_role<>'owner' then raise exception 'owner_draw_requires_owner_role' using errcode='42501'; end if;
  perform private.assert_no_accounting_fields(p_facts);$a$);
  if v_def=v_old then raise exception 'owner_draw_owner_only_anchor_missing'; end if;
  v_old:=v_def; v_def:=replace(v_def,
    $a$    when 'BAYAR_GAJI' then v_source:='payroll_payment'; v_build:=private.build_salary_payment_lines(p_tenant_id,p_business_date,p_facts);$a$,
    $a$    when 'BAYAR_GAJI' then v_source:='payroll_payment'; v_build:=private.build_salary_payment_lines(p_tenant_id,p_business_date,p_facts);
    when 'BELI_ASET_TUNAI' then v_source:='fixed_asset_acquisition'; v_build:=private.build_fixed_asset_acquisition_lines(p_tenant_id,p_business_date,p_facts);
    when 'PENYUSUTAN_BULANAN' then v_source:='fixed_asset_depreciation'; v_build:=private.build_depreciation_lines(p_tenant_id,p_business_date,p_facts);
    when 'PRIVE_OWNER' then v_source:='manual'; v_build:=private.build_owner_draw_lines(p_tenant_id,p_business_date,p_facts);
    when 'ATUR_CADANGAN_PIUTANG' then v_source:='manual'; v_build:=private.build_bad_debt_allowance_lines(p_tenant_id,p_business_date,p_facts);$a$);
  if v_def=v_old then raise exception 'owner_adjustment_case_anchor_missing'; end if;
  execute v_def;

  v_def:=pg_get_functiondef('private.guard_domain_journal_reversal()'::regprocedure); v_old:=v_def;
  v_def:=replace(v_def,
    $a$'BELI_KREDIT','BEBAN_VENDOR_KREDIT','BAYAR_VENDOR','TERIMA_PIUTANG','GAJI_BULANAN','BAYAR_GAJI','RETUR_PENJUALAN','STOCK_OPNAME'$a$,
    $a$'BELI_KREDIT','BEBAN_VENDOR_KREDIT','BAYAR_VENDOR','TERIMA_PIUTANG','GAJI_BULANAN','BAYAR_GAJI','BELI_ASET_TUNAI','PENYUSUTAN_BULANAN','PRIVE_OWNER','ATUR_CADANGAN_PIUTANG','RETUR_PENJUALAN','STOCK_OPNAME'$a$);
  if v_def=v_old then raise exception 'owner_adjustment_reversal_anchor_missing'; end if; execute v_def;
end;
$patch$;

do $patch2$
declare v_def text; v_old text;
begin
  v_def:=pg_get_functiondef('private.enforce_customer_receivable_evidence()'::regprocedure);
  v_old:=v_def; v_def:=replace(v_def,
    $a$    if v_rec.remaining_amount<v_amount then raise exception 'customer_receipt_exceeds_outstanding_receivable' using errcode='23514'; end if;$a$,
    $a$    if v_rec.remaining_amount<v_amount then raise exception 'customer_receipt_exceeds_outstanding_receivable' using errcode='23514'; end if;
    if v_rec.remaining_amount-v_amount < coalesce((select a.allowance_amount from public.receivable_allowances a where a.tenant_id=new.tenant_id and a.sale_transaction_ref=v_source),0) then raise exception 'receivable_collection_requires_allowance_reduction' using errcode='23514'; end if;$a$);
  if v_def=v_old then raise exception 'allowance_collection_guard_anchor_missing'; end if;
  v_old:=v_def; v_def:=replace(v_def,
    $a$      if v_rec.remaining_amount<v_ar_delta then
        raise exception 'credit_sale_return_exceeds_open_receivable_requires_refund_flow' using errcode='23514';
      end if;$a$,
    $a$      if v_rec.remaining_amount<v_ar_delta then
        raise exception 'credit_sale_return_exceeds_open_receivable_requires_refund_flow' using errcode='23514';
      end if;
      if v_rec.remaining_amount-v_ar_delta < coalesce((select a.allowance_amount from public.receivable_allowances a where a.tenant_id=new.tenant_id and a.sale_transaction_ref=v_source),0) then
        raise exception 'credit_sale_return_requires_allowance_reduction' using errcode='23514';
      end if;$a$);
  if v_def=v_old then raise exception 'allowance_return_guard_anchor_missing'; end if;
  execute v_def;
end;
$patch2$;

do $gate$
declare v_def text; v_old text;
begin
  v_def:=pg_get_functiondef('private.compute_accounting_hard_gate(uuid)'::regprocedure);
  v_old:=v_def; v_def:=replace(v_def,
    $a$v_pph21_delta bigint;$a$,
    $a$v_pph21_delta bigint; v_asset_cost_subledger bigint; v_asset_cost_gl bigint; v_asset_cost_delta bigint; v_asset_accum_subledger bigint; v_asset_accum_gl bigint; v_asset_accum_delta bigint; v_asset_invalid bigint; v_allowance_subledger bigint; v_allowance_gl bigint; v_allowance_delta bigint; v_allowance_exceeds bigint;$a$);
  if v_def=v_old then raise exception 'owner_gate_declaration_anchor_missing'; end if;
  v_old:=v_def; v_def:=replace(v_def,
    $a$  select count(*)::bigint into v_tax_gl_mismatch$a$,
    $a$  select coalesce(sum(cost),0)::bigint,coalesce(sum(accumulated_depreciation),0)::bigint,count(*) filter(where accumulated_depreciation<0 or accumulated_depreciation>cost-residual_value)::bigint into v_asset_cost_subledger,v_asset_accum_subledger,v_asset_invalid from public.fixed_assets where tenant_id=p_tenant_id;
  select coalesce(sum(debit-credit),0)::bigint into v_asset_cost_gl from public.accounting_journal_lines where tenant_id=p_tenant_id and account_code='1-1060';
  select coalesce(sum(credit-debit),0)::bigint into v_asset_accum_gl from public.accounting_journal_lines where tenant_id=p_tenant_id and account_code='1-1070';
  v_asset_cost_delta:=v_asset_cost_subledger-v_asset_cost_gl; v_asset_accum_delta:=v_asset_accum_subledger-v_asset_accum_gl;
  select coalesce(sum(allowance_amount),0)::bigint into v_allowance_subledger from public.receivable_allowances where tenant_id=p_tenant_id;
  select coalesce(sum(credit-debit),0)::bigint into v_allowance_gl from public.accounting_journal_lines where tenant_id=p_tenant_id and account_code='1-1080';
  v_allowance_delta:=v_allowance_subledger-v_allowance_gl;
  select count(*)::bigint into v_allowance_exceeds from public.receivable_allowances a join public.customer_receivables r on r.tenant_id=a.tenant_id and r.sale_transaction_ref=a.sale_transaction_ref where a.tenant_id=p_tenant_id and a.allowance_amount>r.remaining_amount;

  select count(*)::bigint into v_tax_gl_mismatch$a$);
  if v_def=v_old then raise exception 'owner_gate_compute_anchor_missing'; end if;
  v_old:=v_def; v_def:=replace(v_def,
    $a$'payroll_pph21_evidence_minus_gl_2_2040',v_pph21_delta,$a$,
    $a$'payroll_pph21_evidence_minus_gl_2_2040',v_pph21_delta,
    'fixed_asset_cost_subledger_minus_gl_1_1060',v_asset_cost_delta,
    'fixed_asset_accum_subledger_minus_gl_1_1070',v_asset_accum_delta,
    'fixed_asset_invalid_count',v_asset_invalid,
    'receivable_allowance_subledger_minus_gl_1_1080',v_allowance_delta,
    'receivable_allowance_exceeds_receivable_count',v_allowance_exceeds,$a$);
  if v_def=v_old then raise exception 'owner_gate_output_anchor_missing'; end if;
  v_old:=v_def; v_def:=replace(v_def,
    $a$v_salary_delta=0 and v_salary_negative=0 and v_pph21_delta=0)$a$,
    $a$v_salary_delta=0 and v_salary_negative=0 and v_pph21_delta=0 and v_asset_cost_delta=0 and v_asset_accum_delta=0 and v_asset_invalid=0 and v_allowance_delta=0 and v_allowance_exceeds=0)$a$);
  if v_def=v_old then raise exception 'owner_gate_allzero_anchor_missing'; end if;
  execute v_def;
