create or replace function private.tax_period_obligation(
  p_tenant_id uuid,
  p_tax_code text,
  p_period_start date,
  p_period_end date
) returns bigint
language plpgsql
stable
security definer
set search_path=''
as $$
declare v_code text:=upper(btrim(coalesce(p_tax_code,''))); v_amount bigint;
begin
  if p_period_start is null or p_period_end is null or p_period_end<p_period_start then
    raise exception 'invalid_tax_period' using errcode='22023';
  end if;
  if v_code='PPH21' then
    select greatest(coalesce(sum(withholding_adjustment),0),0)::bigint into v_amount
    from public.payroll_tax_evidence
    where tenant_id=p_tenant_id and business_date between p_period_start and p_period_end;
  elsif v_code='PPH23' then
    select coalesce(sum(tax_amount),0)::bigint into v_amount
    from public.tax_documents
    where tenant_id=p_tenant_id and document_type='PPH23_UNIFICATION'
      and business_date between p_period_start and p_period_end
      and status in ('VALIDATED','SUBMITTED','ACCEPTED','REPORTED');
  elsif v_code='PPH_FINAL' then
    select coalesce(sum(tax_amount),0)::bigint into v_amount
    from public.tax_documents
    where tenant_id=p_tenant_id and document_type='PPH_FINAL'
      and business_date between p_period_start and p_period_end
      and status in ('VALIDATED','SUBMITTED','ACCEPTED','REPORTED');
  else
    raise exception 'unsupported_tax_remittance_code' using errcode='22023';
  end if;
  return coalesce(v_amount,0);
end;
$$;
revoke all on function private.tax_period_obligation(uuid,text,date,date) from public,anon,authenticated,service_role;

create or replace function public.register_tax_payment_reference_v2(
  p_tenant_id uuid,
  p_tax_code text,
  p_tax_period_start date,
  p_tax_period_end date,
  p_billing_code text,
  p_amount bigint,
  p_device_id text,
  p_app_version text,
  p_reason text
) returns uuid
language plpgsql
security definer
set search_path=''
as $$
declare
  v_actor uuid:=auth.uid();
  v_code text:=upper(btrim(coalesce(p_tax_code,'')));
  v_obligation bigint;
  v_reserved bigint;
  v_id uuid;
begin
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  perform accounting_private.require_member_role(p_tenant_id,v_actor,array['owner','admin','accountant']);
  if v_code not in ('PPH21','PPH23','PPH_FINAL') then raise exception 'unsupported_tax_remittance_code' using errcode='22023'; end if;
  if p_tax_period_start is null or p_tax_period_end is null or p_tax_period_end<p_tax_period_start then raise exception 'invalid_tax_period' using errcode='22023'; end if;
  if p_billing_code is null or length(btrim(p_billing_code))<3 or p_amount is null or p_amount<=0 then raise exception 'billing_code_and_amount_required' using errcode='22023'; end if;
  if p_reason is null or length(btrim(p_reason))<3 then raise exception 'audit_reason_required' using errcode='22023'; end if;

  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':tax-billing:'||v_code||':'||p_tax_period_start::text||':'||p_tax_period_end::text,7337));
  v_obligation:=private.tax_period_obligation(p_tenant_id,v_code,p_tax_period_start,p_tax_period_end);
  select coalesce(sum(amount),0)::bigint into v_reserved
  from public.tax_payment_refs
  where tenant_id=p_tenant_id and tax_code=v_code
    and tax_period_start=p_tax_period_start and tax_period_end=p_tax_period_end
    and status in ('CREATED','PAID');
  if v_obligation<=0 then raise exception 'tax_period_has_no_payable_obligation' using errcode='23514'; end if;
  if p_amount>v_obligation-v_reserved then raise exception 'billing_amount_exceeds_unreserved_tax_obligation' using errcode='23514'; end if;

  insert into public.tax_payment_refs(
    tenant_id,tax_document_id,billing_code,amount,status,actor_user_id,device_id,reason,
    tax_code,tax_period_start,tax_period_end,obligation_snapshot,updated_at
  ) values(
    p_tenant_id,null,btrim(p_billing_code),p_amount,'CREATED',v_actor,btrim(p_device_id),btrim(p_reason),
    v_code,p_tax_period_start,p_tax_period_end,v_obligation,now()
  ) returning payment_ref_id into v_id;
  return v_id;
end;
$$;
revoke all on function public.register_tax_payment_reference_v2(uuid,text,date,date,text,bigint,text,text,text)
  from public,anon,service_role;
grant execute on function public.register_tax_payment_reference_v2(uuid,text,date,date,text,bigint,text,text,text)
  to authenticated;

create or replace function private.build_tax_remittance_lines(
  p_tenant_id uuid,
  p_business_date date,
  p_facts jsonb
) returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  v_ref_id uuid;
  v_ref public.tax_payment_refs%rowtype;
  v_liability_account text;
  v_liability_balance bigint;
  v_method text:=upper(coalesce(p_facts->>'payment_method',''));
  v_payment_account text;
  v_payment_reference text:=nullif(btrim(coalesce(p_facts->>'payment_reference','')),'');
  v_journal jsonb:='[]'::jsonb;
begin
  perform private.assert_no_accounting_fields(p_facts);
  if p_business_date is null then raise exception 'business_date_required' using errcode='22023'; end if;
  begin v_ref_id:=(p_facts->>'payment_ref_id')::uuid; exception when others then raise exception 'tax_payment_ref_id_required' using errcode='22023'; end;
  if v_payment_reference is null or length(v_payment_reference)<3 then raise exception 'tax_payment_confirmation_reference_required' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':tax-payment:'||v_ref_id::text,7338));
  select * into strict v_ref from public.tax_payment_refs r where r.tenant_id=p_tenant_id and r.payment_ref_id=v_ref_id for update;
  if v_ref.status<>'CREATED' then raise exception 'tax_payment_reference_not_open' using errcode='23514'; end if;
  if v_ref.tax_code is null or v_ref.tax_period_start is null or v_ref.tax_period_end is null then raise exception 'legacy_tax_payment_reference_not_payable' using errcode='23514'; end if;
  if p_business_date<v_ref.tax_period_end then raise exception 'tax_payment_before_period_end' using errcode='23514'; end if;
  if v_method='CASH' then v_payment_account:='1-1010'; elsif v_method='BANK' then v_payment_account:='1-1030'; else raise exception 'tax_payment_method_must_be_cash_or_bank' using errcode='22023'; end if;
  v_liability_account:=case v_ref.tax_code when 'PPH21' then '2-2040' when 'PPH23' then '2-2050' when 'PPH_FINAL' then '2-2060' else null end;
  if v_liability_account is null then raise exception 'unsupported_tax_remittance_code' using errcode='23514'; end if;
  select coalesce(sum(credit-debit),0)::bigint into v_liability_balance from public.accounting_journal_lines where tenant_id=p_tenant_id and account_code=v_liability_account;
  if v_liability_balance<v_ref.amount then raise exception 'tax_payment_exceeds_current_tax_liability' using errcode='23514'; end if;
  perform private.assert_sufficient_liquid_funds(p_tenant_id,v_payment_account,v_ref.amount);
  v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code',v_liability_account,'debit',v_ref.amount,'credit',0,'memo','Setor '||v_ref.tax_code));
  v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code',v_payment_account,'debit',0,'credit',v_ref.amount,'memo','Pembayaran pajak via e-Billing'));
  return jsonb_build_object(
    'journal_lines',v_journal,'tax_snapshot',jsonb_build_object('tax_code',v_ref.tax_code,'tax_period_start',v_ref.tax_period_start,'tax_period_end',v_ref.tax_period_end,'billing_code',v_ref.billing_code,'obligation_snapshot',v_ref.obligation_snapshot),
    'payment_ref_id',v_ref_id,'tax_code',v_ref.tax_code,'amount',v_ref.amount,'payment_reference',v_payment_reference,'liability_account',v_liability_account
  );
exception when no_data_found then raise exception 'tax_payment_reference_not_found' using errcode='P0002';
end;
$$;
revoke all on function private.build_tax_remittance_lines(uuid,date,jsonb) from public,anon,authenticated,service_role;

create or replace function private.enforce_tax_remittance_evidence()
returns trigger
language plpgsql
security definer
set search_path=''
as $$
declare
  v_ref_id uuid;
  v_ref public.tax_payment_refs%rowtype;
  v_account text;
  v_debit bigint;
  v_cash_credit bigint;
  v_payment_reference text;
begin
  if new.transaction_type<>'SETOR_PAJAK' then return new; end if;
  v_ref_id:=(new.facts_snapshot->>'payment_ref_id')::uuid;
  v_payment_reference:=btrim(new.facts_snapshot->>'payment_reference');
  select * into strict v_ref from public.tax_payment_refs r where r.tenant_id=new.tenant_id and r.payment_ref_id=v_ref_id for update;
  if v_ref.status<>'CREATED' then raise exception 'tax_payment_reference_not_open' using errcode='23514'; end if;
  v_account:=case v_ref.tax_code when 'PPH21' then '2-2040' when 'PPH23' then '2-2050' when 'PPH_FINAL' then '2-2060' else null end;
  select coalesce(sum(l.debit-l.credit),0)::bigint into v_debit from public.accounting_journal_lines l where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code=v_account;
  select coalesce(sum(l.credit-l.debit),0)::bigint into v_cash_credit from public.accounting_journal_lines l where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code in ('1-1010','1-1030');
  if v_debit<>v_ref.amount or v_cash_credit<>v_ref.amount then raise exception 'tax_remittance_gl_mismatch' using errcode='23514'; end if;
  update public.tax_payment_refs set status='PAID',payment_reference=v_payment_reference,paid_at=now(),payment_journal_id=new.journal_id,updated_at=now() where tenant_id=new.tenant_id and payment_ref_id=v_ref_id and status='CREATED';
  if not found then raise exception 'tax_payment_reference_state_conflict' using errcode='40001'; end if;
  return new;
end;
$$;
revoke all on function private.enforce_tax_remittance_evidence() from public,anon,authenticated,service_role;

create trigger accounting_transaction_tax_remittance_guard
after insert on public.accounting_transaction_evidence
for each row when (new.transaction_type='SETOR_PAJAK')
execute function private.enforce_tax_remittance_evidence();

alter table public.accounting_transaction_evidence drop constraint accounting_transaction_evidence_transaction_type_check;
alter table public.accounting_transaction_evidence add constraint accounting_transaction_evidence_transaction_type_check check (transaction_type=any(array[
  'JUAL_TUNAI'::text,'JUAL_QRIS'::text,'JUAL_TRANSFER'::text,'JUAL_KREDIT'::text,
  'BELI_KREDIT'::text,'BEBAN_VENDOR_KREDIT'::text,'BAYAR_VENDOR'::text,'TERIMA_PIUTANG'::text,
  'GAJI_BULANAN'::text,'BAYAR_GAJI'::text,'SETOR_PAJAK'::text,
  'SETOR_MODAL_OWNER'::text,'BELI_ASET_TUNAI'::text,'PENYUSUTAN_BULANAN'::text,'PRIVE_OWNER'::text,'ATUR_CADANGAN_PIUTANG'::text,
  'RETUR_PENJUALAN'::text,'STOCK_OPNAME'::text
]));

do $patch$
declare v_def text; v_old text;
begin
  v_def:=pg_get_functiondef('public.create_auto_journal(uuid,text,text,date,jsonb,text,text,text)'::regprocedure);
  v_old:=v_def;
  v_def:=replace(v_def,
    $a$if v_type not in ('JUAL_TUNAI','JUAL_QRIS','JUAL_TRANSFER','JUAL_KREDIT','BELI_KREDIT','BEBAN_VENDOR_KREDIT','BAYAR_VENDOR','TERIMA_PIUTANG','GAJI_BULANAN','BAYAR_GAJI','SETOR_MODAL_OWNER','BELI_ASET_TUNAI','PENYUSUTAN_BULANAN','PRIVE_OWNER','ATUR_CADANGAN_PIUTANG','RETUR_PENJUALAN','STOCK_OPNAME') then$a$,
    $a$if v_type not in ('JUAL_TUNAI','JUAL_QRIS','JUAL_TRANSFER','JUAL_KREDIT','BELI_KREDIT','BEBAN_VENDOR_KREDIT','BAYAR_VENDOR','TERIMA_PIUTANG','GAJI_BULANAN','BAYAR_GAJI','SETOR_PAJAK','SETOR_MODAL_OWNER','BELI_ASET_TUNAI','PENYUSUTAN_BULANAN','PRIVE_OWNER','ATUR_CADANGAN_PIUTANG','RETUR_PENJUALAN','STOCK_OPNAME') then$a$);
  if v_def=v_old then raise exception 'tax_remittance_whitelist_anchor_missing'; end if;
  v_old:=v_def;
  v_def:=replace(v_def,
    $a$if v_type in ('RETUR_PENJUALAN','STOCK_OPNAME','GAJI_BULANAN','BAYAR_GAJI','BELI_ASET_TUNAI','PENYUSUTAN_BULANAN','PRIVE_OWNER','ATUR_CADANGAN_PIUTANG') and v_member_role='cashier' then$a$,
    $a$if v_type in ('RETUR_PENJUALAN','STOCK_OPNAME','GAJI_BULANAN','BAYAR_GAJI','SETOR_PAJAK','BELI_ASET_TUNAI','PENYUSUTAN_BULANAN','PRIVE_OWNER','ATUR_CADANGAN_PIUTANG') and v_member_role='cashier' then$a$);
  if v_def=v_old then raise exception 'tax_remittance_role_anchor_missing'; end if;
  v_old:=v_def;
  v_def:=replace(v_def,
    $a$    when 'SETOR_MODAL_OWNER' then v_source:='manual'; v_build:=private.build_owner_capital_lines(p_tenant_id,p_business_date,p_facts);$a$,
    $a$    when 'SETOR_PAJAK' then v_source:='manual'; v_build:=private.build_tax_remittance_lines(p_tenant_id,p_business_date,p_facts);
    when 'SETOR_MODAL_OWNER' then v_source:='manual'; v_build:=private.build_owner_capital_lines(p_tenant_id,p_business_date,p_facts);$a$);
  if v_def=v_old then raise exception 'tax_remittance_case_anchor_missing'; end if;
  execute v_def;

  v_def:=pg_get_functiondef('private.guard_domain_journal_reversal()'::regprocedure);
  v_old:=v_def;
  v_def:=replace(v_def,
    $a$'SETOR_MODAL_OWNER','BELI_ASET_TUNAI'$a$,
    $a$'SETOR_PAJAK','SETOR_MODAL_OWNER','BELI_ASET_TUNAI'$a$);
  if v_def=v_old then raise exception 'tax_remittance_reversal_anchor_missing'; end if;
  execute v_def;
end;
$patch$;

do $gate$
declare v_def text; v_old text;
begin
  v_def:=pg_get_functiondef('private.compute_accounting_hard_gate(uuid)'::regprocedure);
  v_old:=v_def;
  v_def:=replace(v_def,$a$v_negative_liquid bigint;$a$,$a$v_negative_liquid bigint; v_tax_payment_errors bigint;$a$);
  if v_def=v_old then raise exception 'tax_payment_gate_declaration_anchor_missing'; end if;
  v_old:=v_def;
  v_def:=replace(v_def,
    $a$  select count(*)::bigint into v_tax_gl_mismatch$a$,
    $a$  select count(*)::bigint into v_tax_payment_errors from public.tax_payment_refs r
  where r.tenant_id=p_tenant_id and r.status='PAID' and (
    r.payment_journal_id is null or nullif(btrim(coalesce(r.payment_reference,'')),'') is null or r.paid_at is null
    or not exists(
      select 1 from public.accounting_transaction_evidence e
      where e.tenant_id=r.tenant_id and e.journal_id=r.payment_journal_id and e.transaction_type='SETOR_PAJAK'
        and e.facts_snapshot->>'payment_ref_id'=r.payment_ref_id::text
    )
    or coalesce((select sum(case r.tax_code when 'PPH21' then case when l.account_code='2-2040' then l.debit-l.credit else 0 end when 'PPH23' then case when l.account_code='2-2050' then l.debit-l.credit else 0 end when 'PPH_FINAL' then case when l.account_code='2-2060' then l.debit-l.credit else 0 end else 0 end) from public.accounting_journal_lines l where l.tenant_id=r.tenant_id and l.journal_id=r.payment_journal_id),0)<>r.amount
  );

  select count(*)::bigint into v_tax_gl_mismatch$a$);
  if v_def=v_old then raise exception 'tax_payment_gate_compute_anchor_missing'; end if;
  v_old:=v_def;
  v_def:=replace(v_def,$a$'negative_liquid_asset_count',v_negative_liquid,$a$,$a$'negative_liquid_asset_count',v_negative_liquid,'tax_payment_reconciliation_error_count',v_tax_payment_errors,$a$);
  if v_def=v_old then raise exception 'tax_payment_gate_output_anchor_missing'; end if;
  v_old:=v_def;
  v_def:=replace(v_def,$a$v_negative_liquid=0)$a$,$a$v_negative_liquid=0 and v_tax_payment_errors=0)$a$);
  if v_def=v_old then raise exception 'tax_payment_gate_allzero_anchor_missing'; end if;
  execute v_def;
end;
$gate$;

do $patch$
declare v_def text; v_old text;
begin
  v_def:=pg_get_functiondef('public.register_tax_payment_reference_v2(uuid,text,date,date,text,bigint,text,text,text)'::regprocedure);
  v_old:=v_def;
  v_def:=replace(v_def,
    $a$if p_tax_period_start is null or p_tax_period_end is null or p_tax_period_end<p_tax_period_start then raise exception 'invalid_tax_period' using errcode='22023'; end if;$a$,
    $a$if p_tax_period_start is null or p_tax_period_end is null or p_tax_period_end<p_tax_period_start then raise exception 'invalid_tax_period' using errcode='22023'; end if;
  if p_tax_period_start<>date_trunc('month',p_tax_period_start)::date
     or p_tax_period_end<>(date_trunc('month',p_tax_period_start)+interval '1 month - 1 day')::date then
    raise exception 'tax_period_must_be_full_calendar_month' using errcode='22023';
  end if;$a$);
  if v_def=v_old then raise exception 'ebilling_calendar_period_anchor_missing'; end if;
  execute v_def;
