create table public.vat_period_settlements (
  settlement_id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.accounting_tenants(tenant_id),
  period_start date not null,
  period_end date not null,
  output_vat_charged bigint not null check (output_vat_charged>=0),
  output_vat_reductions bigint not null check (output_vat_reductions>=0),
  input_vat_current bigint not null check (input_vat_current>=0),
  carry_in bigint not null check (carry_in>=0),
  offset_used bigint not null check (offset_used>=0),
  return_credit_reclass bigint not null check (return_credit_reclass>=0),
  net_payable bigint not null check (net_payable>=0),
  carry_out bigint not null check (carry_out>=0),
  settlement_journal_id uuid null references public.accounting_journals(journal_id),
  actor_user_id uuid not null references auth.users(id),
  device_id text not null check (length(btrim(device_id))>=1),
  app_version text not null check (length(btrim(app_version))>=1),
  reason text not null check (length(btrim(reason))>=3),
  created_at timestamptz not null default now(),
  unique(tenant_id,period_start),
  unique(tenant_id,period_end),
  check (period_start=date_trunc('month',period_start)::date),
  check (period_end=(date_trunc('month',period_start)+interval '1 month - 1 day')::date),
  check (return_credit_reclass=greatest(output_vat_reductions-output_vat_charged,0)),
  check (offset_used=least(greatest(output_vat_charged-output_vat_reductions,0),input_vat_current+carry_in)),
  check (net_payable=greatest(output_vat_charged-output_vat_reductions,0)-offset_used),
  check (carry_out=input_vat_current+carry_in+return_credit_reclass-offset_used),
  check ((offset_used+return_credit_reclass=0 and settlement_journal_id is null) or (offset_used+return_credit_reclass>0 and settlement_journal_id is not null))
);
