    when 'PPH23_15_ACCRUAL' then v_source:='manual'; v_build:=private.build_extended_withholding_source_lines(p_tenant_id,p_transaction_ref,p_business_date,p_facts,v_actor,p_device_id,p_reason);
    when 'BAYAR_PPH23_15' then v_source:='supplier_payment'; v_build:=private.build_extended_withholding_payment_lines(p_tenant_id,p_business_date,p_facts);$a$);
  if v_def=v_old then raise exception 'extended_pph23_case_anchor_missing'; end if;
  v_old:=v_def;
