  if v_def=v_old then raise exception 'extended_pph23_tax_document_anchor_missing'; end if;
  execute v_def;

  v_def:=pg_get_functiondef('private.guard_domain_journal_reversal()'::regprocedure); v_old:=v_def;
  v_def:=replace(v_def,$a$'TERIMA_PIUTANG_PPH23','GAJI_BULANAN'$a$,$a$'TERIMA_PIUTANG_PPH23','PPH23_15_ACCRUAL','BAYAR_PPH23_15','GAJI_BULANAN'$a$);
  if v_def=v_old then raise exception 'extended_pph23_reversal_anchor_missing'; end if; execute v_def;
end; $dispatcher$;

do $gate$
declare v_def text; v_old text;
