create or replace function private.umkm_gross_turnover_between(p_tenant_id uuid,p_from date,p_to date)
returns bigint language sql stable security definer set search_path=''
as $$
  with sale_lines as (
    select
      s.tenant_id,s.transaction_ref,s.line_key,s.line_kind,s.service_profile_id,s.quantity,s.list_amount,s.taxable,s.tax_snapshot,
      e.business_date,e.facts_snapshot,
      case
        when s.line_kind='SERVICE' then coalesce(sp.umkm_final_eligible,false)
        else true
      end as umkm_eligible,
      case
        when s.taxable and coalesce((e.facts_snapshot->>'prices_include_vat')::boolean,false)
          then round(s.list_amount::numeric/(1+coalesce((s.tax_snapshot->>'effective_rate')::numeric,0)))::bigint
        else s.list_amount
      end as gross_before_discount_ex_vat
    from public.sale_line_evidence s
    join public.accounting_transaction_evidence e
      on e.tenant_id=s.tenant_id and e.transaction_ref=s.transaction_ref
    left join public.service_tax_profiles sp
      on sp.tenant_id=s.tenant_id and sp.service_profile_id=s.service_profile_id
    where s.tenant_id=p_tenant_id
      and e.transaction_type in ('JUAL_TUNAI','JUAL_QRIS','JUAL_TRANSFER','JUAL_KREDIT')
      and e.business_date between p_from and p_to
  ), returns as (
    select r.tenant_id,r.original_transaction_ref,r.line_key,
           er.business_date as return_date,
           round(sl.gross_before_discount_ex_vat::numeric*r.quantity::numeric/sl.quantity::numeric)::bigint as gross_reversed,
           sl.umkm_eligible
    from public.sale_return_line_evidence r
    join public.accounting_transaction_evidence er
      on er.tenant_id=r.tenant_id and er.transaction_ref=r.return_transaction_ref
    join sale_lines sl
      on sl.tenant_id=r.tenant_id and sl.transaction_ref=r.original_transaction_ref and sl.line_key=r.line_key
    where r.tenant_id=p_tenant_id and er.business_date between p_from and p_to
  )
  select greatest(
    coalesce((select sum(gross_before_discount_ex_vat) from sale_lines where umkm_eligible),0)
    - coalesce((select sum(gross_reversed) from returns where umkm_eligible),0),0
  )::bigint;
$$;
revoke all on function private.umkm_gross_turnover_between(uuid,date,date) from public,anon,authenticated,service_role;

create or replace function private.build_owner_turnover_tax_lines(p_tenant_id uuid,p_business_date date,p_facts jsonb)
returns jsonb language plpgsql stable security definer set search_path=''
as $$
declare
  v_month_start date:=date_trunc('month',p_business_date)::date;
  v_month_end date:=(date_trunc('month',p_business_date)+interval '1 month - 1 day')::date;
  v_self_count int; v_self public.tax_parties%rowtype; v_rule jsonb; v_month bigint; v_before bigint; v_after bigint; v_exempt bigint:=0; v_taxable bigint; v_tax bigint; v_limit bigint; v_exempt_limit bigint;
begin
  perform private.assert_no_accounting_fields(p_facts);
  if jsonb_object_length(coalesce(p_facts,'{}'::jsonb))<>0 then raise exception 'owner_turnover_tax_accepts_no_manual_economic_inputs' using errcode='42501'; end if;
  if p_business_date<>v_month_end then raise exception 'owner_turnover_tax_business_date_must_be_month_end' using errcode='22023'; end if;
  if v_month_end>=current_date then raise exception 'owner_turnover_tax_period_must_be_completed' using errcode='23514'; end if;
  if v_month_start<date '2026-05-01' then raise exception 'historical_umkm_tax_rule_incomplete_for_partial_pre_pp20_period' using errcode='23514'; end if;
  select count(*) into v_self_count from public.tax_parties p where p.tenant_id=p_tenant_id and p.party_kind='SELF'
    and p.valid_from<=v_month_end and (p.valid_to is null or p.valid_to>=v_month_start)
    and private.is_pph_final_umkm_evidence_valid(p.tax_regime,p.taxpayer_type,p.turnover_eligibility,p.certificate_status,p.legal_basis,v_month_end)
    and coalesce((p.metadata->>'umkm_all_turnover_captured')::boolean,false)
    and coalesce((p.metadata->>'umkm_prior_year_eligibility_verified')::boolean,false);
  if v_self_count<>1 then raise exception 'exactly_one_verified_self_umkm_final_profile_required' using errcode='23514'; end if;
  select * into strict v_self from public.tax_parties p where p.tenant_id=p_tenant_id and p.party_kind='SELF'
    and p.valid_from<=v_month_end and (p.valid_to is null or p.valid_to>=v_month_start)
    and private.is_pph_final_umkm_evidence_valid(p.tax_regime,p.taxpayer_type,p.turnover_eligibility,p.certificate_status,p.legal_basis,v_month_end)
    and coalesce((p.metadata->>'umkm_all_turnover_captured')::boolean,false)
    and coalesce((p.metadata->>'umkm_prior_year_eligibility_verified')::boolean,false);
  v_rule:=private.resolve_tax_rate_snapshot('PPH_FINAL_UMKM','TURNOVER',v_month_end,'DEFAULT');
  v_limit:=coalesce((v_rule->'metadata'->>'turnover_limit_idr')::bigint,4800000000);
  v_exempt_limit:=coalesce((v_rule->'metadata'->>'wp_op_exempt_first_idr')::bigint,500000000);
  v_month:=private.umkm_gross_turnover_between(p_tenant_id,v_month_start,v_month_end);
  v_before:=private.umkm_gross_turnover_between(p_tenant_id,make_date(extract(year from v_month_start)::int,1,1),v_month_start-1);
  v_after:=v_before+v_month;
  if v_self.taxpayer_type='OP' then
    v_exempt:=least(v_month,greatest(v_exempt_limit-v_before,0));
  end if;
  v_taxable:=v_month-v_exempt;
  v_tax:=round(v_taxable::numeric*(v_rule->>'effective_rate')::numeric)::bigint;
  return jsonb_build_object(
    'journal_lines',case when v_tax>0 then jsonb_build_array(
      jsonb_build_object('account_code','6-6110','debit',v_tax,'credit',0,'memo','PPh Final UMKM bulan '||to_char(v_month_start,'YYYY-MM')),
      jsonb_build_object('account_code','2-2060','debit',0,'credit',v_tax,'memo','Utang PPh Final UMKM bulan '||to_char(v_month_start,'YYYY-MM'))
    ) else '[]'::jsonb end,
    'tax_snapshot',v_rule||jsonb_build_object('taxpayer_type',v_self.taxpayer_type,'turnover_limit_idr',v_limit,'wp_op_exempt_first_idr',v_exempt_limit,'prior_year_eligibility_verified',true,'all_turnover_captured',true),
    'period_start',v_month_start,'period_end',v_month_end,'taxpayer_type',v_self.taxpayer_type,
    'gross_turnover_month',v_month,'gross_turnover_ytd_before',v_before,'gross_turnover_ytd_after',v_after,
    'exempt_turnover_month',v_exempt,'taxable_turnover_month',v_taxable,'tax_amount',v_tax
  );
exception when no_data_found then raise exception 'owner_umkm_final_tax_dependency_missing' using errcode='23514';
end; $$;
revoke all on function private.build_owner_turnover_tax_lines(uuid,date,jsonb) from public,anon,authenticated,service_role;

create or replace function public.close_owner_turnover_tax_period(p_tenant_id uuid,p_period_start date,p_device_id text,p_app_version text,p_reason text)
returns uuid language plpgsql security definer set search_path=''
as $$
declare
  v_actor uuid:=auth.uid(); v_end date; v_build jsonb; v_existing uuid; v_journal uuid; v_doc uuid; v_id uuid; v_ref text; v_fingerprint jsonb;
begin
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  perform accounting_private.require_member_role(p_tenant_id,v_actor,array['owner','admin','accountant']);
  if p_reason is null or length(btrim(p_reason))<3 then raise exception 'audit_reason_required' using errcode='22023'; end if;
  if p_period_start is null or p_period_start<>date_trunc('month',p_period_start)::date then raise exception 'owner_turnover_tax_period_start_must_be_first_day' using errcode='22023'; end if;
  v_end:=(date_trunc('month',p_period_start)+interval '1 month - 1 day')::date;
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':umkm-final:'||p_period_start::text,7344));
  select period_id into v_existing from public.owner_turnover_tax_periods where tenant_id=p_tenant_id and period_start=p_period_start;
  if v_existing is not null then return v_existing; end if;
  if exists(select 1 from public.owner_turnover_tax_periods p where p.tenant_id=p_tenant_id and p.period_end<p_period_start and p.period_end<>(p_period_start-1)) then null; end if;
  v_build:=private.build_owner_turnover_tax_lines(p_tenant_id,v_end,'{}'::jsonb);
  v_ref:='UMKM_FINAL:'||to_char(p_period_start,'YYYY-MM');
  if (v_build->>'tax_amount')::bigint>0 then
    v_journal:=accounting_private.post_journal(p_tenant_id,'auto:'||v_ref,v_ref,v_end,'PPH_FINAL_UMKM_BULANAN','manual',v_build->'journal_lines',p_device_id,p_app_version);
    v_fingerprint:=jsonb_build_object('transaction_type','PPH_FINAL_UMKM_BULANAN','period_start',p_period_start,'period_end',v_end,'actor_user_id',v_actor,'device_id',btrim(p_device_id),'app_version',btrim(p_app_version),'reason',btrim(p_reason));
    insert into public.accounting_transaction_evidence(tenant_id,transaction_ref,transaction_type,business_date,request_fingerprint,facts_snapshot,tax_snapshot,journal_id,actor_user_id,device_id,app_version,reason)
    values(p_tenant_id,v_ref,'PPH_FINAL_UMKM_BULANAN',v_end,v_fingerprint,jsonb_build_object('period_start',p_period_start,'period_end',v_end),v_build->'tax_snapshot',v_journal,v_actor,btrim(p_device_id),btrim(p_app_version),btrim(p_reason));
    v_doc:=private.create_tax_document_internal(p_tenant_id,'PPH_FINAL',v_ref,v_end,null,null,v_build->'tax_snapshot',(v_build->>'taxable_turnover_month')::bigint,(v_build->>'tax_amount')::bigint,(v_build->>'taxable_turnover_month')::bigint,v_journal,'VALID',false,null,v_actor,p_device_id,p_reason);
  end if;
  insert into public.owner_turnover_tax_periods(tenant_id,period_start,period_end,taxpayer_type,gross_turnover_month,gross_turnover_ytd_before,gross_turnover_ytd_after,exempt_turnover_month,taxable_turnover_month,tax_amount,tax_rule_snapshot,tax_journal_id,tax_document_id,actor_user_id,device_id,app_version,reason)
  values(p_tenant_id,p_period_start,v_end,v_build->>'taxpayer_type',(v_build->>'gross_turnover_month')::bigint,(v_build->>'gross_turnover_ytd_before')::bigint,(v_build->>'gross_turnover_ytd_after')::bigint,(v_build->>'exempt_turnover_month')::bigint,(v_build->>'taxable_turnover_month')::bigint,(v_build->>'tax_amount')::bigint,v_build->'tax_snapshot',v_journal,v_doc,v_actor,btrim(p_device_id),btrim(p_app_version),btrim(p_reason)) returning period_id into v_id;
  insert into private.audit_logs(tenant_id,actor_id,device_id,source,reason,action) values(p_tenant_id::text,v_actor,btrim(p_device_id),'owner_umkm_final:'||to_char(p_period_start,'YYYY-MM'),btrim(p_reason),'success');
  return v_id;
end; $$;
