  v_def:=replace(v_def,$a$  select count(*)::bigint into v_tax_gl_mismatch$a$,$a$  select count(*)::bigint into v_umkm_period_errors from public.owner_turnover_tax_periods p
  where p.tenant_id=p_tenant_id and (
    p.gross_turnover_month<>private.umkm_gross_turnover_between(p.tenant_id,p.period_start,p.period_end)
    or p.gross_turnover_ytd_before<>private.umkm_gross_turnover_between(p.tenant_id,make_date(extract(year from p.period_start)::int,1,1),p.period_start-1)
    or (p.tax_amount>0 and not exists(select 1 from public.accounting_transaction_evidence e where e.tenant_id=p.tenant_id and e.journal_id=p.tax_journal_id and e.transaction_type='PPH_FINAL_UMKM_BULANAN'))
    or (p.tax_amount>0 and not exists(select 1 from public.tax_documents d where d.tenant_id=p.tenant_id and d.tax_document_id=p.tax_document_id and d.document_type='PPH_FINAL' and d.tax_amount=p.tax_amount and d.journal_id=p.tax_journal_id))
  );

  select count(*)::bigint into v_tax_gl_mismatch$a$);
  if v_def=v_old then raise exception 'umkm_gate_compute_anchor_missing'; end if;
  v_old:=v_def;
  v_def:=replace(v_def,$a$'inbound_pph23_credit_subledger_minus_gl_1_1100',v_inbound_pph23_delta,$a$,$a$'inbound_pph23_credit_subledger_minus_gl_1_1100',v_inbound_pph23_delta,'owner_umkm_turnover_tax_period_error_count',v_umkm_period_errors,$a$);
  if v_def=v_old then raise exception 'umkm_gate_output_anchor_missing'; end if;
  v_old:=v_def;
  v_def:=replace(v_def,$a$v_inbound_pph23_delta=0)$a$,$a$v_inbound_pph23_delta=0 and v_umkm_period_errors=0)$a$);
  if v_def=v_old then raise exception 'umkm_gate_allzero_anchor_missing'; end if;
  execute v_def;
end; $gate$;

do $patch$
declare v_def text; v_old text;
begin
  v_def:=pg_get_functiondef('private.build_owner_turnover_tax_lines(uuid,date,jsonb)'::regprocedure);
  v_old:=v_def;
  v_def:=replace(v_def,
    $a$if jsonb_object_length(coalesce(p_facts,'{}'::jsonb))<>0 then raise exception 'owner_turnover_tax_accepts_no_manual_economic_inputs' using errcode='42501'; end if;$a$,
    $a$if coalesce(p_facts,'{}'::jsonb)<>'{}'::jsonb then raise exception 'owner_turnover_tax_accepts_no_manual_economic_inputs' using errcode='42501'; end if;$a$);
  if v_def=v_old then raise exception 'umkm_empty_facts_portability_anchor_missing'; end if;
  execute v_def;
end; $patch$;

