  general_taxable_income bigint not null check (general_taxable_income>=0),
  corporate_tax_due bigint not null check (corporate_tax_due>=0),
  pph23_credit_available bigint not null check (pph23_credit_available>=0),
  pph23_credit_applied bigint not null check (pph23_credit_applied>=0 and pph23_credit_applied<=pph23_credit_available),
  pph25_credit_available bigint not null check (pph25_credit_available>=0),
  pph25_credit_applied bigint not null check (pph25_credit_applied>=0 and pph25_credit_applied<=pph25_credit_available),
