create or replace function private.corporate_commercial_profit_before_tax(p_tenant_id uuid,p_tax_year integer)
returns bigint language sql stable security definer set search_path=''
as $$
  select coalesce(sum(case
    when c.account_type='Pendapatan' then l.credit-l.debit
    when c.account_type in ('HPP','Beban') and l.account_code not in ('6-6110','6-6120') then -(l.debit-l.credit)
    else 0 end),0)::bigint
  from public.accounting_journal_lines l
  join public.accounting_journals j on j.tenant_id=l.tenant_id and j.journal_id=l.journal_id
  join public.accounting_coa c on c.account_code=l.account_code
  where l.tenant_id=p_tenant_id and extract(year from j.journal_date)::integer=p_tax_year;
$$;
revoke all on function private.corporate_commercial_profit_before_tax(uuid,integer) from public,anon,authenticated,service_role;

create or replace function private.corporate_gross_turnover_between(p_tenant_id uuid,p_from date,p_to date)
returns bigint language sql stable security definer set search_path=''
as $$
  with base_lines as (
    select s.tenant_id,s.transaction_ref,s.line_key,s.quantity,s.list_amount,s.taxable,s.tax_snapshot,e.business_date,e.facts_snapshot,
      case when s.taxable and coalesce((e.facts_snapshot->>'prices_include_vat')::boolean,false)
        then round(s.list_amount::numeric/(1+coalesce((s.tax_snapshot->>'effective_rate')::numeric,0)))::bigint
        else s.list_amount end as gross_before_discount_ex_vat
    from public.sale_line_evidence s
    join public.accounting_transaction_evidence e on e.tenant_id=s.tenant_id and e.transaction_ref=s.transaction_ref
    where s.tenant_id=p_tenant_id and e.transaction_type in ('JUAL_TUNAI','JUAL_QRIS','JUAL_TRANSFER','JUAL_KREDIT')
  ), sales_period as (
    select * from base_lines where business_date between p_from and p_to
  ), returns_period as (
    select r.tenant_id,r.original_transaction_ref,r.line_key,er.business_date as return_date,
      round(bl.gross_before_discount_ex_vat::numeric*r.quantity::numeric/bl.quantity::numeric)::bigint as gross_reversed
    from public.sale_return_line_evidence r
    join public.accounting_transaction_evidence er on er.tenant_id=r.tenant_id and er.transaction_ref=r.return_transaction_ref
    join base_lines bl on bl.tenant_id=r.tenant_id and bl.transaction_ref=r.original_transaction_ref and bl.line_key=r.line_key
    where r.tenant_id=p_tenant_id and er.business_date between p_from and p_to
  )
  select greatest(coalesce((select sum(gross_before_discount_ex_vat) from sales_period),0)-coalesce((select sum(gross_reversed) from returns_period),0),0)::bigint;
$$;
revoke all on function private.corporate_gross_turnover_between(uuid,date,date) from public,anon,authenticated,service_role;

create or replace function public.record_corporate_fiscal_adjustment(
  p_tenant_id uuid,p_tax_year integer,p_adjustment_ref text,p_direction text,p_category text,p_amount bigint,
  p_legal_basis text,p_evidence jsonb,p_reverses_adjustment_id uuid,p_device_id text,p_app_version text,p_reason text
) returns uuid language plpgsql security definer set search_path=''
as $$
declare v_actor uuid:=auth.uid(); v_id uuid; v_dir text:=upper(btrim(coalesce(p_direction,''))); v_cat text:=upper(btrim(coalesce(p_category,''))); v_old public.corporate_fiscal_adjustments%rowtype;
begin
  perform accounting_private.require_bound_device(v_actor,p_device_id,p_app_version);
  perform accounting_private.require_member_role(p_tenant_id,v_actor,array['owner','admin','accountant']);
  if exists(select 1 from public.corporate_annual_tax_periods p where p.tenant_id=p_tenant_id and p.tax_year=p_tax_year) then raise exception 'corporate_tax_year_already_closed' using errcode='55000'; end if;
  if p_adjustment_ref is null or length(btrim(p_adjustment_ref))<3 or v_dir not in ('POSITIVE','NEGATIVE') or v_cat not in ('NON_DEDUCTIBLE_EXPENSE','TAXABLE_INCOME_ADDITION','NON_TAXABLE_INCOME','DEDUCTIBLE_EXPENSE','TIMING_DIFFERENCE','OTHER_STATUTORY') or p_amount is null or p_amount<=0 then raise exception 'invalid_fiscal_adjustment' using errcode='22023'; end if;
  if p_legal_basis is null or length(btrim(p_legal_basis))<3 or p_evidence is null or jsonb_typeof(p_evidence)<>'object' or p_evidence='{}'::jsonb or p_reason is null or length(btrim(p_reason))<3 then raise exception 'fiscal_adjustment_evidence_required' using errcode='22023'; end if;
  if p_reverses_adjustment_id is not null then
    select * into strict v_old from public.corporate_fiscal_adjustments a where a.tenant_id=p_tenant_id and a.adjustment_id=p_reverses_adjustment_id and a.tax_year=p_tax_year;
    if v_old.direction=v_dir or v_old.amount<>p_amount then raise exception 'fiscal_adjustment_reversal_must_exactly_offset_original' using errcode='23514'; end if;
  end if;
  insert into public.corporate_fiscal_adjustments(tenant_id,tax_year,adjustment_ref,direction,category,amount,legal_basis,evidence,reverses_adjustment_id,actor_user_id,device_id,reason)
  values(p_tenant_id,p_tax_year,btrim(p_adjustment_ref),v_dir,v_cat,p_amount,btrim(p_legal_basis),p_evidence,p_reverses_adjustment_id,v_actor,btrim(p_device_id),btrim(p_reason)) returning adjustment_id into v_id;
  insert into private.audit_logs(tenant_id,actor_id,device_id,source,reason,action) values(p_tenant_id::text,v_actor,btrim(p_device_id),'corporate_fiscal_adjustment:'||v_id::text,btrim(p_reason),'success');
  return v_id;
exception when no_data_found then raise exception 'fiscal_adjustment_reversal_source_not_found' using errcode='P0002';
end; $$;
revoke all on function public.record_corporate_fiscal_adjustment(uuid,integer,text,text,text,bigint,text,jsonb,uuid,text,text,text) from public,anon,service_role;
grant execute on function public.record_corporate_fiscal_adjustment(uuid,integer,text,text,text,bigint,text,jsonb,uuid,text,text,text) to authenticated;

