    if p_tax_period_start<>make_date(extract(year from p_tax_period_start)::int,1,1) or p_tax_period_end<>make_date(extract(year from p_tax_period_start)::int,12,31) then raise exception 'PPh29_period_must_be_full_calendar_year' using errcode='22023'; end if;
  else
    if p_tax_period_start<>date_trunc('month',p_tax_period_start)::date or p_tax_period_end<>(date_trunc('month',p_tax_period_start)+interval '1 month - 1 day')::date then raise exception 'tax_period_must_be_full_calendar_month' using errcode='22023'; end if;
  end if;$a$);
 if v_def=v_old then raise exception 'corporate_billing_period_anchor_missing'; end if;
 execute v_def;
end; $register$;

create or replace function private.build_tax_remittance_lines(p_tenant_id uuid,p_business_date date,p_facts jsonb)
returns jsonb language plpgsql security definer set search_path=''
as $$
declare
  v_ref_id uuid; v_ref public.tax_payment_refs%rowtype; v_account text; v_balance bigint; v_method text:=upper(coalesce(p_facts->>'payment_method','')); v_payment_account text; v_payment_reference text:=nullif(btrim(coalesce(p_facts->>'payment_reference','')),''); v_journal jsonb:='[]'::jsonb; v_is_asset boolean:=false;
begin
  perform private.assert_no_accounting_fields(p_facts);
  if p_business_date is null then raise exception 'business_date_required' using errcode='22023'; end if;
  begin v_ref_id:=(p_facts->>'payment_ref_id')::uuid; exception when others then raise exception 'tax_payment_ref_id_required' using errcode='22023'; end;
  if v_payment_reference is null or length(v_payment_reference)<3 then raise exception 'tax_payment_confirmation_reference_required' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':tax-payment:'||v_ref_id::text,7338));
  select * into strict v_ref from public.tax_payment_refs r where r.tenant_id=p_tenant_id and r.payment_ref_id=v_ref_id for update;
  if v_ref.status<>'CREATED' then raise exception 'tax_payment_reference_not_open' using errcode='23514'; end if;
  if v_ref.tax_code is null or v_ref.tax_period_start is null or v_ref.tax_period_end is null then raise exception 'legacy_tax_payment_reference_not_payable' using errcode='23514'; end if;
  if p_business_date<v_ref.tax_period_end then raise exception 'tax_payment_before_period_end' using errcode='23514'; end if;
  if v_method='CASH' then v_payment_account:='1-1010'; elsif v_method='BANK' then v_payment_account:='1-1030'; else raise exception 'tax_payment_method_must_be_cash_or_bank' using errcode='22023'; end if;
  v_account:=case v_ref.tax_code when 'PPN' then '2-2010' when 'PPH21' then '2-2040' when 'PPH23' then '2-2050' when 'PPH_FINAL' then '2-2060' when 'PPH25' then '1-1110' when 'PPH29' then '2-2070' else null end;
  if v_account is null then raise exception 'unsupported_tax_remittance_code' using errcode='23514'; end if;
  v_is_asset:=(v_ref.tax_code='PPH25');
  if not v_is_asset then
    select coalesce(sum(credit-debit),0)::bigint into v_balance from public.accounting_journal_lines where tenant_id=p_tenant_id and account_code=v_account;
    if v_balance<v_ref.amount then raise exception 'tax_payment_exceeds_current_tax_liability' using errcode='23514'; end if;
  end if;
  perform private.assert_sufficient_liquid_funds(p_tenant_id,v_payment_account,v_ref.amount);
  v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code',v_account,'debit',v_ref.amount,'credit',0,'memo',case when v_is_asset then 'Angsuran PPh25' else 'Setor '||v_ref.tax_code end));
  v_journal:=v_journal||jsonb_build_array(jsonb_build_object('account_code',v_payment_account,'debit',0,'credit',v_ref.amount,'memo','Pembayaran pajak via e-Billing'));
  return jsonb_build_object('journal_lines',v_journal,'tax_snapshot',jsonb_build_object('tax_code',v_ref.tax_code,'tax_period_start',v_ref.tax_period_start,'tax_period_end',v_ref.tax_period_end,'billing_code',v_ref.billing_code,'obligation_snapshot',v_ref.obligation_snapshot),'payment_ref_id',v_ref_id,'tax_code',v_ref.tax_code,'amount',v_ref.amount,'payment_reference',v_payment_reference,'settlement_account',v_account);
exception when no_data_found then raise exception 'tax_payment_reference_not_found' using errcode='P0002';
end; $$;
revoke all on function private.build_tax_remittance_lines(uuid,date,jsonb) from public,anon,authenticated,service_role;

create or replace function private.enforce_tax_remittance_evidence()
returns trigger language plpgsql security definer set search_path=''
as $$
declare v_ref_id uuid; v_ref public.tax_payment_refs%rowtype; v_account text; v_debit bigint; v_cash_credit bigint; v_payment_reference text;
begin
  if new.transaction_type<>'SETOR_PAJAK' then return new; end if;
  v_ref_id:=(new.facts_snapshot->>'payment_ref_id')::uuid; v_payment_reference:=btrim(new.facts_snapshot->>'payment_reference');
  select * into strict v_ref from public.tax_payment_refs r where r.tenant_id=new.tenant_id and r.payment_ref_id=v_ref_id for update;
  if v_ref.status<>'CREATED' then raise exception 'tax_payment_reference_not_open' using errcode='23514'; end if;
  v_account:=case v_ref.tax_code when 'PPN' then '2-2010' when 'PPH21' then '2-2040' when 'PPH23' then '2-2050' when 'PPH_FINAL' then '2-2060' when 'PPH25' then '1-1110' when 'PPH29' then '2-2070' else null end;
  select coalesce(sum(l.debit-l.credit),0)::bigint into v_debit from public.accounting_journal_lines l where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code=v_account;
  select coalesce(sum(l.credit-l.debit),0)::bigint into v_cash_credit from public.accounting_journal_lines l where l.tenant_id=new.tenant_id and l.journal_id=new.journal_id and l.account_code in ('1-1010','1-1030');
  if v_debit<>v_ref.amount or v_cash_credit<>v_ref.amount then raise exception 'tax_remittance_gl_mismatch' using errcode='23514'; end if;
  update public.tax_payment_refs set status='PAID',payment_reference=v_payment_reference,paid_at=now(),payment_journal_id=new.journal_id,updated_at=now() where tenant_id=new.tenant_id and payment_ref_id=v_ref_id and status='CREATED';
  if not found then raise exception 'tax_payment_reference_state_conflict' using errcode='40001'; end if;
  return new;
end; $$;
revoke all on function private.enforce_tax_remittance_evidence() from public,anon,authenticated,service_role;

do $gate$
declare v_def text; v_old text;
begin
  v_def:=pg_get_functiondef('private.compute_accounting_hard_gate(uuid)'::regprocedure);
  v_old:=v_def;
  v_def:=replace(v_def,
    $a$v_inbound_pph23_credit bigint; v_inbound_pph23_gl bigint; v_inbound_pph23_delta bigint; v_umkm_period_errors bigint;$a$,
    $a$v_inbound_pph23_credit bigint; v_inbound_pph23_gl bigint; v_inbound_pph23_delta bigint; v_umkm_period_errors bigint; v_pph25_expected bigint; v_pph25_gl bigint; v_pph25_delta bigint; v_pph29_expected bigint; v_pph29_gl bigint; v_pph29_delta bigint; v_corp_tax_exp_expected bigint; v_corp_tax_exp_gl bigint; v_corp_tax_exp_delta bigint; v_corp_period_errors bigint; v_corp_loss_errors bigint; v_pph25_authority_errors bigint;$a$);
  if v_def=v_old then raise exception 'corporate_gate_declaration_anchor_missing'; end if;

  v_old:=v_def;
  v_def:=replace(v_def,
    $a$when 'PPH_FINAL' then case when l.account_code='2-2060' then l.debit-l.credit else 0 end else 0 end$a$,
    $a$when 'PPH_FINAL' then case when l.account_code='2-2060' then l.debit-l.credit else 0 end when 'PPH25' then case when l.account_code='1-1110' then l.debit-l.credit else 0 end when 'PPH29' then case when l.account_code='2-2070' then l.debit-l.credit else 0 end else 0 end$a$);
  if v_def=v_old then raise exception 'corporate_gate_tax_payment_case_anchor_missing'; end if;

  v_old:=v_def;
  v_def:=replace(v_def,
    $a$  select coalesce(sum(tax_amount),0)::bigint into v_inbound_pph23_credit from public.customer_withholding_tax_credits where tenant_id=p_tenant_id;
  select coalesce(sum(debit-credit),0)::bigint into v_inbound_pph23_gl from public.accounting_journal_lines where tenant_id=p_tenant_id and account_code='1-1100';
  v_inbound_pph23_delta:=v_inbound_pph23_credit-v_inbound_pph23_gl;$a$,
    $a$  select greatest(coalesce(sum(c.tax_amount),0)-coalesce((select sum(p.pph23_credit_applied) from public.corporate_annual_tax_periods p where p.tenant_id=p_tenant_id),0),0)::bigint into v_inbound_pph23_credit from public.customer_withholding_tax_credits c where c.tenant_id=p_tenant_id;
  select coalesce(sum(debit-credit),0)::bigint into v_inbound_pph23_gl from public.accounting_journal_lines where tenant_id=p_tenant_id and account_code='1-1100';
  v_inbound_pph23_delta:=v_inbound_pph23_credit-v_inbound_pph23_gl;

  select greatest(coalesce(sum(r.amount),0)-coalesce((select sum(p.pph25_credit_applied) from public.corporate_annual_tax_periods p where p.tenant_id=p_tenant_id),0),0)::bigint into v_pph25_expected
  from public.tax_payment_refs r where r.tenant_id=p_tenant_id and r.tax_code='PPH25' and r.status='PAID';
  select coalesce(sum(debit-credit),0)::bigint into v_pph25_gl from public.accounting_journal_lines where tenant_id=p_tenant_id and account_code='1-1110';
  v_pph25_delta:=v_pph25_expected-v_pph25_gl;

  select greatest(coalesce((select sum(p.pph29_payable) from public.corporate_annual_tax_periods p where p.tenant_id=p_tenant_id),0)-coalesce((select sum(r.amount) from public.tax_payment_refs r where r.tenant_id=p_tenant_id and r.tax_code='PPH29' and r.status='PAID'),0),0)::bigint into v_pph29_expected;
  select coalesce(sum(credit-debit),0)::bigint into v_pph29_gl from public.accounting_journal_lines where tenant_id=p_tenant_id and account_code='2-2070';
  v_pph29_delta:=v_pph29_expected-v_pph29_gl;

  select coalesce(sum(corporate_tax_due),0)::bigint into v_corp_tax_exp_expected from public.corporate_annual_tax_periods where tenant_id=p_tenant_id;
  select coalesce(sum(debit-credit),0)::bigint into v_corp_tax_exp_gl from public.accounting_journal_lines where tenant_id=p_tenant_id and account_code='6-6120';
  v_corp_tax_exp_delta:=v_corp_tax_exp_expected-v_corp_tax_exp_gl;

  select count(*)::bigint into v_corp_period_errors from public.corporate_annual_tax_periods p
  where p.tenant_id=p_tenant_id and (
    p.commercial_profit_before_tax<>private.corporate_commercial_profit_before_tax(p.tenant_id,p.tax_year)
    or p.fiscal_positive_adjustments<>coalesce((select sum(a.amount) from public.corporate_fiscal_adjustments a where a.tenant_id=p.tenant_id and a.tax_year=p.tax_year and a.direction='POSITIVE'),0)
    or p.fiscal_negative_adjustments<>coalesce((select sum(a.amount) from public.corporate_fiscal_adjustments a where a.tenant_id=p.tenant_id and a.tax_year=p.tax_year and a.direction='NEGATIVE'),0)
    or p.gross_turnover<>private.corporate_gross_turnover_between(p.tenant_id,make_date(p.tax_year,1,1),make_date(p.tax_year,12,31))
    or p.fiscal_loss_applied<>coalesce((select sum(x.amount_applied) from public.corporate_fiscal_loss_applications x where x.tenant_id=p.tenant_id and x.target_annual_period_id=p.annual_period_id),0)
    or (p.fiscal_loss_created>0 and not exists(select 1 from public.corporate_fiscal_loss_carryforwards l where l.tenant_id=p.tenant_id and l.origin_tax_year=p.tax_year and l.original_loss=p.fiscal_loss_created and l.source_annual_period_id=p.annual_period_id))
    or (p.corporate_tax_due>0 and not exists(select 1 from public.accounting_transaction_evidence e where e.tenant_id=p.tenant_id and e.journal_id=p.annual_journal_id and e.transaction_type='PPH_BADAN_TAHUNAN'))
  );

  select count(*)::bigint into v_corp_loss_errors from public.corporate_fiscal_loss_carryforwards l
  where l.tenant_id=p_tenant_id and (
    l.expires_after_tax_year<>l.origin_tax_year+5
    or coalesce((select sum(a.amount_applied) from public.corporate_fiscal_loss_applications a where a.loss_id=l.loss_id),0)>l.original_loss
    or exists(select 1 from public.corporate_fiscal_loss_applications a where a.loss_id=l.loss_id and (a.target_tax_year<=l.origin_tax_year or a.target_tax_year>l.expires_after_tax_year))
  );

  select count(*)::bigint into v_pph25_authority_errors from public.corporate_pph25_authorities a
  join public.corporate_annual_tax_periods p on p.annual_period_id=a.source_annual_period_id and p.tenant_id=a.tenant_id
  where a.tenant_id=p_tenant_id and (
    a.tax_year<>p.tax_year+1
    or a.annual_installment_basis<>greatest(p.corporate_tax_due-p.pph23_credit_available,0)
    or a.monthly_amount<>round(a.annual_installment_basis::numeric/12)::bigint
    or (a.superseded_from_month is not null and (a.superseded_from_month<=a.effective_from_month or a.superseded_from_month>a.effective_to_month))
  );$a$);
  if v_def=v_old then raise exception 'corporate_gate_compute_anchor_missing'; end if;

  v_old:=v_def;
  v_def:=replace(v_def,
    $a$'inbound_pph23_credit_subledger_minus_gl_1_1100',v_inbound_pph23_delta,'owner_umkm_turnover_tax_period_error_count',v_umkm_period_errors,$a$,
    $a$'inbound_pph23_credit_subledger_minus_gl_1_1100',v_inbound_pph23_delta,'pph25_prepayment_subledger_minus_gl_1_1110',v_pph25_delta,'pph29_payable_subledger_minus_gl_2_2070',v_pph29_delta,'corporate_tax_expense_subledger_minus_gl_6_6120',v_corp_tax_exp_delta,'corporate_annual_tax_period_error_count',v_corp_period_errors,'corporate_fiscal_loss_error_count',v_corp_loss_errors,'pph25_authority_error_count',v_pph25_authority_errors,'owner_umkm_turnover_tax_period_error_count',v_umkm_period_errors,$a$);
  if v_def=v_old then raise exception 'corporate_gate_output_anchor_missing'; end if;

  v_old:=v_def;
  v_def:=replace(v_def,
    $a$v_inbound_pph23_delta=0 and v_umkm_period_errors=0)$a$,
    $a$v_inbound_pph23_delta=0 and v_pph25_delta=0 and v_pph29_delta=0 and v_corp_tax_exp_delta=0 and v_corp_period_errors=0 and v_corp_loss_errors=0 and v_pph25_authority_errors=0 and v_umkm_period_errors=0)$a$);
  if v_def=v_old then raise exception 'corporate_gate_allzero_anchor_missing'; end if;
  execute v_def;
end;
$gate$;

