-- Task 4 repair: lock journal post entrypoints and make economic facts server-authoritative.
-- Target: berkahtigaputeri-pos-staging (cztlmwzfrhyafgawphgw).
-- Existing close-register semantics are preserved: no row means not explicitly closed.
CREATE OR REPLACE FUNCTION accounting_private.require_open_period(
  p_tenant_id uuid, p_business_date date
)
RETURNS void
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO ''
AS $function$
BEGIN
  IF p_tenant_id IS NULL OR p_business_date IS NULL THEN
    RAISE EXCEPTION 'accounting_period_identity_required' USING ERRCODE='22023';
  END IF;

  -- The period table is a close-register: no row means the date remains open.
  -- Any matching persisted row must explicitly be status=open to allow posting.
  IF EXISTS (
    SELECT 1
    FROM public.accounting_periods p
    WHERE p.tenant_id=p_tenant_id
      AND p_business_date BETWEEN p.period_start AND p.period_end
      AND p.status IS DISTINCT FROM 'open'
  ) THEN
    RAISE EXCEPTION 'accounting_period_closed' USING ERRCODE='55000';
  END IF;
END;
$function$;
COMMENT ON FUNCTION accounting_private.require_open_period(uuid,date)
IS 'Fail closed for any persisted accounting period covering the business date unless its status is open; absence of a close-register row means open.';

