CREATE OR REPLACE FUNCTION private.verify_coretax_template()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $function$
  SELECT (
    SELECT count(*) = 3
    FROM (VALUES ('FAKTUR_KELUARAN'), ('BPPU'), ('BPMP')) AS required(template_code)
    WHERE EXISTS (
      SELECT 1
      FROM public.coretax_template_registry AS t
      WHERE t.template_code = required.template_code
        AND t.is_active IS TRUE
        AND t.is_verified IS TRUE
        AND t.xml_template IS NOT NULL
        AND length(btrim(t.xml_template)) >= 20
        AND t.template_sha256 ~ '^[0-9a-f]{64}$'
        AND t.template_sha256 = encode(
          extensions.digest(convert_to(t.xml_template, 'UTF8'), 'sha256'),
          'hex'
        )
        AND coalesce(t.generator_spec ->> 'status', '') <> 'SOURCE_REGISTERED_NOT_PARSED'
    )
  );
$function$;

COMMENT ON FUNCTION private.verify_coretax_template() IS
  'Returns true only when the three required DJP template registry entries are active, verified, parsed, non-empty, and their stored XML bytes match the registered SHA-256. This verifies registry content; a repository asset and its .sha256 sidecar must also be compared in CI because PostgreSQL must not read application/repository files from the server filesystem.';

CREATE OR REPLACE FUNCTION private.can_export_coretax(
  p_tenant_id uuid,
  p_tax_document_id uuid
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_doc public.tax_documents%ROWTYPE;
  v_gate jsonb;
  v_expected_template text;
BEGIN
  IF p_tenant_id IS NULL OR p_tax_document_id IS NULL THEN
    RETURN false;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.accounting_tenants AS t WHERE t.tenant_id = p_tenant_id
  ) THEN
    RETURN false;
  END IF;

  SELECT d.* INTO v_doc
  FROM public.tax_documents AS d
  WHERE d.tax_document_id = p_tax_document_id
    AND d.tenant_id = p_tenant_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;

  IF v_doc.status <> 'VALIDATED' THEN
    RETURN false;
  END IF;

  -- all_zero is the conservative aggregate hard gate; it fails closed for any
  -- non-zero ledger/subledger delta as well as other accounting invariants.
  v_gate := private.compute_accounting_hard_gate(p_tenant_id);
  IF coalesce((v_gate ->> 'all_zero')::boolean, false) IS NOT TRUE THEN
    RETURN false;
  END IF;

  IF v_doc.tax_rate_snapshot IS NULL
     OR jsonb_typeof(v_doc.tax_rate_snapshot) <> 'object'
     OR v_doc.tax_rate_snapshot = '{}'::jsonb
     OR v_doc.legal_rule_snapshot IS NULL
     OR jsonb_typeof(v_doc.legal_rule_snapshot) <> 'object'
     OR v_doc.legal_rule_snapshot = '{}'::jsonb
     OR nullif(btrim(v_doc.legal_rule_snapshot ->> 'legal_basis'), '') IS NULL THEN
    RETURN false;
  END IF;

  v_expected_template := CASE v_doc.document_type
    WHEN 'VAT_OUTPUT' THEN 'FAKTUR_KELUARAN'
    WHEN 'VAT_REPLACEMENT' THEN 'FAKTUR_KELUARAN'
    WHEN 'PPH23_UNIFICATION' THEN 'BPPU'
    WHEN 'PPH21_26' THEN 'BPMP'
    ELSE NULL
  END;
  IF v_expected_template IS NULL OR NOT private.verify_coretax_template() THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.coretax_template_registry AS t
    WHERE t.template_code = v_expected_template
      AND t.is_active IS TRUE
      AND t.is_verified IS TRUE
      AND t.xml_template IS NOT NULL
      AND t.template_sha256 ~ '^[0-9a-f]{64}$'
      AND t.template_sha256 = encode(
        extensions.digest(convert_to(t.xml_template, 'UTF8'), 'sha256'),
        'hex'
      )
      AND coalesce(t.generator_spec ->> 'status', '') <> 'SOURCE_REGISTERED_NOT_PARSED'
  );
END;
$function$;

COMMENT ON FUNCTION private.can_export_coretax(uuid, uuid) IS
  'Per-document fail-closed Coretax capability gate: accounting hard gate all_zero, document VALIDATED, both tax snapshots present/non-empty, and all required registered templates verified against stored XML SHA-256.';

CREATE OR REPLACE FUNCTION public.get_coretax_export_capability(
  p_tax_document_id uuid,
  p_device_id text,
  p_app_version text
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_doc public.tax_documents%ROWTYPE;
  v_gate jsonb;
  v_templates_verified boolean;
  v_snapshot_ready boolean;
  v_can_export boolean;
  v_expected_template text;
  v_blockers jsonb := '[]'::jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING errcode = '42501';
  END IF;

  SELECT d.* INTO STRICT v_doc
  FROM public.tax_documents AS d
  WHERE d.tax_document_id = p_tax_document_id;

  PERFORM accounting_private.require_bound_device(v_actor, p_device_id, p_app_version);
  PERFORM accounting_private.require_member_role(
    v_doc.tenant_id,
    v_actor,
    ARRAY['owner', 'admin', 'accountant']
  );

  v_gate := private.compute_accounting_hard_gate(v_doc.tenant_id);
  v_templates_verified := private.verify_coretax_template();
  v_snapshot_ready :=
    v_doc.tax_rate_snapshot IS NOT NULL
    AND jsonb_typeof(v_doc.tax_rate_snapshot) = 'object'
    AND v_doc.tax_rate_snapshot <> '{}'::jsonb
    AND v_doc.legal_rule_snapshot IS NOT NULL
    AND jsonb_typeof(v_doc.legal_rule_snapshot) = 'object'
    AND v_doc.legal_rule_snapshot <> '{}'::jsonb
    AND nullif(btrim(v_doc.legal_rule_snapshot ->> 'legal_basis'), '') IS NOT NULL;

  v_expected_template := CASE v_doc.document_type
    WHEN 'VAT_OUTPUT' THEN 'FAKTUR_KELUARAN'
    WHEN 'VAT_REPLACEMENT' THEN 'FAKTUR_KELUARAN'
    WHEN 'PPH23_UNIFICATION' THEN 'BPPU'
    WHEN 'PPH21_26' THEN 'BPMP'
    ELSE NULL
  END;

  v_can_export := private.can_export_coretax(v_doc.tenant_id, v_doc.tax_document_id);

  IF coalesce((v_gate ->> 'all_zero')::boolean, false) IS NOT TRUE THEN
    v_blockers := v_blockers || jsonb_build_array('ACCOUNTING_HARD_GATE_NOT_ZERO');
  END IF;
  IF NOT v_snapshot_ready THEN
    v_blockers := v_blockers || jsonb_build_array('TAX_SNAPSHOT_MISSING_OR_EMPTY');
  END IF;
  IF NOT v_templates_verified THEN
    v_blockers := v_blockers || jsonb_build_array('CORETAX_REQUIRED_TEMPLATES_NOT_VERIFIED');
  END IF;
  IF v_doc.status <> 'VALIDATED' THEN
    v_blockers := v_blockers || jsonb_build_array('TAX_DOCUMENT_NOT_VALIDATED');
  END IF;
  IF v_expected_template IS NULL THEN
    v_blockers := v_blockers || jsonb_build_array('UNSUPPORTED_TAX_DOCUMENT_TYPE');
  END IF;

  RETURN jsonb_build_object(
    'can_export_coretax', coalesce(v_can_export, false),
    'accounting_all_zero', coalesce((v_gate ->> 'all_zero')::boolean, false),
    'accounting_gate', v_gate,
    'snapshot_ready', coalesce(v_snapshot_ready, false),
    'required_templates_verified', coalesce(v_templates_verified, false),
    'expected_template_code', v_expected_template,
    'blockers', v_blockers
  );
EXCEPTION
  WHEN no_data_found THEN
    RAISE EXCEPTION 'tax_document_not_found' USING errcode = 'P0002';
END;
$function$;

COMMENT ON FUNCTION public.get_coretax_export_capability(uuid, text, text) IS
  'Authenticated read-only per-document Coretax capability. can_export_coretax is false when accounting hard gate is non-zero, snapshots are missing/empty, the document is not validated, or required official templates fail hash verification.';

CREATE OR REPLACE FUNCTION private.guard_coretax_export_gate()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_document_type text;
  v_expected_template text;
BEGIN
  IF NEW.payload_sha256 IS NULL
     OR NEW.payload_sha256 !~ '^[0-9a-f]{64}$'
     OR NEW.payload_sha256 <> encode(
       extensions.digest(convert_to(NEW.xml_payload, 'UTF8'), 'sha256'),
       'hex'
     ) THEN
    RAISE EXCEPTION 'coretax_payload_sha256_mismatch' USING errcode = '23514';
  END IF;

  SELECT d.document_type INTO v_document_type
  FROM public.tax_documents AS d
  WHERE d.tax_document_id = NEW.tax_document_id
    AND d.tenant_id = NEW.tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'coretax_export_document_tenant_mismatch' USING errcode = '23514';
  END IF;

  v_expected_template := CASE v_document_type
    WHEN 'VAT_OUTPUT' THEN 'FAKTUR_KELUARAN'
    WHEN 'VAT_REPLACEMENT' THEN 'FAKTUR_KELUARAN'
    WHEN 'PPH23_UNIFICATION' THEN 'BPPU'
    WHEN 'PPH21_26' THEN 'BPMP'
    ELSE NULL
  END;
  IF v_expected_template IS NULL OR NEW.xml_template_code IS DISTINCT FROM v_expected_template THEN
    RAISE EXCEPTION 'coretax_template_document_type_mismatch' USING errcode = '23514';
  END IF;

  IF NOT private.can_export_coretax(NEW.tenant_id, NEW.tax_document_id) THEN
    RAISE EXCEPTION 'coretax_export_blocked_by_accounting_snapshot_or_template_gate' USING errcode = '23514';
  END IF;

  RETURN NEW;
END;
$function$;

COMMENT ON FUNCTION private.guard_coretax_export_gate() IS
  'Rejects a new Coretax outbox row unless its payload hash matches and the tenant/document/accounting/snapshot/template export capability gate passes.';

DROP TRIGGER IF EXISTS coretax_outbox_export_gate ON public.coretax_outbox;
CREATE TRIGGER coretax_outbox_export_gate
BEFORE INSERT ON public.coretax_outbox
FOR EACH ROW EXECUTE FUNCTION private.guard_coretax_export_gate();

REVOKE ALL ON FUNCTION private.verify_coretax_template() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION private.can_export_coretax(uuid, uuid) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION private.guard_coretax_export_gate() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.get_coretax_export_capability(uuid, text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_coretax_export_capability(uuid, text, text) TO authenticated;

-- Phase 5 tenant isolation hardening.
-- Canonical schema uses text tenant_id/device_id and app_config(key, value, updated_at).
-- Direct app_config reads are DEVICE-only; aggregate configuration is RPC-only.

begin;

create schema if not exists private;
revoke all on schema private from public, anon;
grant usage on schema private to authenticated, service_role;

-- Remove ambient direct grants left by early/bootstrap schemas. Policies alone are
-- not a substitute for table grants: both must deny anonymous access.
revoke all privileges on table
  public.tenants,
  public.devices,
  public.licences,
  public.app_config,
  public.tenant_services,
  public.config_history,
  public.accounting_coa,
  public.client_status
from anon, public;

-- Prevent future tables created by postgres in public from inheriting anonymous
-- or PUBLIC table privileges. Authenticated and service_role defaults are unchanged.
alter default privileges for role postgres in schema public
  revoke all on tables from anon, public;

alter table public.tenants enable row level security;
alter table public.devices enable row level security;
alter table public.licences enable row level security;
alter table public.app_config enable row level security;
alter table public.tenant_services enable row level security;
alter table public.config_history enable row level security;
alter table public.accounting_coa enable row level security;
alter table public.client_status enable row level security;

-- Delete any broad policy addressed to anon/PUBLIC on the protected surfaces,
-- including accidental policies that combine anon with another role.
do $$
declare
  p record;
begin
  for p in
    select schemaname, tablename, policyname
    from pg_policies
    where schemaname = 'public'
      and tablename = any (array[
        'tenants', 'devices', 'licences', 'app_config',
        'tenant_services', 'config_history', 'accounting_coa', 'client_status'
      ])
      and (roles && array['anon'::name, 'public'::name])
  loop
    execute format('drop policy %I on %I.%I', p.policyname, p.schemaname, p.tablename);
  end loop;
end
$$;

-- Inventory guard is defined here as well so the resolver does not depend on
-- undocumented dashboard-only function state.
create or replace function private.assert_app_config_inventory()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_count integer;
  v_digest text;
begin
  select count(*)::integer, md5(string_agg(key, E'\n' order by key))
    into v_count, v_digest
  from public.app_config;

  if v_count <> 352 or v_digest <> '1fd3d64219ecc7c333453c20da80e295' then
    raise exception 'app_config inventory mismatch: count %, digest %', v_count, v_digest
      using errcode = '23514';
  end if;
end;
$$;
revoke all on function private.assert_app_config_inventory() from public, anon, authenticated, service_role;

-- Match the deployed tax-authority behavior: legacy tax values are not promoted
-- from client-owned config JSON into the effective configuration.
create or replace function private.strip_legacy_tax_config(p_value jsonb)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb)
  from jsonb_each(coalesce(p_value, '{}'::jsonb)) e
  where lower(e.key) not in (
    'ppn', 'ppn rate %', 'ppn account', 'dpp',
    'pph21', 'pph 21', 'pph23', 'pph 23', 'pph final', 'tax rate', 'tax_rate'
  );
$$;
revoke all on function private.strip_legacy_tax_config(jsonb) from public, anon, authenticated, service_role;

-- Helpers used by authenticated RLS policies must be executable by that role,
-- but must not be ambiently callable by anon.
revoke all on function private.btp_is_super_admin() from public, anon;
grant execute on function private.btp_is_super_admin() to authenticated, service_role;
revoke all on function private.can_read_final_pos_config_strict(text) from public, anon;
grant execute on function private.can_read_final_pos_config_strict(text) to authenticated, service_role;

-- Recreate the four core read policies against the real text-keyed schema.
drop policy if exists "authenticated read own devices" on public.devices;
create policy "authenticated read own devices"
  on public.devices for select to authenticated
  using (user_id = (select auth.uid()));

drop policy if exists "super admin all devices" on public.devices;
create policy "super admin all devices"
  on public.devices for all to authenticated
  using (private.btp_is_super_admin())
  with check (private.btp_is_super_admin());

drop policy if exists "authenticated read own tenants" on public.tenants;
create policy "authenticated read own tenants"
  on public.tenants for select to authenticated
  using (
    exists (
      select 1 from public.devices d
      where d.tenant_id = tenants.tenant_id
        and d.user_id = (select auth.uid())
    )
  );

drop policy if exists "super admin all tenants" on public.tenants;
create policy "super admin all tenants"
  on public.tenants for all to authenticated
  using (private.btp_is_super_admin())
  with check (private.btp_is_super_admin());

drop policy if exists "authenticated read own licences" on public.licences;
create policy "authenticated read own licences"
  on public.licences for select to authenticated
  using (
    exists (
      select 1 from public.devices d
      where d.device_id = licences.device_id
        and d.tenant_id = licences.tenant_id
        and d.user_id = (select auth.uid())
    )
  );

drop policy if exists "super admin all licences" on public.licences;
create policy "super admin all licences"
  on public.licences for all to authenticated
  using (private.btp_is_super_admin())
  with check (private.btp_is_super_admin());

drop policy if exists "authenticated read own app_config" on public.app_config;
drop policy if exists "authenticated read own app_config - device only own" on public.app_config;
create policy "authenticated read own app_config - device only own"
  on public.app_config for select to authenticated
  using (private.can_read_final_pos_config_strict(key));

drop policy if exists "super admin all app_config" on public.app_config;
drop policy if exists "super admin all app_config - canonical" on public.app_config;
create policy "super admin all app_config - canonical"
  on public.app_config for all to authenticated
  using (private.btp_is_super_admin())
  with check (private.btp_is_super_admin());

-- Restore only required SELECT grants after revoking anon/PUBLIC. RLS determines
-- which authenticated rows each caller is permitted to see.
grant select on table public.tenants, public.devices, public.licences, public.app_config to authenticated;

create or replace function public.get_effective_config(
  p_tenant text,
  p_device text,
  p_service text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  g jsonb;
  t jsonb;
  x jsonb;
  s jsonb;
  d jsonb;
  tid text;
  svc text := lower(trim(coalesce(p_service, '')));
  uid uuid := auth.uid();
  role_name text := lower(coalesce(auth.jwt()->>'role', ''));
begin
  perform private.assert_app_config_inventory();

  if nullif(trim(coalesce(p_tenant, '')), '') is null
     or nullif(trim(coalesce(p_device, '')), '') is null
     or svc not in ('pos', 'akuntansi') then
    raise exception 'invalid tenant/device/service' using errcode = '22023';
  end if;

  if role_name <> 'service_role' and uid is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  -- First prove the device is a member of the requested tenant.
  if not exists (
    select 1
    from public.devices z
    where z.device_id = p_device
      and z.tenant_id = p_tenant
  ) then
    raise exception 'device does not belong to tenant' using errcode = '42501';
  end if;

  -- Service-role is server-only. Other callers must own the device or be the
  -- canonical super-admin; caller-supplied tenant/device strings are not authority.
  if role_name <> 'service_role'
     and not private.btp_is_super_admin()
     and not exists (
       select 1 from public.devices z
       where z.device_id = p_device
         and z.tenant_id = p_tenant
         and z.user_id = uid
     ) then
    raise exception 'caller is not authorized for device' using errcode = '42501';
  end if;

  select value into strict g from public.app_config where key = 'global';
  select value into strict t from public.app_config where key = 'tenant:' || p_tenant;

  tid := upper(trim(coalesce(t->>'template_id', t->>'template', '')));
  if tid = '' then
    raise exception 'tenant template assignment missing' using errcode = '23514';
  end if;

  select value into strict x from public.app_config where key = 'template:' || tid;
  select value into strict s
    from public.app_config
    where key = 'tenant:' || p_tenant || ':service:' || svc;
  select value into strict d from public.app_config where key = 'device:' || p_device;

  if nullif(trim(coalesce(s->>'inherited_from_template', '')), '') is not null then
    s := s - 'mdr' - 'mdr_pos' - 'qris_mdr' - 'mdr_%';
  end if;

  return private.strip_legacy_tax_config(g || x || t || s || d);
exception
  when no_data_found then
    raise exception 'missing canonical five-layer app_config row' using errcode = '23514';
end;
$$;

revoke all on function public.get_effective_config(text, text, text) from public, anon;
grant execute on function public.get_effective_config(text, text, text) to authenticated, service_role;

commit;

DO $preflight$
